[65784] = { ["id"] = 65784, ["name"] = "The Otter Side", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65784 }, ["description"] = "To the northeast, there are a system of otter burrows along the bank. Some of the otters there are blessed by the river to grow to magnificent sizes. I will not have you hunting these blessings out of respect. Instead you will bring them back here, alive, so that we may treat them with the reverence they deserve.", ["objectivesText"] = "Bring 3 Gargantuan River Otters back to Clan Aylaag. Progress: Remember, they must be returned alive.", ["rewardXP"] = 2765, ["rewardItems"] = { 191989, 191990, 191993, 191994, 191995, 191996, 191999, 192002, 192003, 192004, 192005, 192008, 192011, 192012, 193568, 198505, 198539, 198542, 198627 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65789] = { ["id"] = 65789, ["name"] = "Where Rivers Sleep", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65789 }, ["description"] = "The Mirewood contains key reagents often used to converse with the ancestors. Unfortunately, the Mudfin tribe swarms the area, making it difficult for us to forage the area. If you could gather some of the blooms within the marsh, along with some of the Mudfin's own resources, I would appreciate it.", ["objectivesText"] = "Collect reagents from Mirewood Fen. Progress: Have you found everything?", ["rewardXP"] = 2765, ["rewardItems"] = { 191839, 191840, 191987, 191988, 191989, 191993, 191994, 191995, 191996, 192001, 192002, 192003, 192004, 192005, 192009, 192011, 193568, 198539, 198542, 198627, 200613 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65792] = { ["id"] = 65792, ["name"] = "Teeth for a Tooth", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65792 }, ["description"] = "Toliqui has been claiming that just the other day she killed a rockfang without any assistance. Given our connected souls, I don't want to call her as a liar. So instead... I want to prove to her, and everyone else, that I'm the better half of our soul! The nearest rockfang quest is to the northeast - meet me there!", ["objectivesText"] = "Slay 10 rockfangs with Toluijin . Progress: I cannot let Toliqui continue to leave me in her shadow.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191986, 191989, 191990, 191992, 191995, 191996, 191997, 191999, 192003, 192004, 192006, 192008, 192010, 192011, 192012, 192013, 192037, 193568, 198539, 198542, 198627 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185880, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185880, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.706667, ["y"] = 0.522667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65796] = { ["id"] = 65796, ["name"] = "The Best Defense...", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65796 }, ["description"] = "Our next path is through Nokhud territory. Historically, we have been at a tentative peace with their clan, but times have changed. If we do not act first, we leave ourselves open while we're vulnerable. My scouts have reported that one of their war leaders has been spotted near Dragonsmeet. Take the fight to her directly - do not let her gather the forces to assault us on the move.", ["objectivesText"] = "Slay Sirena the Fangbreaker . Progress: I cannot afford any mistakes. There are too many lives counting on me.", ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
[65798] = { ["id"] = 65798, ["name"] = "An Opportunistic Approach", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65798 }, ["description"] = "The Shikaar have formed an offensive line against the Nokhud to the north. While I do not like stooping to scavenging, it is unfortunately a necessary evil for our supplies. Brave the battlefield and return with weapons, and I will reward your efforts. If you could focus said efforts on the Nokhud side of the line, perhaps the ancestors will judge me less harshly.", ["objectivesText"] = "Retrieve weapons and slay Nokhud forces at the Nokhud Approach. Progress: Weapons will be the most useful thing - I apologize for asking this of you.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191989, 191992, 191995, 191997, 191999, 192003, 192006, 192007, 192008, 192011, 192013, 192028, 192029, 192030, 192031, 192032, 192033, 192034, 193568, 198539, 198542, 198627, 199477 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65837] = { ["id"] = 65837, ["name"] = "Trouble In The Pines", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65837 }, ["description"] = "There's been a primalist attack in the Shikaar Highlands. If you have information or think you can help, head over to Pinewood Post and look for Olekk. Tell him I sent you. <Tirren chuckles.> I sure hope the dusty hoofer remembers me. Keep to the roads, $p. The plains are not as peaceful since all this change arrived.", ["objectivesText"] = "Speak to Sentinel Olekk at Pinewood Post in the Ohn'ahran Plains .", ["rewardGold"] = 1745, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195524, ["x"] = 0.62, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190024, ["x"] = 0.825, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[65840] = { ["id"] = 65840, ["name"] = "Same as the Old Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65840 }, ["description"] = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.", ["objectivesText"] = "Eliminate Doventhal the Chosen . Progress: Are we ready for a new leader?", ["rewardXP"] = 1060, ["rewardItems"] = { 202173 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191304, ["x"] = 0.32, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191304, ["x"] = 0.32, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65842] = { ["id"] = 65842, ["name"] = "Disarming Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65842 }, ["description"] = "I have little love for the Worldbeaker dragonkin. They follow a misplaced belief that Deathwing himself will return one day, and they will not help us with the Obsidian Throne. Weaponmaster Vordak , who once swore loyalty to the Black Prince, has stolen many weapons crafted here in the Citadel and given them to the Worldbreakers. I will not allow such theft. Or such betrayal. Go to Smoldering Peak and recover the weapons... by force if necessary.", ["objectivesText"] = "Eliminate Weaponmaster Vordak and collect 15 Worldbreaker Weapons . Progress: Have you acquired the weapons?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191057, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192032, 192033, 192037, 193477, 197923, 197926, 197937, 197941, 197943, 197944, 197945, 197947, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[65865] = { ["id"] = 65865, ["name"] = "They've Got Us Pinned Down!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 65865 }, ["description"] = "These gnoll sharpshooters are ruthless... and surprisingly accurate. We cannot even consider heading into the Big Tree Hills while they have their weapons trained on us. Thin our their ranks and show them that we will not be used for target practice!", ["objectivesText"] = "Kill Gnoll Sharpshooters.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[65874] = { ["id"] = 65874, ["name"] = "A Rotten Revelation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 65874 }, ["description"] = "Hmm... <Brel peers intently at the strange totem, turning it over in her thick hands.> We've got to put our whiskers together and determine what this means.", ["objectivesText"] = "Speak with Hanu, Elder Poa, and Norukk.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[65875] = { ["id"] = 65875, ["name"] = "A Dragon's Day Off", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 65875 }, ["description"] = "A lifetime spent in Outland... always fighting. So little time to relax! Sometimes a dragon just needs a day off by the sea with a cold, cold drink in their claws. Hey, maybe you can help me relax! Do me a favor and see if you can find a few of these drinks to refresh our supply here.", ["objectivesText"] = "Locate the various drinks for Vazallia . Progress: Have fetched my beverages yet? No? That's too bad.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 109076, 191251, 191255, 191264, 192786, 193201, 195543, 197737, 197738, 197739, 197744, 198043, 198044, 198045, 198047, 198356, 198622, 199215, 201817, 201818, 201838, 202173 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192662, ["x"] = 0.202, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192662, ["x"] = 0.202, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
