[65896] = { ["id"] = 65896, ["name"] = "Let the Healing Begin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 65896 }, ["description"] = "Do you think you would be able to step into this city without me noticing? No! I was right about your kind before and I'll be damned before I let dragons destroy my home again. This once was a park filled with joy and peace. Then your progenitor, Deathwing, came. Oh yes, I know all about him. See for yourself the legacy of destruction that was left behind. The pain that walks these streets still.", ["objectivesText"] = "Help the people of Stormwind heal.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 190830, ["x"] = 0.444333, ["y"] = 0.594333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 194554, ["x"] = 0.4312, ["y"] = 0.6612 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.444333, ["y"] = 0.594333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[65906] = { ["id"] = 65906, ["name"] = "A Disgruntled Initiate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 65906 }, ["description"] = "I received an interesting letter from Ohn'iri Springs. As for the letter's contents, it details, quote, horrid imprisonment, controlling mentors, and extreme boredom. It is formally signed by Initiate Radiya . There's also a sketch of an eagle... kicking a centaur named Meluun off a cliff. Well. I suppose this is a call for help, if you are so inclined to see for yourself. To be frank, I think Radiya is probably okay. She sends me such letters often.", ["objectivesText"] = "Speak to Initiate Radiya at Ohn'iri Springs in the Ohn'ahran Plains .", ["rewardGold"] = 26210, ["rewardXP"] = 345, ["rewardItems"] = { 192743, 192799 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195302, ["x"] = 0.63, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 190014, ["x"] = 0.535778, ["y"] = 0.680889 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
