[66261] = { ["id"] = 66261, ["name"] = "A Minor Setback", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66261 }, ["description"] = "Ah, adventurer! Just the sort of well-armed individual I was hoping to encounter. I'm here in this literal backwater on very important Kirin Tor business, you see, and whilst I was beginning to set up my camp, I was chased off by filthy, mangy gnolls. In fact, a rather concerning number of gnolls have gathered nearby, enough that I believe they pose a threat to the wider Span. Fear not though, for I have a plan! Meet me in the lake just over there, and I'll explain everything.", ["objectivesText"] = "Reach Detry.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 187764, ["x"] = 0.21, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 187463, ["x"] = 0.226, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.21, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66308] = { ["id"] = 66308, ["name"] = "Feeding the Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66308 }, ["description"] = "The creation of new weapons and armor in the Earth-Warder's Forge will insure our eventual victory over the Djaradin. The flames of the forge though must be constantly kept fueled. Cindershard Coal will provide the strongest heat, necessary to forge weapons. You can find Cindershard Coal from deposits and Elementals within the Cindershard Seam.", ["objectivesText"] = "Collect 30 Cindershard Coal . Progress: Have you collected fresh Cindershard Coal ?", ["rewardXP"] = 1060, ["rewardItems"] = { 191659 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66321] = { ["id"] = 66321, ["name"] = "Bar Their Efforts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66321 }, ["description"] = "Djaradin forces are threatening an attack on our position. I can feel it down to my claws. We should strike first. Before they have a chance to mobilize! Go to the Burning Ascent and wreak havoc on the djaradin forces there.", ["objectivesText"] = "Djaradin forces eliminated. Progress: Have you weakened the djaradin forces?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191987, 191989, 191990, 191992, 191993, 191995, 191996, 191997, 191998, 191999, 192000, 192003, 192004, 192005, 192006, 192007, 192009, 192010, 192011, 192012, 192014, 192015, 192037, 193477, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66326] = { ["id"] = 66326, ["name"] = "The Tools of One's Trade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66326 }, ["description"] = "A forge of this power needs specialized tools--ones that can take the tremendous heat. But the djaradin have ransacked the place and stole many of the tools we need for this work. If you can, recover those tools from them, so that we may continue our efforts to arm our allies.", ["objectivesText"] = "Collect 1 Precision Scale Hammer , 1 Obsidian Bickern , 5 Blacksteel Tongs , and 10 Dragonclaw Punches. Progress: Have you found the tools we require?", ["rewardXP"] = 1060, ["rewardItems"] = { 190454, 191683, 191684, 191686, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192020, 192021, 192030, 192032, 192037, 193477, 194336, 197923, 197924, 197926, 197931, 197932, 197937, 197938, 197944, 197947, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
