[66351] = { ["id"] = 66351, ["name"] = "Smoke Over the Mountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66351 }, ["series"] = { 65421, 72524 }, ["description"] = "< Pathfinder Jeb looks at the mountain ridge beyond the camp and sniffs.> I don't like it. Pathfinder Yips should've been here days ago. Was gonna help me teach this new batch of explorers how to climb these pillars safely. Now I see smoke in the distance. I don't like it at all.", ["objectivesText"] = "Find Pathfinder Yip's plane.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 191138 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 181039, ["x"] = 0.624, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66363] = { ["id"] = 66363, ["name"] = "Basilisk Bucklers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66363 }, ["description"] = "Interlinked scales are the key to stopping an arrow. The bucklers we make are the best in the plains. However, I am short of basilisk hides for my next order. I see you are interested in learning about our crafts. Gather basilisk hides from around the Dragon Isles, and I will give you instruction on our techniques.", ["objectivesText"] = "Gather 20 Rigid Basilisk Hides from the basilisks of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Do you have the hides?", ["rewardXP"] = 1415, ["rewardItems"] = { 191780, 198106, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[66364] = { ["id"] = 66364, ["name"] = "To Fly a Kite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66364 }, ["description"] = "Let me tell you about an opportunity. The proto-drakes and proto-dragons have an amazing range of motion on their wings. And the ribbing! It is so extendable. We mostly make our kites from stretched hides. With the proto-drakes causing havoc, I was wondering if you could return some of their wings to me? I can make kites that would be the envy of the tribe.", ["objectivesText"] = "Gather 10 Fresh Proto-Dragon Wings from the proto-drakes and proto-dragons of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Do you have the wings?", ["rewardXP"] = 1415, ["rewardItems"] = { 191782, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
