[66426] = { ["id"] = 66426, ["name"] = "Running Out of Time", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66426 }, ["description"] = "I can feel the arcane surge growing as we speak. I suspect there is not much time before the ruins make Rannan's J.A.M. look like a distant star in the night sky. We have to get there and stop it. Please be careful, $p. Meet us by the east tower. We will assess the situation there.", ["objectivesText"] = "Reach the east tower.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 191265, 191909, 192110, 192475, 195207, 195209 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189236, ["x"] = 0.656, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189792, ["x"] = 0.684, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66442] = { ["id"] = 66442, ["name"] = "Let's Get Theoretical", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66442 }, ["description"] = "We now have four elemental orbs! Let us see which hypothesis proves fruitful.", ["objectivesText"] = "Help test the orbs against the Titan Barrier in Life Vault Ruins.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 191904, 192480, 192524, 192545, 192546, 192562 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190352, ["x"] = 0.663, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 197860, ["x"] = 0.665, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66445] = { ["id"] = 66445, ["name"] = "Honor Our Fallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66445 }, ["description"] = "The djaradin have no regard for the sanctity of the Citadel or the bodies of our kin! They break the bones of the dead and take their personal keepsakes as souvenirs. This disrespect cuts at the heart of every proud black dragon. They deserve honor. Recover these items that the djaradin have stripped from the bodies of our fallen.", ["objectivesText"] = "Recover 8 Fallen Defenders Ring, 3 Earth-Warder's Flame Blade and 1 Horn of Scorxia Progress: Have you recovered the items of the fallen?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 29108, 29109, 190454, 191902, 191908, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192020, 192024, 192031, 192033, 192037, 193477, 194544, 197923, 197931, 197932, 197937, 197939, 197941, 197942, 197943, 197955, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243, 237812 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66448] = { ["id"] = 66448, ["name"] = "The Wayward Waywatcher", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66448 }, ["series"] = { 66100, 71219 }, ["description"] = "The Waywatchers have kept the roads of Thaldraszus safe for travelers for as long as I can remember. It is a duty that my family has upheld with honor for generations. Alas, my sister Alvi seems less than interested in that honor of late. She is supposed to report to me here each morning, but I have not heard from her in over a day. If you find a bronze drakonid east of here, lazing about with her head in the clouds, I ask that you direct her to me. Otherwise, I will have to seek her out myself.", ["objectivesText"] = "Find Waywatcher Alvi .", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 187202, ["x"] = 0.546, ["y"] = 0.685333 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191753, ["x"] = 0.546, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.685333 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66449] = { ["id"] = 66449, ["name"] = "Hands-Off Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66449 }, ["description"] = "Qalashi dustbinders are trying to imprison our whelps. It seems their leader is planning to use them for some nefarious purpose. We cannot let this happen! But the djaradin are not the only enemy here. Phoenixes are also tracking our whelps, presenting even more danger. You must protect the the whelps and eliminate the enemies that threaten them. Osoria will assist you.", ["objectivesText"] = "Save 8 Endangered Whelps while eliminating 12 Searclaw Phoenixes and Ashbinder Tornecha . Progress: Have you eliminated the threats?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192033, 192037, 193477, 194519, 197926, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66484] = { ["id"] = 66484, ["name"] = "Know Your Enemy: Proto-Dragons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 66484 }, ["description"] = "The area is crawling with those powerful beasts! Conveniently. the Surveying Scope has allowed you to spot a few weak spot in their tough scale. You can also devise a few tricks to avoid their sharp claws and fangs.", ["objectivesText"] = "Hunt down a few Proto-Dragons around the Apex Canopy.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[66504] = { ["id"] = 66504, ["name"] = "A Shard of Crystalized Mana", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 66504 }, ["description"] = "<The small blue crystal vibrates lightly when touched, then produces a low tune that sounds like a distant song. You can hear the words echoing like a soft melody in your head.> Lathos may find it interesting.", ["objectivesText"] = "Take the crystal to Lathos.", ["rewardGold"] = 26210, ["rewardXP"] = 515, ["rewardItems"] = { 191633 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 191633 } },
[66509] = { ["id"] = 66509, ["name"] = "Paranoid 1", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 66509 }, ["description"] = "Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.", ["rewardGold"] = 84900, ["rewardXP"] = 1385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[66511] = { ["id"] = 66511, ["name"] = "Renowned with the Iskaara Tuskarr", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66511 }, ["description"] = "You continue to show us that you are an integral member of our community. To honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.", ["objectivesText"] = "Speak with Murik in Iskaara.", ["rewardItems"] = { 199473, 204379 }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2551, ["threshold"] = 7500 } } } },
[66516] = { ["id"] = 66516, ["name"] = "Mundane Gems, I Think Not!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66516 }, ["description"] = "It's such a waste. The djaradin of this land use powerful gems as mundane decorations. Mere jewelry! Gems have so many uses: telescopes, mirrors, focusing pointers, not to mention the myriad magical properties they possess. We must rectify this situation, explorer. Relieve the djaradin of their gems, and bring them back to me. I'll make sure they're put to better use! Be careful though--the djaradin are fierce warriors.", ["objectivesText"] = "Gather 25 'Mundane' Gems from the djaradin of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Were you able to get the gems?", ["rewardXP"] = 1415, ["rewardItems"] = { 192125, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[66517] = { ["id"] = 66517, ["name"] = "A New Source of Weapons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66517 }, ["description"] = "These Sundered Flame pose a great threat to our borders. Their weapons are concerning. Gather what you can of their weapons--we can study them for any weaknesses, and even use them for our own defenses. I have faith in you, outsider. If you perform this task for us, I will teach you some of our own blacksmithing arts.", ["objectivesText"] = "Gather 25 Intact Dracthyr Weapons from the Sundered Flame of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: What were you able to secure?", ["rewardXP"] = 1415, ["rewardItems"] = { 192126, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
