[66611] = { ["id"] = 66611, ["name"] = "Clearing the Skies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 66611 }, ["description"] = "Can you hear that? Bugs! All around. Some of them are getting pretty big. Why don't you and your gliding friend use the thermal behind me and do something about it?", ["objectivesText"] = "Kill 50 insects.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[66633] = { ["id"] = 66633, ["name"] = "Make a Statement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66633 }, ["description"] = "These djaradin believe the black dragonflight is finished. They don't fear or respect Wrathion's authority here. We need a statement to remind them that the obsidian flight has returned, and that we are stronger than ever. Slay the djaradin and mark each corpse so they don't forget who rules here.", ["objectivesText"] = "Plant a black dragon banner into the corpses of 12 djaradin.", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192020, 192023, 192024, 192025, 192031, 192033, 192037, 193477, 193915, 197922, 197923, 197924, 197926, 197927, 197941, 197943, 197947, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
