[66698] = { ["id"] = 66698, ["name"] = "Counting Argali", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66698 }, ["description"] = "One of our key resources is our argali herd. Every loss is felt deeply for the strength of our clan. A few of the argali have gotten separated and have wandered away from the herd. Our shepherds could use your assistance reclaiming them.", ["objectivesText"] = "Speak with the Aylaag Shepherd and return the lost sheep to the clan. Progress: Have you reunited the herd?", ["rewardXP"] = 2765, ["rewardItems"] = { 191986, 191988, 191990, 191992, 191994, 191996, 191998, 192001, 192002, 192004, 192008, 192009, 192012, 192016, 192017, 192018, 192022, 192023, 198542, 198627 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[66708] = { ["id"] = 66708, ["name"] = "Riders in the Snow", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66708 }, ["series"] = { 66709 }, ["description"] = "Greetings, <class>. This magical dome is truly astonishing, is it not? But even though it protects us from the biting cold and the wilderness, we cannot count on the Kirin Tor forever. A few days ago, some of our most seasoned hunters ventured into the forests looking for food and supplies, but they never came back. Even though I know their leader, Old Grimtusk , is a seasoned hiker and hunter, it is very hard not to worry about him and his hunting party. Can you find them for me?", ["objectivesText"] = "Find the missing tuskarr hunters in the Azure Span .", ["rewardGold"] = 42450, ["rewardXP"] = 1030, ["rewardItems"] = { 193617 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190300, ["x"] = 0.658, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 189963, ["x"] = 0.586667, ["y"] = 0.402667 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[66711] = { ["id"] = 66711, ["name"] = "Delicacy in the Dark", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 66711 }, ["description"] = "Due to the nature of our clan, some resources are in short supply. We do not have the luxury of time to claim the land's metal resources. The late khan established multiple trade connections with a variety of individuals, and I see no reason to discontinue their services. The nearby bay contains buckets where we catch whelks - they're considered a delicacy for some of our neighbors. Bring a collection back to me for use in trade.", ["objectivesText"] = "Collect 12 river whelks for Hadari. Progress: Take care with the traps, they may contain some more aggressive nuisances.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191989, 191991, 191995, 191998, 191999, 192003, 192007, 192008, 192010, 192011, 192014, 192015, 192037, 192603, 193568, 198539, 198542, 198627 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
