[66856] = { ["id"] = 66856, ["name"] = "Becca Black and the Seven Gnomes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66856 }, ["description"] = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts. Wrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", ["objectivesText"] = "Recover the missing artifacts. Progress: Have you found everything on the list?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191984, 191989, 191991, 191992, 191993, 191995, 191996, 191998, 192000, 192001, 192004, 192005, 192006, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192037, 193477, 193625, 193626, 193627, 195881, 197931, 197939, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191014, ["x"] = 0.322, ["y"] = 0.654 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191014, ["x"] = 0.322, ["y"] = 0.654 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.654 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66858] = { ["id"] = 66858, ["name"] = "Tour the Trading Post", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 66858 }, ["description"] = "<A flyer, carried by the wind, flaps into your hands.> Fancy yourself a collector, trader, or adventurer? We've travelled all over Azeroth collecting goods of the finest quality for someone exactly like you! Visit one of our outposts in Stormwind or Dornogal and browse all the latest goods! --T&W Trading Post <You squint to read the fine print.> Be sure to present this flyer for some extra Trader's Tender !", ["objectivesText"] = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post. Progress: Welcome to the Tradin' Post! We've got goods from all over Azeroth for ye to collect. Would ye like to take a look?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 54811, 189871, 189897, 189898, 190071, 190143, 190231, 190434, 190599, 190799, 190846, 190855, 190856, 202167, 202170 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 185468, ["x"] = 0.51, ["y"] = 0.718 }, { ["mapID"] = 2339, ["npcID"] = 219244, ["x"] = 0.445, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 84, 2339 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 52 },
