[66884] = { ["id"] = 66884, ["name"] = "Fireproof Gear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66884 }, ["description"] = "The armor of the djaradin can withstand even the fiercest flames. Such qualities would be of great use in combating them! See what you can gather from the djaradin. We can study it, and apply the same enchantments to our own armor.", ["objectivesText"] = "Gather 10 Fireproof Gear from the djaradin of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Were you able to gather any armor?", ["rewardXP"] = 1415, ["rewardItems"] = { 193624, 198610 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
[66890] = { ["id"] = 66890, ["name"] = "Stolen Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66890 }, ["description"] = "We have been plagued by gnolls raiding our supply caravans. They appear to be obsessed with the various engineering tools within. We cannot risk these violent raiders figuring out our specialized art! Also, these thefts have set our production schedule back more than I'd like to admit. If you can retrieve some of the stolen engineering parts, we can get back on schedule.", ["objectivesText"] = "Gather 20 Stolen Tools from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Have you retrieved the stolen tools ?", ["rewardXP"] = 1415, ["rewardItems"] = { 193836, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[66891] = { ["id"] = 66891, ["name"] = "Explosive Ash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66891 }, ["description"] = "The molten phoenixes in the Dragon Isles create an unusual ash substance once they die. It could be used to create some material improvements for some complex, life-changing machinery. Though I would probably use it for explosives.", ["objectivesText"] = "Gather 20 Explosive Ash from the phoenixes of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you found enough ash?", ["rewardXP"] = 1415, ["rewardItems"] = { 193839, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[66894] = { ["id"] = 66894, ["name"] = "Same as the Old Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66894 }, ["description"] = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.", ["objectivesText"] = "Eliminate Aizir the Inflamed . Progress: Are we ready for a new leader?", ["rewardXP"] = 1060, ["rewardItems"] = { 202173 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191307, ["x"] = 0.32, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191307, ["x"] = 0.32, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66895] = { ["id"] = 66895, ["name"] = "Same as the Old Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66895 }, ["description"] = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing. However, Deathwing has not returned, and still there is no Twilight. It is time for a new leader. You can help bring about the change.", ["objectivesText"] = "Eliminate Vyzos the Prophet . Progress: Are we ready for a new leader?", ["rewardXP"] = 1060, ["rewardItems"] = { 202173 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191310, ["x"] = 0.32, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191310, ["x"] = 0.32, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[66896] = { ["id"] = 66896, ["name"] = "Net Income", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66896 }, ["objectivesText"] = "Collect 10 Warmwater Riverfish and 6 Succulent Snapper Meat.", ["rewardXP"] = 1415, ["rewardItems"] = { 85500, 192191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Warmwater Riverfish caught", ["amount"] = 10, ["type"] = 0, ["objectID"] = 198397, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[66897] = { ["id"] = 66897, ["name"] = "Fuel for the Forge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66897 }, ["description"] = "To make the best blades, you need the heat that only a Magma Core can provide. We try to keep a few on hand as a fuel source for our forges. Lately, we've been running low on cores and could use a resupply. Magma Cores are obtainable from most lava creatures in the Dragon Isles.", ["objectivesText"] = "Gather 10 Magma Cores from the lava creatures of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you gathered the Magma Cores ?", ["rewardXP"] = 1415, ["rewardItems"] = { 193864, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[66899] = { ["id"] = 66899, ["name"] = "Fuzzy Legs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66899 }, ["description"] = "We have received a request for \" Fuzzy Legs \" for tailoring... Don't look at me, I don't make the requests, I just pass them on. I imagine the legs of tarantulas would fulfill this request.", ["objectivesText"] = "Gather 20 Fuzzy Legs from the tarantulas of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you gathered the Fuzzy Legs ?", ["rewardXP"] = 1415, ["rewardItems"] = { 193865, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[66900] = { ["id"] = 66900, ["name"] = "Enchanted Relics", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66900 }, ["description"] = "Ah, the tides have brought you at just the right time! Gnolls have stolen some of our relics. These are more precious than most--they have been enchanted. We cannot allow the gnolls to learn our magics! Someone of your skill should have no issue identifying the stolen relics. Please, will you lend us your aid?", ["objectivesText"] = "Gather 10 Enchanted Relics from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you retrieved the relics?", ["rewardXP"] = 1415, ["rewardItems"] = { 193867, 198610 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
