[66929] = { ["id"] = 66929, ["name"] = "Gotta Collect Them All", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 66929 }, ["description"] = "$PC, do you mind helping me get my cards back? I told Setogosa I need them to show other students how to play Hearthstone. I want to form a club, but she's not giving them back! She's always been rude to me, but this is taking it further than normal.", ["objectivesText"] = "Get Yumadormu 's deck back. Progress: I got a few of the cards out myself, have you gotten the rest yet?", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 194033 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 191414, ["x"] = 0.592, ["y"] = 0.4236 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191414, ["x"] = 0.592, ["y"] = 0.4236 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.4236 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[66934] = { ["id"] = 66934, ["name"] = "Break the Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 66934 }, ["objectivesText"] = "Qalashi Supplies destroyed", ["rewardGold"] = 154900, ["rewardXP"] = 1415, ["rewardItems"] = { 25701, 25702, 25710, 25711, 147469, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Qalashi Supplies destroyed", ["amount"] = 5, ["type"] = 0, ["objectID"] = 195921, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[66937] = { ["id"] = 66937, ["name"] = "Decaying News", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66937 }, ["description"] = "The gnolls and their use of decay magic are concerning. We need to gather as much knowledge as we can, in case the threat escalates. As alchemists, we are used to gathering such foul substances safely--plus, we're used to the smell. Will you lend your aid?", ["objectivesText"] = "Gather 10 Rotting Samples from the decay gnolls of the Dragon Isles for Dothenos of the Valdrakken. Progress: Have you gathered the Rotting Samples ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194103, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[66938] = { ["id"] = 66938, ["name"] = "Mammoth Marrow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66938 }, ["description"] = "Creating new and unusual brews is one of our many specialties. While we do enjoy experimenting with new and fascinating ingredients, we have a few common ingredients that we keep in stock. One of these ingredients is the marrow from mammoth tusks. We have run short on marrow and would appreciate your help in collecting more for our alchemists.", ["objectivesText"] = "Gather 20 Tusk Marrow from the mammoths of the Dragon Isles for Dhurrel of the Maruuk Centaur. Progress: Have you gathered enough Tusk Marrow ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194424, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[66940] = { ["id"] = 66940, ["name"] = "Elixir Experiment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66940 }, ["description"] = "Our alchemists have recently looked into a variety of new ingredients for experimentation. Their most recent interest is... interesting... to say the least. It appears that gorloc mucus has some properties that can be beneficial for certain elixirs.", ["objectivesText"] = "Gather 15 Gorloc Mucus from the gorlocs of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you gathered the mucus from the gorlocs?", ["rewardXP"] = 1415, ["rewardItems"] = { 194427, 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[66941] = { ["id"] = 66941, ["name"] = "Tremendous Tools", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66941 }, ["description"] = "The djaradin have some mighty large tools and weaponry. We can easily find a use for such tools, even if only to smelt them down into more tools for ourselves. Bring back some djaradin tools for us to study and use.", ["objectivesText"] = "Gather 10 Large Tools from the djaradin of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Did you find the djaradin and collect some of their tools?", ["rewardXP"] = 1415, ["rewardItems"] = { 194435, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[66942] = { ["id"] = 66942, ["name"] = "Enemy Engineering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66942 }, ["description"] = "It may be a bit controversial, but I believe that we can study the rituals of the Primalists to learn new ways to channel elemental power. I'm confident that once we understand the pathways of their magic, we can use it to create all sorts of innovative engineering products.", ["objectivesText"] = "Gather 10 Primal Rituals from the Primalists of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Did you find some Primal Rituals ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194437, 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[66943] = { ["id"] = 66943, ["name"] = "Wood for Writing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66943 }, ["description"] = "We've found some unusual information in our studies of the Dragon Isles. For instance, the bark of treants afflicted by decay magic acts similarly to hide parchment. This odd parchment is strangely able to hold the magic for more powerful inscriptions. Very useful! Can you help us gather some?", ["objectivesText"] = "Gather 15 Bark Parchment from the decay treants of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Were you able to retrieve any bark?", ["rewardXP"] = 1415, ["rewardItems"] = { 194332, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[66944] = { ["id"] = 66944, ["name"] = "Peacock Pigments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66944 }, ["description"] = "The peacocks of the Dragon Isles have such colorful feathers! I bet we can make some pigments from them for our scribes to use as ink.", ["objectivesText"] = "Gather 8 Peacock Feathers from the peacocks of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you gathered the Peacock Feathers ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194321, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[66945] = { ["id"] = 66945, ["name"] = "Icy Ink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66945 }, ["description"] = "The icy beasts in the frozen biomes excrete a very rare and mysterious liquid. The liquid's properties make it the perfect binding agent for our inks. I'm a southpaw so the prospect of not smudging my page is very exciting to me.", ["objectivesText"] = "Gather 20 Icy Excrement from the ice spiders and ice bears of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Have you gathered the Icy Excrements ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194451, 198607 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[66949] = { ["id"] = 66949, ["name"] = "Trinket Bandits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66949 }, ["description"] = "The gnolls have quite a collection of trinkets. Tuskarr trinkets. They have either stolen them from our villages, or worse, from the brave tuskarr that fell in battle against them. These trinkets are our heritage and should reside with us. If you bring some back to me, I will teach you the techniques that are used to make them.", ["objectivesText"] = "Gather 10 Stolen Trinkets from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you retrieved the Stolen Trinkets from the gnolls?", ["rewardXP"] = 1415, ["rewardItems"] = { 194443, 198612, 201421, 201422, 201454 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[66950] = { ["id"] = 66950, ["name"] = "Heart of a Giant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66950 }, ["description"] = "There are various giants within the Dragon Isles that are rumored to contain beautiful gems at their core. We normally don't hunt the creatures of the Isles for treasures, but these giants have caused quite a bit of havoc. We may as well collect these gems in the process of clearing out the destructive giants.", ["objectivesText"] = "Gather 5 Giant Cores from the mountain, ice, or molten giants of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you found any gems from within the giants?", ["rewardXP"] = 1415, ["rewardItems"] = { 194449, 198612 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[66951] = { ["id"] = 66951, ["name"] = "Population Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66951 }, ["description"] = "Recently there has been an overpopulation of a few different species on the Dragon Isles. In particular, the rockfang and the bruffalon. We don't want to be wasteful, of course. Be sure to collect as much of the hides as you can from the creatures.", ["objectivesText"] = "Gather 25 Salvaged Hides from the rockfang and bruffalon of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you dealt with the overpopulation and brought back some hides?", ["rewardGold"] = 619600, ["rewardXP"] = 1415, ["rewardItems"] = { 194448, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[66952] = { ["id"] = 66952, ["name"] = "The Gnoll's Clothes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66952 }, ["description"] = "The gnolls are a constant threat, launching bloody raids and attacks against the expeditions and peoples of the Dragon Isles. So how are their clothes so clean? After your battles with these raiders, could you collect a sample of their worn cloth for me to analyze?", ["objectivesText"] = "Gather 20 Gnoll-Worn Cloth from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Did you bring the Gnoll-Worn Cloth ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194328, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[66953] = { ["id"] = 66953, ["name"] = "All Things Fluffy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66953 }, ["description"] = "The tailors are always anxious to get their hands on that fluffy argali fur. The wool is especially useful for surviving in the freezing cold mountains of the Dragon Isles.", ["objectivesText"] = "Gather 20 Fluffy Fur from the argali of the Dragon Isles for Dothenos of the Valdrakken. Progress: Did you get some of that Fluffy Fur ?", ["rewardXP"] = 1415, ["rewardItems"] = { 194450, 198609 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[66959] = { ["id"] = 66959, ["name"] = "Tour the Trading Post", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 66959 }, ["description"] = "<A flyer, carried by the wind, flaps into your hands.> Rare antiquities from every corner of Azeroth! Fine goods fit for any taste! You will not find these unique treasures anywhere else, friend. Come see us at one of our outposts in Orgrimmar or Dornogal and gaze in wonder upon the mysteries in store for you! --Zen' shiri Trading Post <You squint to read the fine print.> Be sure to present this flyer for some extra Trader's Tender !", ["objectivesText"] = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post. Progress: Welcome to the Trading Post. We have goods from all over Azeroth here for your collectin'. Please, take a look.", ["rewardGold"] = 328500, ["rewardXP"] = 200, ["rewardItems"] = { 54811, 189871, 189897, 189898, 190071, 190143, 190231, 190434, 190599, 190799, 190846, 190855, 190856, 202167, 202170 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 185472, ["x"] = 0.488, ["y"] = 0.764 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.764 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 52 },
[66964] = { ["id"] = 66964, ["name"] = "Artifacts in the Wrong Hands", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 66964 }, ["description"] = "We've got a myriad, no, an incalculable number of problems here! Oh man, where to start! The Kirin Tor uncovered a Sundered Flame plot. They're after an artifact called \"Valthrux\". It's immensely powerful and... sentient? That's an exponential increase in danger if you're keeping track. One Alia Sunsoar went south with a pair of tuskarr to investigate the Sundered Flame. She should have been back by now. Please find her and stop the Sundered Flame from acquiring the artifact!", ["objectivesText"] = "Locate Alia Sunsoar in the Lost Ruins within Azure Span.", ["rewardGold"] = 24100, ["rewardXP"] = 515, ["rewardItems"] = { 194747, 195468, 199928, 200067, 200110 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 196545, ["x"] = 0.658, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 196254, ["x"] = 0.672, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
