[67004] = { ["id"] = 67004, ["name"] = "Good Things in Large Boxes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67004 }, ["description"] = "Our efforts have created everything we need to open an Earth-Warder's Vault . There are several beneath the Citadel. Locate one and I will reward you. I have crafted chains to help move it. If you bring the Vault here, we can share in the riches. Watch for the Vault being moved, as I have dispatched others to find them as well.", ["objectivesText"] = "Locate an Earth-Warder's Vault for me. If you bring it back, we can share in the loot. Progress: Have you found the Vault?", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 191264, 192055, 201991 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188179, ["x"] = 0.247, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
