[67034] = { ["id"] = 67034, ["name"] = "Of Wind and Water", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67034 }, ["description"] = "To the east is a great dragonspring which serves as a nesting area for wild eagles. The feathers they shed still contain their magic for quite some time and are used in many rituals. The area also hosts raging spirits of the elements, and their cores are of some use as well. Bring a collection of both back to me - and remember that the eagles are sacred, I will not accept feathers that are gathered from their harm.", ["objectivesText"] = "Collect reagents from the Roaring Dragonsprings. Progress: Have you found everything?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 118151, 118152, 118153, 119066, 119074, 191983, 191984, 191986, 191989, 191991, 191992, 191993, 191995, 191997, 191998, 191999, 192000, 192001, 192003, 192005, 192006, 192007, 192010, 192011, 192013, 192015, 192019, 192020, 192024, 192025, 192037, 193568, 194452, 194509, 197942, 197943, 197945, 197947, 197953, 197954, 197955, 197956, 197957, 198539, 198542 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185867, ["x"] = 0.66, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[67039] = { ["id"] = 67039, ["name"] = "An Amazing Journey", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67039 }, ["description"] = "A few of the clan's pets ended up getting lost along the last journey between camps. They're not hunting animals so I doubt they can take care of themselves properly out there! Do you think you could go search for them? They may not be hunting partners, but they're important members of the clan regardless!", ["objectivesText"] = "Find the missing animals. Progress: Did you find them? Their partners are becoming increasingly concerned.", ["rewardXP"] = 2765, ["rewardItems"] = { 191988, 191994, 191995, 192000, 192001, 192002, 192005, 192009, 192010, 192011, 192014, 192015, 192037, 193568, 197939, 198539, 198542, 198627 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185881, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185880, ["x"] = 0.706667, ["y"] = 0.522667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.706667, ["y"] = 0.522667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
