[67051] = { ["id"] = 67051, ["name"] = "Dragon Eyes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67051 }, ["description"] = "We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious. I have dispatched three dragons to survey the surrounding area and pinpoint any potential threats. Meet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.", ["objectivesText"] = "Speak with Baskilan, Vazallia, and Zepharian in the nearby areas. Progress: What have you discovered?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 194546, 194559, 194561, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
