[67080] = { ["id"] = 67080, ["name"] = "Artisan's Supply: Dragon's Alchemical Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67080 }, ["description"] = "Are you looking for work, alchemist? The Artisan's Consortium has reached out to me with a \"crafting order\" for my alchemical solutions. I am as curious as the next dragonkin to find out more about these business practices, but I am simply too busy. Perhaps this is an opportunity for you, my apprentice. Create some alchemical solution by reclaiming your earlier concoctions, and bring it to Haephesta , just down the path.", ["objectivesText"] = "Use the Reclaim Concoctions recipe to create 2 bottles of Dragon's Alchemical Solution for Haephesta at the Ruby Lifeshrine. Progress: How can the Artisan's Consortium help you today?", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 191462, 191570 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191893, ["x"] = 0.602, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192498, ["x"] = 0.578, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
