[67178] = { ["id"] = 67178, ["name"] = "White Eyes, Blue Dragon", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 67178 }, ["description"] = "$PC can you make sure the match happens as fairly as possible? Setogosa is known for bending the rules to suit her whims. I would not wish to see Yumadormu lose due to cheating.", ["objectivesText"] = "Help Yumodormu defeat Setogosa .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 192733, ["x"] = 0.58, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 191414, ["x"] = 0.592, ["y"] = 0.4236 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[67221] = { ["id"] = 67221, ["name"] = "A Head for Metal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 67221 }, ["description"] = "To fully utilize the potential of the Earth-Warder's forge, you must learn the basics of creating Obsidian Seared Alloy. Only then can you follow in the footsteps of Neltharion's greatest smiths. Bring me a piece of Crystallized Draconium found deep within the Cindershard Seam. Then I shall gift you the knowledge you desire.", ["objectivesText"] = "Collect 1 Crystallized Draconium inside the Cindershard Seam. Progress: Have you gathered what I require?", ["rewardGold"] = 74100, ["rewardXP"] = 1415, ["rewardItems"] = { 191251, 191264, 193201, 194963, 194971 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191194, ["x"] = 0.245, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191194, ["x"] = 0.245, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[67222] = { ["id"] = 67222, ["name"] = "Darkened Clouds", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67222 }, ["description"] = "The Primalists have infected Windsong Rise with their nonsense teachings. Our kin there are foolish to entertain their ideas. If we assist with clearing this sacred ground of their presence, perhaps the other clans will come to our aid in time of need. Do you think you could assist?", ["objectivesText"] = "Clear out the Primalist presence from Windsong Rise.", ["rewardXP"] = 2765, ["rewardItems"] = { 191983, 191984, 191986, 191987, 191989, 191991, 191992, 191993, 191995, 191998, 191999, 192000, 192001, 192003, 192005, 192006, 192007, 192008, 192010, 192011, 192013, 192014, 192015, 192037, 193568, 198539, 198542 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185853, ["x"] = 0.660667, ["y"] = 0.484667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.660667, ["y"] = 0.484667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[67605] = { ["id"] = 67605, ["name"] = "Thundering Plains", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 67605 }, ["description"] = "There is a great storm beast which wanders this ridge. Many a Shikaar hunter has attempted to take it down, only to fall to its ferocity. If you wish for some hunting glory, you may attempt to bring down the beast. Bring back its horn as tribute.", ["objectivesText"] = "Claim Ayanga's horn . Progress: So, have you seen the beast?", ["rewardXP"] = 3455, ["rewardItems"] = { 195386 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "group" },
