[69918] = { ["id"] = 69918, ["name"] = "Shaking Our Foundations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 69918 }, ["description"] = "Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped! We haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen. Do what you can, <name>... by that I mean kill them!", ["objectivesText"] = "Slay Stonewrecker Tokara , Molka the Grinder , and the elementals they have unleashed. Progress: Have you saved the foundation of this Citadel?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192020, 192021, 192033, 192037, 193477, 197923, 197926, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
