[70126] = { ["id"] = 70126, ["name"] = "A Finishing Touch", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 70126 }, ["description"] = "Ah, $p, good to see you. You've been an exceptional help for the Artisan's Consortium, and to Thomas and myself personally. Thank you. There is one more thing you should know as a crafter, and that's building a rapport with your clients. I filled a crafting order for a customer today. Could you talk to him for me? Try to convince him to come to me for his future crafting needs. Remind him that he needs to come to me personally if he wants high-quality goods.", ["objectivesText"] = "Convince Miguel's customer to entrust him with future crafting orders. Progress: That's the secret, <name>: it's the little acts of kindness that add up in a relationship.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 132331, 132332, 132333, 191513, 191516, 191519, 191529, 192896, 193952, 193958, 194124, 197765, 198218 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192539, ["x"] = 0.598, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192539, ["x"] = 0.598, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
