[70446] = { ["id"] = 70446, ["name"] = "A Personal History", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70446 }, ["description"] = "In delving into the archives here, I've found threads that point towards the Obsidian Observatory as a place of personal importance to the Earth-Warder. I can only guess what knowledge it may contain about the history of our flight. Given Emberthal's interest in the subject, I informed her of my discovery. I pray that wasn't a mistake. She has gone ahead to scout. Please, keep an eye on her. She is a competent soldier, but this subject is... troubling. Who knows what truths you may uncover.", ["objectivesText"] = "Meet Emberthal at the Obsidian Observatory.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193456, ["x"] = 0.25, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 196253, ["x"] = 0.446, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70450] = { ["id"] = 70450, ["name"] = "Otter Devastation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70450 }, ["description"] = "Hey there, friend. These here ottuks keep stealin' my catch! Personally, I'd blow 'em up, but our Tuskarr friends don't seem too keen on that action. I made this here Ottuk Deterent Device MK-SH4RK, but... I aint a great swimmer. You seem like you got the goods, why don't ya do us all a favor, activate the device, swimmy-swim around over there, and scare 'em off?", ["objectivesText"] = "Scare off the Pesky Ottuks. You may unlock only one extra fishing net per day. Progress: You get rid of them pesky ottuks yet?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 85500, 133755, 194701 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 195444, ["x"] = 0.636, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 195444, ["x"] = 0.636, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70501] = { ["id"] = 70501, ["name"] = "License to Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70501 }, ["description"] = "Ah, finally ready to prove yourself as a hunter? Keep in mind this is not as simple as running around and hunting everything that moves. The Shikaar hunt with purpose. We hunt to feed and clothe the clan, to prove our strength against mighty foes, and to balance nature. We do not hunt the land barren, we sow the seeds for future Grand Hunts as we go. Prove yourself capable of following these instructions and you may join us. However I do not have confidence in your friend there succeeding.", ["objectivesText"] = "Complete the Grand Hunt training tasks. Progress: Have you completed your training?", ["rewardGold"] = 280900, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195454, ["x"] = 0.64, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195454, ["x"] = 0.64, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
