[70871] = { ["id"] = 70871, ["name"] = "Iskaaran Fishing Net", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 70871, 70936, 70939, 70940, 70941, 70942, 70943, 70944, 70945, 70948, 70950, 70952, 70953, 70954, 70955, 70956, 70959, 70960, 70961, 70962, 70963, 70964, 70966, 70967, 70968, 70969, 70971, 70972, 70976, 70977, 70978, 72279, 72280, 72281, 72291, 72292, 72318, 72319, 72320, 72321, 72322, 72323, 72324, 72325, 72326, 72327, 72385, 72386, 72387, 72388, 72389, 72390, 72391, 72392, 72393, 72394, 72395, 72584, 72632, 72633, 72634, 72635, 72636, 72637, 72638, 72639, 72640, 72641, 72642, 72875 }, ["description"] = "I see you're getting along with the villagers. You seek to learn more about our ways of fishing you say? Well, first of all no one fishes with their bare hands. I can craft you a good, strong net worthy of an Iskaaran.", ["objectivesText"] = "Bring Tavio materials and let her craft an Iskaaran fishing net. Progress: Have you found suitable materials? I need strongest vines of kelp, and some good stones with holes in them.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 194510, 199694, 199695, 199696, 199697, 199698, 199844, 199846, 199848, 199850, 199924, 199925, 200075, 200076, 200077, 200078, 200079, 200080, 200081, 200082, 200083, 200084, 200085 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 195935, ["x"] = 0.128, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.128, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 1382, ["name"] = "Iskaara Tuskarr Renown", ["orderIndex"] = 6, ["flags"] = 0 } } },
[70873] = { ["id"] = 70873, ["name"] = "Chasing Waterfalls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 70873 }, ["description"] = "The real threat lies in the Emberslate Cavern. This is where they carve those runestones and infuse them with primal fire. No doubt you noticed the blazing wall of flame that blocks the entrance. I cannot dispel it, however I may be able to do something to help. I believe that with the proper application of Fallingwater, we can pass through it safely. Harvest water motes from the nearby elementals.", ["objectivesText"] = "Harvest 35 Fallingwater Motes . Progress: We will need those motes to get you safely into the Emberslate Cavern.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 200087, 200273, 200461, 200462, 200463 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 196562, ["x"] = 0.426, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 196562, ["x"] = 0.426, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[70877] = { ["id"] = 70877, ["name"] = "A Quack in Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70877 }, ["description"] = "<This duckling is despondent, quietly quacking to itself as its eyes dart around in fear.> <Maybe the ecologists would know how to help it?>", ["objectivesText"] = "Bring the Bubbled Duckling back to the Ecologists' Camp. Progress: <Tharu coos at the bubbled duckling .> Shh, don't cry, little one. Us big strong ecologists will keep you safe! And <name> too, of course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196744, ["x"] = 0.8, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
