[70917] = { ["id"] = 70917, ["name"] = "A Shoulder to Quack On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70917 }, ["description"] = "<This duckling is full of nervous energy. It seems eager to escape its current predicament.> <Maybe the ecologists would know how to help it?>", ["objectivesText"] = "Bring the Bubbled Duckling back to the Ecologists' Camp. Progress: <Tharu coos at the bubbled duckling .> Shh, don't cry, little one. Us big strong ecologists will keep you safe! And <name> too, of course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196746, ["x"] = 0.815, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.815, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[70919] = { ["id"] = 70919, ["name"] = "Quacking Out for a Hero", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70919 }, ["description"] = "<This duckling has been bubbled so long that it's fallen fast asleep. It quacks softly as it snores.> <Maybe the ecologists would know how to help it?>", ["objectivesText"] = "Bring the Bubbled Duckling back to the Ecologists' Camp. Progress: <Tharu coos at the bubbled duckling .> Shh, don't cry, little one. Us big strong ecologists will keep you safe! And <name> too, of course.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 196747, ["x"] = 0.828, ["y"] = 0.426 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 186428, ["x"] = 0.745, ["y"] = 0.421 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.426 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
