[70984] = { ["id"] = 70984, ["name"] = "Surge Breaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70984 }, ["objectivesText"] = "Djaradin Forces repelled", ["rewardXP"] = 1770, ["rewardItems"] = { 191264 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Djaradin Forces repelled", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[70985] = { ["id"] = 70985, ["name"] = "The Lonely Scout", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70985 }, ["description"] = "I know, I know, it's silly. A centaur and a dryad, right? We can't be more different. But ever since I first laid eyes on the Emerald Gardens, I really have wanted to get to know one better. I just can't seem to say or do anything to keep them interested in me. I've heard they're into... plants. And cute baby animals. And maybe killing poachers, but I don't even know where to start. Please, you can talk to them, right? Could you ask around and find out what they like? Then maybe I can have a shot.", ["objectivesText"] = "Speak to dryads in Shady Sanctuary. Progress: Any luck? Please tell me there's hope. It would just be so nice.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 195489, ["x"] = 0.342, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195489, ["x"] = 0.342, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70990] = { ["id"] = 70990, ["name"] = "If There's Wool There's a Way", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 70990 }, ["description"] = "While most of our wool comes from our own argali flocks, we do sometimes need to pull from the land when the flock grows thin. The nearby plains are home to wild argali - they tend to be more temperamental than our clan's flock. If you could take this blade and attempt to shear their wool, it would be a great service to Aylaag.", ["objectivesText"] = "Shear cliffhoof argali for their wool. Progress: Take care to avoid the horns. They're as sharp as any knife.", ["rewardXP"] = 2765, ["rewardItems"] = { 191984, 191986, 191988, 191989, 191990, 191991, 191992, 191994, 191995, 191996, 191998, 191999, 192002, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192015, 192037, 197943, 198542, 200149, 200153 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 185870, ["x"] = 0.658, ["y"] = 0.491667 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.491667 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[70997] = { ["id"] = 70997, ["name"] = "Wanted: Ruby Lifeband", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 70997 }, ["description"] = "<The posted sign is written in hasty scratches.> Expedition members have reported a Primalist attack on the Ruby Life Pools, threatening the destruction of countless artifacts stored by our dragon allies there. Toddy and Naleidea urge all combat-ready members to join the fight, and seek out the Ruby Lifeband if you are able. It is a unique, priceless artifact that must be preserved. If acquired, please deliver to Cataloger Jakes for safekeeping until the dragons may safely retrieve it.", ["objectivesText"] = "Find the Ruby Lifeband in the Ruby Life Pools. Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191999, 192001, 192007, 192008, 192013, 198490, 198529, 198532, 198695, 200179, 205423, 209837, 217242 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "dungeon" },
[71001] = { ["id"] = 71001, ["name"] = "Wanted: Earthbound Primordial Core", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71001 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Earthbound Primordial Core for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Recent learnings from records recovered from the Obsidian Citadel indicate it may have once been stored in the Dragon's Hoard of Neltharus, although it's current location is unclear.", ["objectivesText"] = "Find the Earthbound Primordial Core in Neltharus. Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191989, 191994, 191995, 191997, 191998, 191999, 192003, 192004, 192009, 192014, 192037, 197938, 197941, 198490, 198532, 198695, 200200, 205423, 209837, 217242 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "dungeon" },
[71002] = { ["id"] = 71002, ["name"] = "Best Spell Ever", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 71002 }, ["description"] = "<Gently levitating and emanating with arcane magic, this enchanted book contains countless spells and enchantments created by the chaotic yet beautiful mind of Millhouse Manastorm.>", ["objectivesText"] = "Read \" Manastorming for Beginners \" and discover Millhouse's secret spell.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 200205 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71004] = { ["id"] = 71004, ["name"] = "Wanted: Ohuna Mass-Binding Totem", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71004 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Ohuna Mass-Binding Totem for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Expedition members have reported a particularly powerful Primalist in the Windsong Rise of the Ohn'ahran Plains, who appears to wield the rumored powers of this totem.", ["objectivesText"] = "Find the Ohuna Mass-Binding Totem . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191989, 191991, 191992, 191993, 191995, 191997, 191998, 191999, 192000, 192001, 192002, 192005, 192007, 192011, 192012, 192013, 192014, 192037, 197931, 198490, 198529, 198532, 198695, 200134, 205423, 209837 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71005] = { ["id"] = 71005, ["name"] = "Wanted: Fangfall", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2022, ["storyline"] = { 71005 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the legendary blade Fangfall for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. The sword was reportedly fractured long ago, but expedition members have reported that the Sundered Flame is recovering fragments of it in ruins of the Ohn'aran Plains.", ["objectivesText"] = "Find 100 Fragments of Fangfall . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191983, 191986, 191987, 191988, 191990, 191991, 191993, 191994, 191995, 191997, 191998, 191999, 192000, 192001, 192002, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192037, 197931, 198490, 198529, 198532, 198695, 200140, 205423, 209837, 217242 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
