[71010] = { ["id"] = 71010, ["name"] = "Wanted: Temporal Spyglass", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71010 }, ["description"] = "<The posted sign is written in beautiful calligraphy.> The archivists humbly request that all expedition members seek out the Temporal Spyglass for our artifact archives. If acquired, please deliver to Cataloger Jakes for processing and compensation. Expedition members have reported overhearing a dwarf bragging about his magical spyglass in the inns of Southern Thaldraszus. We recommend focusing your search in that region.", ["objectivesText"] = "Find the Temporal Spyglass . Progress: Do you have something for the archives?", ["rewardItems"] = { 190454, 191984, 191988, 191990, 191991, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192005, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 198490, 198529, 198532, 198695, 200122, 205423, 209837 }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189226, ["x"] = 0.47, ["y"] = 0.825 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.825 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71018] = { ["id"] = 71018, ["name"] = "Vault of the Incarnates: Break a Few Eggs", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14030, ["storyline"] = { 71018 }, ["description"] = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly. Three should be enough. Four seems excessive.", ["objectivesText"] = "Collect 3 Shards of the Greatstaff from Broodkeeper Diurna within the Vault of the Incarnates on Normal Difficulty. Progress: The power contained in these shards will allow us to quickly access The Clutchwarren.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 200225 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14030 } }, ["questType"] = "raid" },
