[71023] = { ["id"] = 71023, ["name"] = "Renowned with the Valdrakken Accord", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71023 }, ["description"] = "Your deeds are certainly in line with your fabled reputation prior to coming to the Dragon Isles. I wish to assist you further by providing you with additional supplies. Seek me out in Valdrakken.", ["objectivesText"] = "Speak with Unatos in Valdrakken.", ["rewardItems"] = { 199475, 204381 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 193015, ["x"] = 0.58, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2552, ["threshold"] = 7500 } } } },
[71026] = { ["id"] = 71026, ["name"] = "Against Overwhelming Odds", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 66036, 67053, 70135, 70373, 71026, 71143 }, ["description"] = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges. If you gather some friends, I know a place you can show the other side who is truly superior. And to make it interesting, if you are successful I have a prize for you.", ["objectivesText"] = "Slay 25 Level 70 Horde anywhere within the Dragon Isles.", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196191, ["x"] = 0.433333, ["y"] = 0.423333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196191, ["x"] = 0.433333, ["y"] = 0.423333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.433333, ["y"] = 0.423333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "pvp", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 1406, ["name"] = "10.0 Faction Swap Protection [DNT]", ["orderIndex"] = 6, ["flags"] = 0 } } },
[71028] = { ["id"] = 71028, ["name"] = "Hunting Tactics: Blessing of Ohn'ahra", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2022, ["storyline"] = { 71028 }, ["description"] = "Your renown with the Maruuk grows. Listen closely, and I will teach you to call upon a blessing of Ohn'ahra to protect you and your allies.", ["objectivesText"] = "Select a blessing of Ohn'ahra for use in the Grand Hunt.", ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 192926, ["x"] = 0.518, ["y"] = 0.765 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 192926, ["x"] = 0.518, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
