[71093] = { ["id"] = 71093, ["name"] = "Legacy of Tyr: Secrets of the Past", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 71093 }, ["description"] = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored. Inconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead. Queen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there. Word is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", ["objectivesText"] = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc.", ["rewardGold"] = 1123600, ["rewardXP"] = 19030, ["rewardItems"] = { 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[71094] = { ["id"] = 71094, ["name"] = "Help Is Our Way!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71094 }, ["description"] = "Hiya! Are you also here to help? You look very helpful! <Heleth points to the injured dracthyr.> That guy hurt his wing trying to fly all the way up here! He looks like one of those bad guys from downstairs, but I'm not scared of him! I'm gonna help him out anyway, because that's our way! <Heleth puffs out their chest.> I'll stand guard over him, while you go find some bandages!", ["objectivesText"] = "Find bandages in the tower above the Cobalt Assembly to heal Venderthvan . Progress: Finally! New people to play with!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 25948, 25949, 25951, 31725, 200514, 200628 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197100, ["x"] = 0.462, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197100, ["x"] = 0.462, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71095] = { ["id"] = 71095, ["name"] = "A Claw in Need", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71095 }, ["description"] = "Let's see what we can do to help this guy! <Heleth leans in close and whispers.> Don't worry, we aren't gonna let him take anything or stuff like that. Let's just have some fun! It's been ages since anyone has come up here to check up on us. We're SO bored! <Heleth winks at you.> Why don't you ask him what he wants?", ["objectivesText"] = "Ask Venderthvan how you can help him and do what he says. Progress: Go ahead, <race>, do all the work for me. It will be a piece of cake to take the artifact from you when the moment is right.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 198476 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197100, ["x"] = 0.462, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197201, ["x"] = 0.46, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71096] = { ["id"] = 71096, ["name"] = "Is A Claw Indeed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71096 }, ["description"] = "<Venderthven rubs his eyes and groans in pain.> Fine. If you won't give it to me, you can do the work of figuring out how to make it work. I'll just take it from you when you're done. By force, if necessary. So go ahead. Give it a shake or something.", ["objectivesText"] = "Attempt to activate the artifact. Progress: < Venderthvan is distracted, looking at a toy duck Nezzie is showing him.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197201, ["x"] = 0.46, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197201, ["x"] = 0.46, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71138] = { ["id"] = 71138, ["name"] = "Waygate: Rusza'thar Reach", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71138 }, ["description"] = "An expeditionary member reported a dormant stone sighting atop a lookout in the Ohn'ahran Plains . Up fer an adventure?", ["objectivesText"] = "Locate the Dormant Waygate at the Rusza'thar Reach in the Ohn'ahran Plains . Progress: What are ye waitin' fer?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198538, 200527 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71139] = { ["id"] = 71139, ["name"] = "Glowing Arcane Jewel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71139 }, ["description"] = "<This jewel seems to be quite powerful. There is an eerie glow to it. Perhaps it's best to deliver it to the Kirin Tor for it to be placed in a safe spot.>", ["objectivesText"] = "Bring the Glowing Arcane Jewel to Noriko the All Knowing in Camp Antonidas.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 197137, 197141, 200528 }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 183543, ["x"] = 0.466, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["startItems"] = { 200528 } },
