[71146] = { ["id"] = 71146, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71146 }, ["description"] = "<The explorer-in-training hands you a taut, rolled note. Upon investigating, it appears to be from an old friend, Thaelin Darkanvil , seeking your aid. Before scurrying off, the critter extends its hand as if it were seeking a treat. Moments later, a loud screech rings out as the curious creature storms off empty handed.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 200590 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71148] = { ["id"] = 71148, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71148 }, ["description"] = "<The curious creature before you presents a note--signed and sealed by the Dragonscale Expedition. A call for assistance from a famed explorer, perhaps.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 200593 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71149] = { ["id"] = 71149, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71149 }, ["description"] = "<Surprisingly, the messenger did not leave you with a satchel or a note this time, rather a single item from Thaelin's personal collection. Upon further investigation, a tiny little message from Thaelin seeks your assistance once again.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 200594 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[71150] = { ["id"] = 71150, ["name"] = "Continued Waygate Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 71150 }, ["description"] = "<The parchment emits an unpleasant, mold-like smell. After struggling to regain focus, it becomes clear Thaelin needs your assistance in seeking answers to newly discovered findings. The only question that remains is what to do with this parchment of intolerable odor.>", ["objectivesText"] = "Meet Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores . Provided item:", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["rewardItems"] = { 200595 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196643, ["x"] = 0.455333, ["y"] = 0.552667 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455333, ["y"] = 0.552667 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
