[71157] = { ["id"] = 71157, ["name"] = "Waygate: Skytop Observatory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71157 }, ["description"] = "Word from some of our northern explorers is there's another o' those stones high atop the spire to the northeast. Heard it's quite difficult tae reach bein' so high up and all, but I'm sure ye can find a way!", ["objectivesText"] = "Locate the Dormant Waygate at the Skytop Observatory in The Waking Shores . Progress: Any luck?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198538, 200556 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
