[71161] = { ["id"] = 71161, ["name"] = "Waygate: Vakthros", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71161 }, ["description"] = "Received a report of another of them dormant stones in the wintry region tae the southeast. Now before ye go gettin' all excited just know this isn't a place most go willingly, but if ye feel the need fer adventure and possible death, this is fer you! Sold ye on it enough yet? Good! Toss on yer warmest attire, then head east until the chill of the wind tickles yer nose and keep goin'. You'll know yer close when ye start feelin' the toughness in yer breath and the chill in yer bones.", ["objectivesText"] = "Locate the Dormant Waygate atop the spire in Vakthros in The Azure Span . Progress: Keepin' warm I hope.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198538, 200557 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71162] = { ["id"] = 71162, ["name"] = "Waygate: Algeth'era", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71162 }, ["description"] = "Another stone. Another spire. Best be gettin' along on yer journey. This one's quite a trek and dangerous tae boot! At least accordin' tae the ones who discovered it. Are ye up fer it?", ["objectivesText"] = "Locate the Dormant Waygate atop the spire in Algeth'era in Thaldraszus . Progress: Can always count on ye tae get the job done.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 200558 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[71165] = { ["id"] = 71165, ["name"] = "Waygate: Eon's Fringe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71165 }, ["description"] = "Far across the land in the mountainous regions of Thaldraszus sits a little inn nestled on the mountainside. Just inside the entryway sits a long-forgotten, dormant stone. What say ye? Up fer another adventure, <name>?", ["objectivesText"] = "Locate the Dormant Waygate at Eon's Fringe in Thaldraszus . Progress: Ye know I'd love tae sit around and talk, but there's work tae do.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 200560 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
