[71191] = { ["id"] = 71191, ["name"] = "Net Worth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 71191 }, ["description"] = "Alas, my fishing net was carried away by the stream. <Sigh> I'm not too keen to use fishing poles like my friends... If you happen to find my fishing net around, bring it back to me.", ["objectivesText"] = "Recover Gruff Fisher's Net from ice holes in Azure Span. You may unlock only one extra fishing net per day. Progress: Any luck finding the net?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 194701, 199696, 200074, 200078, 200081, 200646, 202207 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[71192] = { ["id"] = 71192, ["name"] = "Predator Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 71192 }, ["description"] = "Greetings friend! I've been looking for a good place to set up fishing nets around here, but it seems like the population of waddlers around here is too dense - they're eating away most of the juvenile fish before they get a chance to mature. I've made some effigies to scare at least some of those ravenous birds away. This will help us sustain the abundance of fish across the Dragonsprings. Can you help me set those up?", ["objectivesText"] = "Set up the Scary Effigies. You may unlock only one extra fishing net per day. Progress: Did you set up enough effigies?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 194701, 199694 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[71193] = { ["id"] = 71193, ["name"] = "Underwater Menace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 71193 }, ["description"] = "Did you see that? Underwater! A huge, armored, hungry beast! No way I'm getting near water with my net while that monstrosity lurks below. If you want, you can likely lure it out with a handful of Ominous Conches. Those shouldn't be too hard to catch. To gain conchs, be sure to have your Iskaaran Harpoon handy as you fish in the Dragon Isles.", ["objectivesText"] = "Use 5 Ominous Conches in the Tyrhold Fishing Hole to summon a huge underwater beast, and bring back something as a proof of its demise. You may unlock only one extra fishing net per day. Progress: You're not afraid of littoral megafauna, are you? Because I am!", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 194701, 200667 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 197597, ["x"] = 0.572, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 197597, ["x"] = 0.572, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[71194] = { ["id"] = 71194, ["name"] = "Frogs of Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 71194 }, ["description"] = "I found a perfect spot for a fishing net, one problem bothers me though... Those Hornspikes. I'm pretty sure they will ravage the nets as soon as it's left alone. What do we do? ...I've got an idea. We treat our lava fishing nets with Icicle Brew to make them heat-resistant. We just need to teach those hornspikes to keep away from that smell. Toss a flask of Icicle Brew at a hornspike, and then deal some damage to them. Just make sure not to kill them, they won't learn if they're dead, would they?", ["objectivesText"] = "Teach a couple of Hornspikes to avoid Icicle Brew. You may unlock only one extra fishing net per day. Progress: Did you teach them to keep away from the smell of Icicle Brew?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 137663, 194701 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 198767, ["x"] = 0.344, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 198767, ["x"] = 0.344, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
