[72063] = { ["id"] = 72063, ["name"] = "Return Yennu's Toy Boat", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72063 }, ["description"] = "<This hand made toy boat resembles the ships of the Tuskarr. Yennu , the young Tuskarr, was musing about a boat, it must belong to him>", ["objectivesText"] = "Return the toy boat to Yennu alongside the river in the Ohn'ahran Plains .", ["rewardItems"] = { 200876, 200878 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 195252, ["x"] = 0.524, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 200876 } },
[72069] = { ["id"] = 72069, ["name"] = "Subglacial Refill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72069 }, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Seems we have caught almost all the fish under the ice. Could you catch some more from the Timbertooth Trail downstream, bring it here, and drop it into an ice hole?", ["objectivesText"] = "Collect fish to restock the fishing hole and throw it into an Ice Hole. Progress: Have you dropped those fish yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198855 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197700, ["x"] = 0.586, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72071] = { ["id"] = 72071, ["name"] = "Round Two, Fish!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72071 }, ["description"] = "How do you feel about doing a little fishing, then, <name>? There's a school of bait fish just offshore that the dumb beast attacks whenever they gather, forgetting that it's already dead. Swim out there and wave that lure around, maybe do your best impression of a wounded seal, and it won't be able to resist.", ["objectivesText"] = "Slay Mochoby . Progress: It's out there. I can feel it.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 202200 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 197979, ["x"] = 0.812, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 197979, ["x"] = 0.812, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.812, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72072] = { ["id"] = 72072, ["name"] = "Dragonsprings Drop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72072 }, ["description"] = "The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?", ["objectivesText"] = "Collect fish to restock the fishing hole and mount your drake to drop them from above. Progress: Have you dropped those fish yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 198855 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 198766, ["x"] = 0.808, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.808, ["y"] = 0.784 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
