[72339] = { ["id"] = 72339, ["name"] = "Engine of Innovation", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72339 }, ["description"] = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. You have proven yourself worthy and overcome all the challenges set before you. You may now unlock Engine's full potential.", ["objectivesText"] = "Insert the newly attuned Power Core into the Engine of Innovation.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["rewardItems"] = { 199197 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196475, ["x"] = 0.838, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72354] = { ["id"] = 72354, ["name"] = "The Great Vault", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72354 }, ["description"] = "Over the years, the Aspects and their kin acquired many remarkable artifacts and armaments. The Aspects ordered the construction of an enchanted vault where they could be stored for safe-keeping until such a time as a worthy soul came in search of that which lay within. You will find this Great Vault within the walls of the bank. Perhaps, if you prove your mettle, it will grant you a piece of the Aspects' ancient hoard.", ["objectivesText"] = "Obtain a piece of loot from the Great Vault. Progress: The vault seems to know when a worthy soul approaches. You need not be afraid. Go on. Give it a look.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 201793 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 196499, ["x"] = 0.503, ["y"] = 0.5605 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5605 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
