[72396] = { ["id"] = 72396, ["name"] = "Horns of Plenty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72396 }, ["description"] = "Many of our inventions rely on using a sturdy and springy material. Fortunately, vorquin horns have served as the perfect product for many of our modern creations. Even more fortunate for us, the Dragon Isles are swarmed with vorquin. It should be a simple task for you to gather some springy horns from the vorquin for us.", ["objectivesText"] = "Gather 20 Springy Horns from the vorquin of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Did you collect the vorquin horns?", ["rewardXP"] = 1415, ["rewardItems"] = { 198611, 198970, 201816 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[72398] = { ["id"] = 72398, ["name"] = "Rock and Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72398 }, ["description"] = "Earth elementals in the Dragon Isles are composed of various rocks and minerals. Our blacksmiths are thoroughly fascinated with the unique tools they are able to manufacture from smelting such materials. In fact, they appear to have smelted the last of their samples. I would hate to ruin their fun. Would you mind replenishing the supply?", ["objectivesText"] = "Gather 15 Earthen Samples from the earth elementals of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you gathered enough Earthen Samples from the Elementals?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 198606, 201819 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[72399] = { ["id"] = 72399, ["name"] = "The Hermit's Garden", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 72399 }, ["series"] = { 69932 }, ["description"] = "Our parents always say we shouldn't visit the gardens above Gelikyr. They think the gardener is mean and dangerous. That's not true, though! They're a bit grumpy, but they're really nice! None of us have been up there since the Primalists showed up. It's way too dangerous now. Still, I hope the gardener is okay. Could you go and check on them, since we can't visit anymore?", ["objectivesText"] = "Speak to Szareth in Shadow Ledge.", ["rewardGold"] = 16980, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 198507, ["x"] = 0.525, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 193538, ["x"] = 0.502, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[72407] = { ["id"] = 72407, ["name"] = "Soaked in Success", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72407 }, ["description"] = "Fishermen of our tribe are constantly plagued with waterlogged packs and boots. Lately, the riverbeasts have been swarming fishing spots and causing even more mayhem. The hide of the riverbeasts are quite slick and water-resistant. Perhaps we can handle two problems at once. If you could help handle the over abundance of riverbeasts and bring back their hides, our fishers would be quite pleased.", ["objectivesText"] = "Gather 18 Waterproof Hide from the riverbeasts of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you found some hide with waterproof qualities?", ["rewardXP"] = 1415, ["rewardItems"] = { 198613, 201822 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[72410] = { ["id"] = 72410, ["name"] = "Pincers and Needles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72410 }, ["description"] = "We've been running low on needles for tailoring lately. Those darn things keep snapping in two! Some pointy parts from the scythid in the area might serve as good replacements.", ["objectivesText"] = "Gather 10 Pointy Pincers from the scythid of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition. Progress: Have you found some pointy parts to replace our needles?", ["rewardXP"] = 1415, ["rewardItems"] = { 198609, 201825 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191001, ["x"] = 0.366667, ["y"] = 0.625333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366667, ["y"] = 0.625333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[72423] = { ["id"] = 72423, ["name"] = "Weathering the Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72423 }, ["description"] = "Ah, you have arrived just in time! We've heard tales that the Nokhud centaur have powerful, dangerous weaponry infused with storm enchantments. We would like to bring some samples to our enchanters for study. At the very least, we can decommission the weapons and put them to better use.", ["objectivesText"] = "Gather 12 Tempest Armaments from the Nokhud centaurs of the Dragon Isles for Temnaayu of the Iskaara Tuskarr. Progress: Have you found any weapons for study?", ["rewardXP"] = 1415, ["rewardItems"] = { 198610, 201826 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191004, ["x"] = 0.366, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
[72427] = { ["id"] = 72427, ["name"] = "Animated Infusion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72427 }, ["description"] = "I have a simple request for you today. The alchemists are short on an ingredient used in a particularly tricky brew. The herb is easy enough to retrieve. You'll just need to find some aggressive plants to extract samples from. Think you can handle that?", ["objectivesText"] = "Gather 13 Spiked Leaves from the lashers of the Dragon Isles for Dhurrel of the Maruuk Centaurs. Progress: Have you retrieved the herbs?", ["rewardXP"] = 1415, ["rewardItems"] = { 198608, 201828 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191002, ["x"] = 0.3655, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3655, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[72434] = { ["id"] = 72434, ["name"] = "Ruby Lifeshrine Loop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["storyline"] = { 72434 }, ["description"] = "They say I'm not big enough to fly some of these courses yet. But I can still watch others do it. You should race! Then I can watch you race.", ["objectivesText"] = "Complete the Ruby Lifeshrine Loop course.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72435] = { ["id"] = 72435, ["name"] = "Orientation: Iskaara", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72435 }, ["description"] = "Welcome to Iskaara, friend. Word of your exploits in Brackenhide has already spread among our people. You have already met many of us, and there are more who would like the chance to exchange knowledge and wares with you. Please, take a moment to familiarize yourself with some of the friendly faces around Iskaara. We are a community that supports one another, so just as you have much to offer us, many of our people have much to offer you in return.", ["objectivesText"] = "Familiarize yourself with some vendors with valuable wares. Progress: We have much to offer each other, friend.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 190454, 192017, 200072, 200073, 202142 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 193006, ["x"] = 0.13, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.13, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72438] = { ["id"] = 72438, ["name"] = "Tarasek Intentions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72438 }, ["description"] = "When the tarasek accepted power from the Primalists, they stole many ancient scrolls and tomes to combine with their newfound magic. We need help getting these scrolls back in our possession.", ["objectivesText"] = "Gather 15 Draconic Scrolls from the tarasek of the Dragon Isles for Dothenos of the Valdrakken Accord. Progress: Have you retrieved any of the scrolls?", ["rewardXP"] = 1415, ["rewardItems"] = { 198607, 201835 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 191000, ["x"] = 0.365, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[72447] = { ["id"] = 72447, ["name"] = "Greatest of Threats", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72447 }, ["description"] = "Powerful djaradin and other creatures threaten both the Obsidian Citadel and the safety of my flight. This cannot stand. Help secure the area. Seek out and eliminate two of our most powerful enemies.", ["objectivesText"] = "Eliminate two rare enemies within the Obsidian Citadel or Slagmire. Progress: Is it done?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191251, 191264, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192020, 192031, 192033, 192037, 193201, 193477, 197923, 197939, 197943, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191193, ["x"] = 0.276, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72448] = { ["id"] = 72448, ["name"] = "Securing Our Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72448 }, ["description"] = "I have not worked this hard and come this far to lose the Citadel now! Unfortunately, new threats have emerged. Can I count on your assistance to deal with them? Help secure the area. Seek out and eliminate two of our most powerful enemies.", ["objectivesText"] = "Eliminate two rare enemies within the Obsidian Citadel or Slagmire. Progress: Have you taken care of the threats?", ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 191251, 191264, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192016, 192017, 192020, 192021, 192028, 192030, 192031, 192032, 192033, 192037, 193201, 193477, 197922, 197923, 197926, 197937, 197939, 197940, 197942, 197943, 197945, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 190899, ["x"] = 0.266, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72454] = { ["id"] = 72454, ["name"] = "The Obsidian Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72454 }, ["description"] = "An egg from the black dragonflight is ready to hatch. Report to Mother Elion in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Obsidian Oathstone to hatch in a location strong with their flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Black Dragon Egg at the Ruby Lifeshrine then hatch it at the Obsidian Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72455] = { ["id"] = 72455, ["name"] = "Warmth and Comfort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72455 }, ["description"] = "In order for the obsidian hatchling to be comfortable, we must build them a proper nest. You will need to build their nest from Obsidian Citadel coal to make sure it is warm and suitable. Secondly, Archivist Edress will be able to assist you in finding something that ties them to their people. We will want to gather something from Zaralek Cavern as well, as much of their flight's history is rooted there. Surely somebody in Loamm can help.", ["objectivesText"] = "Gather supplies for the Obsidian Hatchling's nest. Progress: We have the most to learn with this hatchling... I hope she has patience while we improve.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202286, 202288, 202292 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72456] = { ["id"] = 72456, ["name"] = "Tomes Of Trust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72456 }, ["description"] = "Despite securing the upper ramparts of the Obsidian Citadel, the djaradin forces continue to pillage the courtyard. The area is full of priceless historical records! We must act quickly to secure anything that documents the lineage of the black dragonflight. Both Wrathion and Sabellian desire this information, so you can curry favor by procuring a tome for each of them. Travel to the collapsed tower of the citadel. You should find something worth recovering.", ["objectivesText"] = "Recover volumes of the Obsidian Genealogy , and deliver them to Wrathion and Sabellian's quartermasters. Progress: Have you found the tomes?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 201925 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 188344, ["x"] = 0.249, ["y"] = 0.564 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 188344, ["x"] = 0.249, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.249, ["y"] = 0.564 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72457] = { ["id"] = 72457, ["name"] = "A Home-Cooked Meal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72457 }, ["description"] = "Black dragon whelps need to grow up to be big and strong. Our hatchling here seems quite small, so I believe she will require something hearty and nutritious to help her along her way. Roast duck is not only good for your stamina, but also your brain. I think it would be the perfect meal for our young hatchling.", ["objectivesText"] = "Gather Roast Duck Delight for the Obsidian Whelp. This can be crafted via the cooking profession or purchased from the auction house. Progress: Duck is a delicacy local to the Dragon Isles. Did you know we have not found them anywhere else in Azeroth?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 197790 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72458] = { ["id"] = 72458, ["name"] = "Tag, You're Anxious", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72458 }, ["description"] = "Every whelp needs some playtime to get out their energy. Our new obsidian friend is no exception. The hatchlings love playing a good game of tag. See if she would like to play with you!", ["objectivesText"] = "Play with the Obsidian Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72459] = { ["id"] = 72459, ["name"] = "What's a Duck?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72459 }, ["description"] = "I will be honest with you, <name>. It has been such a long time since we dealt with the black dragonflight that I could not quite tell you much about them. I do know that they are strong warriors, brave protectors of us all. Rusziona is still quite young, but perhaps we should see how well she does with battle? Take her to practice on some ducks in the Ohn'ahran Plains. Let us see her baseline.", ["objectivesText"] = "Kill 5 Bluebill Waddlers in Primordial Vale with Rusziona. Progress: How did Rusziona fare with the ducks?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45072, 202293 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72460] = { ["id"] = 72460, ["name"] = "A Solid Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72460 }, ["description"] = "I worry about Ruszi. She is incredibly nervous and insecure, and she jumps at nearly anything! I have never heard of a black dragon so terrified of the world. I believe the best way for us to build her confidence is to find her a companion. Something sturdy and strong that does not move quickly or suddenly. The black dragonflight's charge is the protection of earth. Perhaps a small elemental will suit her well. Speak to Lysindra at the pet shop in Valdrakken. She should have something suitable.", ["objectivesText"] = "Obtain a pet for Rusziona. Progress: Earth elementals are wonderful first pets. They eat gravel, they do not go very far very quickly, and they can stand against almost anything!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72461] = { ["id"] = 72461, ["name"] = "Anatidaephobia", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72461 }, ["description"] = "The time has come, <name>. Her new pet Iggy has been doing wonders for Rusziona 's confidence, and now I think she's ready to face her biggest fear. Ducks. There is a tauren in the Waking Shores who is an expert at using pets to help heal trauma. I think she might be just what we need. Lasztak and Rusziona will meet you there.", ["objectivesText"] = "Help Rusziona and Iggy defeat a duck in a pet battle. Progress: A large duck still may be too much for Rusziona , but a duckling will be perfect.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206682 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72524] = { ["id"] = 72524, ["name"] = "Basic Climbing Gear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72524 }, ["series"] = { 65421, 66351 }, ["description"] = "< Pathfinder Jeb motions to the supply kit next to him.> You're going to need supplies to survive out there. Let's get you what you need to start climbing.", ["objectivesText"] = "Use the Expedition Supply Kit to research Climbing Gear.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 191138 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187700, ["x"] = 0.472, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.834 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
