[72664] = { ["id"] = 72664, ["name"] = "Eggs in Abundance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72664 }, ["description"] = "<Flaps does a spin and deposits a drool-soaked note into your hand.> $p, the Ruby Life Pools are overwhelmed with dragon eggs ready to hatch. We are excited to welcome these blessings to Azeroth, but we do not have enough whelptenders to mind them all. Please visit me at the Lifeshrine so we may discuss a potential solution. - Amella", ["objectivesText"] = "Meet Amella at the Ruby Lifeshrine in the Waking Shores.", ["rewardGold"] = 24100, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197478, ["x"] = 0.455, ["y"] = 0.5545 }, { ["mapID"] = 2112, ["npcID"] = 214121, ["x"] = 0.13, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 187130, ["x"] = 0.622, ["y"] = 0.735 }, { ["mapID"] = 2022, ["npcID"] = 194174, ["x"] = 0.622, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72665] = { ["id"] = 72665, ["name"] = "Whelptender's Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72665 }, ["description"] = "Our egg-tenders report a new clutch of eggs is soon to hatch. Ordinarily, a whelptender would take each newly hatched dragon and raise them with their flight. However, not all dragonspawn are called to the life of a whelptender, and we are short of hands. Gather wisdom from whelptenders of each flight in the gardens below the Lifeshrine. Agapanthus, an experienced whelptender of the blue flight, has offered his services as head of the Little Scales Daycare. But he will need your assistance.", ["objectivesText"] = "Speak to whelptenders at the gardens of the Ruby Life Pools. Progress: Whelptenders of the red flight study the methods of each flight to provide the best all-around care. It makes sense that you are studying those methods, too.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 187130, ["x"] = 0.622, ["y"] = 0.735 }, { ["mapID"] = 2022, ["npcID"] = 194174, ["x"] = 0.622, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 191027, ["x"] = 0.618, ["y"] = 0.738 }, { ["mapID"] = 2022, ["npcID"] = 191881, ["x"] = 0.55, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72666] = { ["id"] = 72666, ["name"] = "Daycare Director Agapanthus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72666 }, ["description"] = "Amella has told me about the incoming whelps and about the daycare. Did you know Agapanthus is a renowned whelptender? I heard he fought back demons while rearing whelps! If he's as amazing as they say, I have much to learn from him. I only just received my Calling, but I will help in any way I can. The Little Scales Daycare is in Valdrakken. I will gather my things and meet you and Agapanthus there.", ["objectivesText"] = "Meet Agapanthus at the Little Scales Daycare in Valdrakken.", ["rewardGold"] = 1745, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 191027, ["x"] = 0.618, ["y"] = 0.738 }, { ["mapID"] = 2022, ["npcID"] = 191881, ["x"] = 0.55, ["y"] = 0.636 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72667] = { ["id"] = 72667, ["name"] = "Snack Run", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72667 }, ["description"] = "The whelps that visit the daycare eat snacks during their visit. A lot of snacks. If there are going to be whelps that stay here with regularity, we will need even more rations to sate their endless hunger. Here is a list of snacks the whelps have taken to lately. I also ordered something for Sir Pringly, so be sure to get that as well.", ["objectivesText"] = "Gather snacks from vendors in Valdrakken. Progress: It was the same in Aszuna. Cheese and crackers are treasured by all whelps.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202265, 202266, 203386, 203432, 203433, 203443 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72668] = { ["id"] = 72668, ["name"] = "A Nurturing Environment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72668 }, ["description"] = "Young whelps can be careless in how they treat their space. The daycare is effectively under siege day in and day out! Help clean up the daycare. The new whelps will need a proper place to stay. I will not let one claw set down on unpolished stone or overgrown grass!", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: Is there anything better than squaring away a space?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
