[72784] = { ["id"] = 72784, ["name"] = "Supporting the Cobalt Assembly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72784 }, ["description"] = "<name>, excellent timing. Have you heard of the Cobalt Assembly? It was once a wondrous place where most of my kin lived. The Sundered Flame forced us out and have taken it over. There was a hope that we could take it from them, but the latest information from there shows we are fighting a losing battle. Can you lend us your support? Meet Venthi within the Cobalt Assembly if you can.", ["objectivesText"] = "Speak with Venthi within the Cobalt Assembly.", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 192222, ["x"] = 0.466, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194680, ["x"] = 0.49, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
