[72972] = { ["id"] = 72972, ["name"] = "The Waking Shores Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2022, ["storyline"] = { 72972 }, ["description"] = "It's time to send you backwards. Not backwards in time, although we could do that, but have you fly the courses in reverse. Get ready to see these courses in a different way. Let's start with Serohs Gnikaw! Wait. Waking Shores!", ["objectivesText"] = "Fly each of the reverse courses in Waking Shores.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52 }, { ["mapID"] = 2025, ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[72982] = { ["id"] = 72982, ["name"] = "The Ohn'ahran Plains Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 72982 }, ["description"] = "Time to go forward to go backward once more. More races await you in Ohn'ahran plains . Head over there now, make sure you go in the right direction.", ["objectivesText"] = "Fly each of the reverse courses in Ohn'ahran Plains .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 193411, ["x"] = 0.732, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 2022, 2023 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[72984] = { ["id"] = 72984, ["name"] = "The Azure Span Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 72984 }, ["description"] = "The next set of backward courses are back in the Azure Span . When you're ready you should head back over there and retrace your previous steps to the previous races.", ["objectivesText"] = "Fly each of the reverse courses in the Azure Span .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 199118, ["x"] = 0.88, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.88, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[72985] = { ["id"] = 72985, ["name"] = "The Thaldraszus Reverse Tour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 72985 }, ["description"] = "Once more you'll be heading back to where it all finished. Or started. I can't remember anymore. Seek out my bronze colleagues to fly the reverse courses to complete your rewinding.", ["objectivesText"] = "Fly each of the reverse courses in Thaldraszus .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 199119, ["x"] = 0.632, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 199120, ["x"] = 0.46, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[72989] = { ["id"] = 72989, ["name"] = "The Ruby Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72989 }, ["description"] = "An egg from the red dragonflight is ready to hatch. Report to Amella in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Ruby Oathstone to hatch in a location strong with our flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Red Dragon Egg at the Ruby Lifeshrine then hatch it at the Ruby Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72990] = { ["id"] = 72990, ["name"] = "Crimson Comfort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72990 }, ["description"] = "I am looking forward to our red whelp. They are, after all, my specialty! I have already spoken with Amella, and I would like to handle the nest myself. Here is a list of materials. Bring them to me when you are done, and I can fashion the most comfortable cushion you have ever seen! < Lasztak hands you a list of supplies.>", ["objectivesText"] = "Gather supplies for the Ruby Hatchling's nest. Progress: Red whelplings are my specialty.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202697, 203712, 204869, 204870 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72991] = { ["id"] = 72991, ["name"] = "Warm Dragonfruit Pie", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72991 }, ["description"] = "When I think of red dragon comfort food, I immediately think of the pies back at the Ruby Life Pools. You can always tell when our blacksmith, Krendisc, has downtime between orders--the entire mountain smells of delicious baked dragonfruit! My pie may not be as good as his, but I am sure our ruby hatchling will love it. If you bring me the ingredients I will bake the best pie I can!", ["objectivesText"] = "Gather Ripened Dragonfruit near the Ruby Life Pools and Pre-Made Pie Crust from Erugosa in Valdrakken, then bring them to Lasztak to bake a pie for the Ruby Hatchling. Progress: < Lasztak cracks his knuckles.> It has been a while since I baked anything, but I am confident!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 193826, 202693, 204868 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72992] = { ["id"] = 72992, ["name"] = "You're Playing Wrong!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72992 }, ["description"] = "Our red hatchling seems to be having quite the trouble making friends. Any time she tries to get one to play, it tends to end quickly. She can be a bit pushy, but whelps are whelps. Why don't you get her in the right mindset to play with some tag?", ["objectivesText"] = "Play with the Ruby Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72993] = { ["id"] = 72993, ["name"] = "I'm the Boss!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72993 }, ["description"] = "Never have I met such a bossy child! She has a list. A list! Please, take Belastrasza off our claws for a bit. I just... I need to sit down.", ["objectivesText"] = "Assist Belastrasza . Progress: <The bags under Agapanthus 's eyes are even deeper than usual.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 158639, 158640, 158642, 158643, 158644, 158645, 158648, 158649, 160207, 184519, 202173, 202250, 219766, 219767, 219768, 219769, 224784, 228654, 228655, 228656, 228657, 237812, 246815, 254677, 256763, 258265 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72994] = { ["id"] = 72994, ["name"] = "A Cavalier Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72994 }, ["description"] = "I believe that the only way we can teach Belastrasza to be less self-obsessed is to show her firsthand how it makes others feel. Vorquin are beautiful creatures, but they are incredibly high maintenance companions who need a lot of care. Lysindra in Valdrakken has a baby vorquin for Bela. Perhaps she will learn through getting a taste of her own medicine.", ["objectivesText"] = "Obtain a Baby Vorquin battle pet for Belastrasza. Progress: A stubborn pet for a stubborn whelp.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72995] = { ["id"] = 72995, ["name"] = "Patience, Please", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72995 }, ["description"] = "Belastrasza has learned much through her vorquin foal, but I have thought of one more lesson that should be excellent for her. Her lack of patience has been stumping me for quite some time. Recently I was reflecting by the water, watching the turtles go about their day. Then I was hit by a revelation! Wurallie has the perfect battle to test Belastrasza 's patience, but poor Princess Vorquistrasza doesn't have the endurance. Can you meet them in the Waking Shores to lend a hand?", ["objectivesText"] = "Help Belastrasza learn patience by defeating a turtle in a pet battle. Progress: Slow and steady, Bela. Slow and steady.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 205232, 206758 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72996] = { ["id"] = 72996, ["name"] = "The Bronze Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72996 }, ["description"] = "An egg from the bronze dragonflight is ready to hatch. Report to Xius in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Bronze Oathstone to hatch in a location strong with their flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Bronze Dragon Egg at the Ruby Lifeshrine then hatch it at the Bronze Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72997] = { ["id"] = 72997, ["name"] = "Nothing Like a Sandy Nap", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72997 }, ["description"] = "While red dragons enjoy their surroundings lush and lively, bronze dragons prefer their environments dry and sandy. I am sure you can find many materials for our hatchling's nest in the Temporal Conflux in Thaldraszus. I have read that bronze whelps also enjoy an appropriately sized basin to curl themselves in. My friend at the inn in the Bronze Enclave has exclaimed often about an excess of bowls... I am sure she would not mind if we took one off her hands.", ["objectivesText"] = "Gather supplies for the Bronze Hatchling's nest. Progress: Bronze dragons are like cats. They defy time and space.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202643, 202644, 202645 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72998] = { ["id"] = 72998, ["name"] = "Artisanal Aging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72998 }, ["description"] = "I have been learning much about bronze dragons since arriving in Valdrakken. While they take their charge of time seriously, they have found many hobbies for their free time that their magic can aid them with. My friend Gorgonzormu swears by his cheeses for all stages of dragon life. He mentioned that he has a type of parmesan that is excellent for bronze whelps. It seems that our hatchling's first meal is figured out!", ["objectivesText"] = "Buy Temporal Parmesan from Gorgonzormu in Valdrakken for the Bronze Hatchling. Progress: Cheese is best when aged over time, but bronze dragons have perfected rapid aging with their control of time!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 201415 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[72999] = { ["id"] = 72999, ["name"] = "Here? There? Everywhere!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 72999 }, ["description"] = "Our bronze hatchling has been staying away from the other whelps, mostly hanging out in the sand. Sometimes we find him in the sandbox with the others, but we never see him moving around! He could use some friendship. Why don't you treat him to a game of tag?", ["objectivesText"] = "Play with the Bronze Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73000] = { ["id"] = 73000, ["name"] = "Sneezing Through Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73000 }, ["description"] = "Zhusa is throwing us for quite the loop, <name>. Since he is so young, his control over time is not fully developed. Unfortunately, he has a strange reflex. Every time he sneezes he disappears, popping up elsewhere in any form! To top it off, he seems to have many allergies. Please, help Zhusadormu figure out what he is allergic to so we can keep him in one place!", ["objectivesText"] = "Find Zhusadormu throughout Valdrakken. Progress: < Agapanthus rubs his temples.> Oh, bronze whelps...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73001] = { ["id"] = 73001, ["name"] = "A Scaly Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73001 }, ["description"] = "We have been trying to decide on the perfect pet for Zhusadormu. His allergies limit our options by quite a bit, but I believe I have thought of a pet for him. I know for a fact that Zhusa is not allergic to scales. A baby hornswog is hypoallergenic and I believe Lysindra could acquire one for us.", ["objectivesText"] = "Obtain a Baby Hornswog battle pet for Zhusadormu. Progress: The whelps love hornswogs. They will love having one in the daycare!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73002] = { ["id"] = 73002, ["name"] = "Temporal Immunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73002 }, ["description"] = "Zhusadormu has been trying hard to keep his powers in check. While we may not be able to prevent his allergies, he does not have to jump through time with each sneeze. Wurallie believes she can test his control. Please go to the Waking Shores and help them with this lesson.", ["objectivesText"] = "Help Zhusadormu confront his allergies during a pet battle. Progress: I believe in Zhusa. I hope you do too.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206971 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73003] = { ["id"] = 73003, ["name"] = "The Azure Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73003 }, ["description"] = "An egg from the blue dragonflight is ready to hatch. Report to Axkall in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Azure Oathstone to hatch in a location strong with our flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Blue Dragon Egg at the Ruby Lifeshrine then hatch it at the Azure Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73004] = { ["id"] = 73004, ["name"] = "A Scholar's Delight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73004 }, ["description"] = "Blue dragons are seekers of knowledge, even from an early age. They seem drawn to books and scrolls, finding the most comfort when surrounded by them. For our azure hatchling, the best nest is truly amongst our many books. I request that you collect the following for his nest--a quill of his own to learn to write, something to keep him nice and cold, and a bedtime story from Azure Span. I have heard tale of one that many blue dragons remember fondly.", ["objectivesText"] = "Gather supplies for the Azure Hatchling's nest. Awakened Frost can be collected from many elementals across the Dragon Isles, created by combining 10 Rousing Frost, or bought from the auction house. Progress: I have raised dozens of blue whelps at all stages of life. At this point, their needs are second nature to me.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 190329, 202330, 202332 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73005] = { ["id"] = 73005, ["name"] = "Crystal Nutrition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73005 }, ["description"] = "Yes, blue dragons eat normal food, but the most important part of their diet is magical in nature. Wherever the blue flight can be found, you can be sure there is a source of nutritious ley crystals nearby. Of course, the homelands of the blue dragons became home to many others during their absence. The brackenhide gnolls have settled in our lands with the most ley crystals and taken them for themselves. You will need to enter their camps to reclaim the crystals for our whelp.", ["objectivesText"] = "Gather 6 Bite-Sized Ley Crystals from Brackenhide Hollow for the Azure Hatchling. Progress: From the moment they hatch, dragons have incredibly sharp teeth.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202404 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73006] = { ["id"] = 73006, ["name"] = "Well, Actually...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73006 }, ["description"] = "As expected, our dear blue whelp is quite the little \"bookwyrm\". I knew many hatchlings just like him in Aszuna, though we only had a small collection of scrolls. While there are books aplenty here in Valdrakken, whelps need to get up and moving! Why don't you play some tag?", ["objectivesText"] = "Play with the Azure Hatchling .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73007] = { ["id"] = 73007, ["name"] = "New Lenses", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73007 }, ["description"] = "Zalethgos is a bright child, but as he has gotten older we have realized something very clear about him. He has terrible eyesight! He is constantly speaking of things being fuzzy and of not being able to tell where one thing ends and the next begins. There is a salon just across the bridge in Valdrakken. Please, accompany Zalethgos to try to find him the perfect pair of glasses to aid his vision.", ["objectivesText"] = "Bring Zalethgos to the Victorious Visage in Valdrakken to find a suitable pair of glasses. Progress: I look forward to Zalethgos learning that sharp edges exist!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 202409 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73008] = { ["id"] = 73008, ["name"] = "A Scholar's Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73008 }, ["description"] = "Long ago in Aszuna, young blue whelps from Azurewing Repose often studied magic alongside the elves of Nar'thalas Academy. I have many fond memories of the place, but one stands out among the others. The enchanted books, while excellent to study, were quite the rascals. I have heard Lysindra acquired a similar book. I think this would be the perfect pet for Zalethgos!", ["objectivesText"] = "Obtain an Enchanted Book pet for Zalethgos. Progress: Enchanted books are the perfect companions. They are full of magic, knowledge, and fun! Additionally, you do not need to feed them.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73009] = { ["id"] = 73009, ["name"] = "Sight Isn't Everything", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73009 }, ["description"] = "Since getting his glasses, Zalethgos has been relying heavily on his eyesight. Of course, this is normal, but he needs to remain flexible in case he loses them. I believe it is time to turn out the lights. I think Wurallie has the perfect trick. She believes she can teach Zalethgos to find victory even when he cannot use his eyes. Please join them in the Waking Shores.", ["objectivesText"] = "Help Zalethgos overcome his insecurity about his eyesight. Progress: In order to grow into a well-rounded dragon, Zalethgos must use everything at his disposal.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206974 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73010] = { ["id"] = 73010, ["name"] = "The Emerald Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73010 }, ["description"] = "An egg from the green dragonflight is ready to hatch. Report to Zahkrana in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Emerald Oathstone to hatch in a location strong with their flight's power. Once this is complete, return here with the hatchling, where we will further take care of it.", ["objectivesText"] = "Collect the Green Dragon Egg at the Ruby Lifeshrine then hatch it at the Emerald Oathstone. Progress: Have you brought the newest hatchling?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73011] = { ["id"] = 73011, ["name"] = "Home Sweet Dirt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73011 }, ["description"] = "Green dragons prefer a home that is both natural and mystical, imbued with the power of the Emerald Dream. The Emerald Gardens will certainly have many materials with which to build an appropriate nest for this little one. Perhaps we should speak to a member of their flight to find something to bring them comfort as well.", ["objectivesText"] = "Gather supplies for the Emerald Hatchling's nest. Progress: We will have to maximize this hatchling's comfort to allow them to rest well and grow.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 67108, 202694, 202695, 202696 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73013] = { ["id"] = 73013, ["name"] = "So... Tired...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73013 }, ["description"] = "I have some worries about our new green friend. They are not sleeping as much as most green whelps tend to do. They seem to be having trouble sleeping. Why don't you get them up and moving around with a game of tag?", ["objectivesText"] = "Play with the Emerald Hatchling . Progress: Every whelp loves a game of tag!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73014] = { ["id"] = 73014, ["name"] = "A Green Who Can't Sleep?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73014 }, ["description"] = "<name>... we have a problem. Posidriss has insomnia. I did not even know it was possible for a green dragon to not be able to fall asleep! How are they to learn to protect the Dream if they cannot enter it? Please, try anything you can think of to help Posidriss fall asleep.", ["objectivesText"] = "Try to help Posidriss fall asleep. Progress: Every green dragon needs to be able to sleep!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 196584, 203621 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73015] = { ["id"] = 73015, ["name"] = "A Sleepy Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73015 }, ["description"] = "Posidriss's sleeping troubles are still causing them many problems. This is preventing them from developing their connection to the Dream. Bears hibernate, bears dream, bear cubs are soft, warm and cuddly. Some of the cubs in the Dragon Isles are even connected to the Dream. Can you fetch one from Lysindra for Posidriss?", ["objectivesText"] = "Obtain a Bear Cub pet for Posidriss. Progress: Where there are bears, there are druids. And where there are druids, there are green dragons!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73016] = { ["id"] = 73016, ["name"] = "Hibernation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73016 }, ["description"] = "Posidriss 's companion has been helping them with their severe insomnia, but I worry that they are still falling behind other whelps in their connection to the Dream. Perhaps we can aid them through a pet battle! Green dragons often protect the Dream from the Nightmare, and Wurallie has found the perfect critter for them to practice this on. It is mostly harmless.", ["objectivesText"] = "Help Posidriss defeat the Nightmare critter.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 206979 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73021] = { ["id"] = 73021, ["name"] = "A Lesson in Responsibility", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73021 }, ["description"] = "The daycare is always looking for new activities to enrich the education of the whelps. Lasztak has suggested a class pet might help teach the whelps responsibility. Sir Pringly has been my personal companion for some time, and I believe his calm demeanor and sense of fun would serve the position well. Sir Pringly will need his own habitat for the daycare, however. If you would gather materials, we can prepare a space just for him.", ["objectivesText"] = "Gather materials for Sir Pringly's habitat. Progress: There is a particular way that Sir Pringly likes his habitat constructed. If you get the materials I listed, he should like it.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 203445, 203446, 203451 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73064] = { ["id"] = 73064, ["name"] = "Spellwrought Snowman", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["storyline"] = { 73064 }, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[73077] = { ["id"] = 73077, ["name"] = "This Might Sting", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73077 }, ["description"] = "Relax. This Sundered Flame is merely poisoned. He won't die. Probably. He will just be in pain. < Patroclosa looks at you, then sighs.> I suppose if you wanted to spare him this fate, you could collect bile from the Quartzite Sporebats that roam this valley. It contains a natural antivenom that would ease his suffering. But I will not waste my healing magic on a murderer. And you may as well bring back loamshrooms, to help him keep the bile down. Though it's a kindness he doesn't deserve.", ["objectivesText"] = "Collect 8 Spongy Loamshrooms and 6 helpings of Quartzite Spore Bile . Progress: We all have to find our own path. I just wish ours was a little bit easier...", ["rewardGold"] = 303800, ["rewardXP"] = 4925, ["rewardItems"] = { 203393, 204088 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200550, ["x"] = 0.594, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200582, ["x"] = 0.594, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73081] = { ["id"] = 73081, ["name"] = "Stress Fractures", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73081 }, ["description"] = "Another member of the Sundered Flame has been apprehended on Scalecommander Emberthal's behalf. A messenger, Amythora thinks. We must decide what to do with him. In the meantime, it would be helpful if you could see if he has any important information. He is well-guarded, so don't worry about him putting up a fight. Some passing Dracthyr offered their aid-- said they were companions of the Scalecommander! And they knew just how to handle Sundered Flame prisoners.", ["objectivesText"] = "Investigate the captured Sundered Flame messenger. Progress: I know you want me to talk, but I can't. Whatever you do to me, Sarkareth's punishment would be a thousand times worse.", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203233, ["x"] = 0.564, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200876, ["x"] = 0.556, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73085] = { ["id"] = 73085, ["name"] = "Cold Feet", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 73085 }, ["description"] = "If Marithos and Amythora want to run off and play adventurer, that's their choice. I have a sense of loyalty. <Despite his bold words, the messenger looks uncertain.> You don't know what Sarkareth is capable of, all right? Look through my things and draw whatever conclusions you'd like. But I won't tell you anything. I can't.", ["objectivesText"] = "Examine the apprehended dracthyr's belongings for clues about the Sundered Flame. Progress: Did you find anything? And why do you look like you've been in a scuffle? ...Oh. I see. That's quite troubling. < Marithos sighs.>", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204436 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200876, ["x"] = 0.556, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203233, ["x"] = 0.564, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[73086] = { ["id"] = 73086, ["name"] = "Healthy Competition", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73086 }, ["description"] = "More of my creche mates have been welcomed under Emberthal's leadership, but there are still tensions between the former Sundered Flame and the dracthyr we've hurt. Fortunately, I think I've found a way to work out those tensions in a productive, dracthyrian method that will reinforce our bonds as evokers. Sparring! Now, come on. Try me! We can show all these louts how it's done.", ["objectivesText"] = "Beat Amythora at sparring.", ["rewardGold"] = 262100, ["rewardXP"] = 4925, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203325, ["x"] = 0.262, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203325, ["x"] = 0.262, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73093] = { ["id"] = 73093, ["name"] = "Empty Chairs", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["requiredRaces"] = { 52, 70 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73093 }, ["description"] = "I don't want to detract from the festivities, but there's someone missing who should be here. This is a time for all dracthyr to come together, but Rathane might not see it that way-- he was Sundered Flame, just like us. And though he left them after what happened at the Aberrus, I fear he's still grappling with the guilt. He seemed rather distressed. Would you go find him? And make sure he's alright, and that he knows he's welcome?", ["objectivesText"] = "Find Rathane .", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 204824, 204830, 205252 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203629, ["x"] = 0.2392, ["y"] = 0.36 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203852, ["x"] = 0.242, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2392, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73119] = { ["id"] = 73119, ["name"] = "A Wealth of Whelp Snacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73119 }, ["description"] = "Agapanthus says there are more snack orders ready to be retrieved, but we both have our hands full. Would you run out and collect snacks while we tend the whelps?", ["objectivesText"] = "Gather snack orders from vendors in Valdrakken. Progress: Luckily we are not meant to eat the snacks ourselves, just understand what the whelps want so we can provide that. Cheese and crackers are clearly what they desire.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 202265, 202266, 203386, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73120] = { ["id"] = 73120, ["name"] = "Appetizing Aftermath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73120 }, ["description"] = "Today's activities were interrupted by a spontaneous food fight. This has attracted several undesirable visitors to the daycare! Please help clean up.", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: It is interesting, being a janitor, educator, and minder, but I suppose that is what all caretakers become.", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199259, ["x"] = 0.127, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.127, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73124] = { ["id"] = 73124, ["name"] = "Hoard Behavior", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73124 }, ["description"] = "The whelps like to spend time with Sir Pringly, but their treading over the space has worn down his habitat. Would you retrieve another shrubbery for him? And while you are out, he could use an adorable new toy. And incense. We cannot let his space fall into disrepair, of course.", ["objectivesText"] = "Gather materials for Sir Pringly's habitat. Progress: Beyond the particular shade of green, Sir Pringly only cares that a natural material adorn his space.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 202399, 202400, 202690, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73126] = { ["id"] = 73126, ["name"] = "Arts and Crafts and Baths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73126 }, ["description"] = "Our arts and crafts activities today have gotten well out of hand. One of the whelps enchanted their brush and the rest followed suit. Now there is a coat of paint over everything. Please clean up the daycare while we get the paint off the whelps.", ["objectivesText"] = "Help clean up paint around the Little Scales Daycare. Progress: This paint was supposed to be washable, but it sticks to whelp scales like nothing else.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73128] = { ["id"] = 73128, ["name"] = "Off the Page", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73128 }, ["description"] = "$p, the whelps are begging us to tell them a story from their favorite anthology, but we are absolutely exhausted. The book the whelps gravitate towards is enchanted and makes every retelling a workout. Would you mind taking over for a spell and tackle story time for us?", ["objectivesText"] = "Battle the villains of various stories for the whelps at the Little Scales Daycare. Progress: I have heard these stories many times now. Battling them every day is tiring, to say the least.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73130] = { ["id"] = 73130, ["name"] = "Fowl Runic Scribblings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73130 }, ["description"] = "Our magic rune lesson yesterday has apparently bled into today. The whelps are keen on practicing their runes anywhere they can, prudent or not. This fascination has led to an interesting playtime period! Please, help us return the toys to their proper place and dispel any runes you come across.", ["objectivesText"] = "Help put the Little Scales Daycare back into order. Progress: We really ought to teach them runes for something helpful, like stone polishing... That would have gone a long way here.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 182082, ["x"] = 0.1276, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.1276, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73131] = { ["id"] = 73131, ["name"] = "Dignified Disguises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73131 }, ["description"] = "$p! I have crafted masterful disguises for me and my friends, but there is only one way to know if they are perfect. Let's play hide and seek! Find us in Valdrakken and I will know my disguises need work!", ["objectivesText"] = "Find Belastrasza and her friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199990, ["x"] = 0.105, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199990, ["x"] = 0.105, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.105, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73132] = { ["id"] = 73132, ["name"] = "Scanning the Stacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73132 }, ["description"] = "Hi, $p! Do you want to play a game? I have been reading about the greatest hide and seek game in all of Azeroth! I think I can improve on the strategies this book suggests. Let us play a round and test my hypothesis!", ["objectivesText"] = "Find Zaleth and his friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199985, ["x"] = 0.098, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199985, ["x"] = 0.098, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.098, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73133] = { ["id"] = 73133, ["name"] = "Cozy Camouflage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73133 }, ["description"] = "< Posidriss yawns.> I just can't sleep. Let's play a game instead! Maybe there's a comfy hiding spot out there somewhere. I bet you can't find me in the city!", ["objectivesText"] = "Find Posidriss and their friends in Valdrakken.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199987, ["x"] = 0.16, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199987, ["x"] = 0.16, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.16, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73134] = { ["id"] = 73134, ["name"] = "Eternal Escapades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73134 }, ["description"] = "Ah--ACHOO! Sorry. Do you want to play hide and seek? I found new places to hide and I want to play! I hope my allergies don't stir up any trouble!", ["objectivesText"] = "Find every Zhusa in Valdrakken. Progress: I don't remember you coming back so soon. You were fast this time!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199986, ["x"] = 0.139333, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199986, ["x"] = 0.139333, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.139333, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73135] = { ["id"] = 73135, ["name"] = "Obsidian Obfuscation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 73135 }, ["description"] = "Hi, $p. <Ruszi looks around nervously.> Do you want to play hide and seek with me? I think it would be very good training. I need to watch out for danger, so it is good to know where to hide. Will you help me practice?", ["objectivesText"] = "Find Ruszi and her friends in Valdrakken. Progress: If I am hiding, then maybe they will not find me!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 205165 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 198612, ["x"] = 0.115, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 198612, ["x"] = 0.115, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.115, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[73169] = { ["id"] = 73169, ["name"] = "The Lunar Festival", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Lunar Festival", ["expansion"] = 9, ["zoneID"] = 14771, ["mapID"] = 2112, ["storyline"] = { 73169 }, ["series"] = { 8867, 8870, 8871, 8872, 8873, 8874, 8875, 8883, 73170 }, ["description"] = "It's that time of the year, <name>! The Cenarion Circle invites all denizens of Azeroth to partake in a celebration of the Lunar Festival. You will find the Lunar Festival Harbinger in Stormwind at a location marked by a blessed circle of moonlight. She can tell you more about the holiday.", ["objectivesText"] = "Talk to the Lunar Festival Harbinger in Stormwind City.", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 15895, ["x"] = 0.3335, ["y"] = 0.5165 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 37, 2112, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
