[73183] = { ["id"] = 73183, ["name"] = "Wanna Play a Game?", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 73183 }, ["series"] = { 75221 }, ["description"] = "<You open a scribbled note.> Heya pal! The name's Mizzen , and I hear you're pretty good at findin' stuff. See, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins. How about we meet up and I'll tell you where to find some?", ["objectivesText"] = "Speak with Mizzen in Valdrakken .", ["rewardItems"] = { 202162, 202163, 202183, 202261, 202395, 204731 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 204731 } },
[73192] = { ["id"] = 73192, ["name"] = "Feathered Fiend", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 73192 }, ["description"] = "The trinket appears to be some sort of Noblegarden decoration. It should probably be returned to the festivities in Goldshire.", ["objectivesText"] = "Bring the Noblegarden Trinket to Zinnia Brooks at Goldshire.", ["rewardItems"] = { 210594, 212599, 212698, 212699, 212701, 212711, 212715, 212985, 213428, 216874 }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 }, ["startItems"] = { 210594 } },
[73196] = { ["id"] = 73196, ["name"] = "Tarecgosa's Rest", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 73196 }, ["description"] = "<name>, hold a moment. Before you leave... I have one more thing that needs to be done. There is one last member of my kin that deserves rest.", ["objectivesText"] = "Speak with Kalecgos about Tarecgosa. Progress: Grief is a burden shared...", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 71086 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[73197] = { ["id"] = 73197, ["name"] = "Love Unending", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 73197 }, ["description"] = "Alongside a proper conduit to house Tarecgosa's soul during the ritual, we need enough magical essence to ground the flower. The bronze dragonflight was involved in creating the staff you hold, so I believe it best we use their magic again. Some of the sand within the Temporal Conflux should suit this purpose perfectly. Just make sure it's of the more magical variety.", ["objectivesText"] = "Gather Ephemeral Sand from the Temporal Conflux. Progress: How goes the hunt for the sand?", ["rewardGold"] = 28900, ["rewardXP"] = 615, ["rewardItems"] = { 71086, 202703 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200979, ["x"] = 0.656, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[73198] = { ["id"] = 73198, ["name"] = "Forget Her Not", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 73198 }, ["description"] = "The staff was made with the bough of a world tree, so the receptacle that the soul is transferred to needs to be comparable. Within the adverse conditions of Vakthros there may be a flower that is tenacious enough to grow. However, it will be fragile given the circumstances. Find it, and then bring it to one of the green dragonflight's groves to help strengthen it.", ["objectivesText"] = "Collect a Manaheart flower and bring it to the Ancient Bough to bloom. Progress: Did you find it? It grows very rarely.", ["rewardGold"] = 30900, ["rewardXP"] = 615, ["rewardItems"] = { 44362, 44363, 44364, 44365, 44785, 44788, 46723, 46800, 46824, 116404, 203855, 203913, 258990 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 190000, ["x"] = 0.394, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 200979, ["x"] = 0.656, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 2024, 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
