[74476] = { ["id"] = 74476, ["name"] = "Slime Dies When You're Having Fun", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 74476 }, ["description"] = "The investigators here told me that there were some side effects to removing the time anomaly from Eon's Fringe. Seems a bunch of slimes snuck through the timestream in the process. Oh! Oh! Time slimes ! They're Time slimes ! Ha. Anyway, could you take some of them out?", ["objectivesText"] = "Kill 12 Time Slimes .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[74495] = { ["id"] = 74495, ["name"] = "The Tale of Hraxian", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74495 }, ["description"] = "Hello <name>, it is good to see you. Would you like to join us around the fire? I think it is time we heard a positive story about the obsidian flight of old. I once promised yourself and Voraxian I would tell you the story from the vase you found in the Zskera Vaults. I believe it is that time.", ["objectivesText"] = "Listen to the tale of Hraxian. Progress: It is always a pleasure, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204220 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 200298, ["x"] = 0.465, ["y"] = 0.4805 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.4805 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[74501] = { ["id"] = 74501, ["name"] = "Suffusion Camp: Cinderwind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74501 }, ["objectivesText"] = "Suffusion Crucible looted Crucible guardian slain Suffusion Mold looted Forgemaster slain", ["rewardItems"] = { 200454, 203430, 203683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13645 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Suffusion Crucible looted", ["amount"] = 1, ["type"] = 14, ["objectID"] = 142839, ["orderIndex"] = 0 }, { ["text"] = "Crucible guardian slain", ["amount"] = 1, ["type"] = 0, ["objectID"] = 201054, ["orderIndex"] = 1 }, { ["text"] = "Suffusion Mold looted", ["amount"] = 1, ["type"] = 14, ["objectID"] = 144052, ["orderIndex"] = 2 }, { ["text"] = "Forgemaster slain", ["amount"] = 1, ["type"] = 0, ["objectID"] = 201625, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[74514] = { ["id"] = 74514, ["name"] = "The Slowest Fan Club", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74514 }, ["description"] = "Has a crowd ever roared for you? Everyone shouting your name, pushing you on to victory? I want to give that same feeling to Slick. Give him the taste of being a champion. Course, we don't speak snail, so we can only be so useful. Round up some snails that could use purpose in their lives. Slick needs a fan club.", ["objectivesText"] = "Collect 8 Aimless Snails. Progress: A race track ain't no race track without fans to watch the race. That's just facts.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204178 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5995 } },
[74515] = { ["id"] = 74515, ["name"] = "Snail Mail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74515 }, ["description"] = "Racing snails are all about speed, but riding snails? They need stamina to boot. I owe some supplies to a buddy in Loamm. Why don't you make the delivery for me? Help build Slick's endurance. Oh, and make sure you don't dismount. Not much of a training session if you keep hopping off and on.", ["objectivesText"] = "Deliver the package to Terryn in Loamm without dismounting Slick. If you get dismounted from Slick, Briggul can give you a new delivery. Progress: This buddy of mine, always asking for supplies. I got snails to train!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203708, 205155 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5995 } },
[74516] = { ["id"] = 74516, ["name"] = "A Snail's Pace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74516 }, ["description"] = "It's an off day for our local racing track, so I figured we could take the opportunity to build up Slick's speed. Grow some confidence on his home turf, I'm thinking. Take two laps around the track. Let's see how your training is coming along!", ["objectivesText"] = "Collect 1 Lap Markers by doing two laps around the snail track. Progress: Not every day needs to be at a hundred, you know? Even in the fast-paced world of snail racing.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 203708 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5995 } },
[74517] = { ["id"] = 74517, ["name"] = "All Terrain Snail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74517 }, ["description"] = "While life in these caverns is plenty exciting, Slick has a future in the world above. Namely as your trusty mount. Which means he needs to prepare for all sorts of environments. Luckily, the Dragon Isles has biomes to spare. Why don't you take him for a spin? Give him a taste of what's to come. One lap per location should do the trick.", ["objectivesText"] = "Ride Slick through Snail Markers in Restless Wetlands, Wanderer's Steppe, Upper Frostlands, and Shifting Sands. Progress: I don't do too well above ground, myself. All that sunlight and fresh air just plays havoc on my sinuses.", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["rewardItems"] = { 203708, 205155 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5995 } },
[74518] = { ["id"] = 74518, ["name"] = "Resistance Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74518 }, ["description"] = "These caverns aren't easy on my poor snails, which is why I feed them a special crystal diet. Keeps their shells hard and gleaming. Slick eats more than his fair share though, so I'm plumb out. Would you collect some crystals in Zaralek Cavern ? Get a nice mix, too. We need to make sure Slicks ready for every environment.", ["objectivesText"] = "Collect 5 Glowing Crystals , 5 Sulfuric Crystals , and 5 Magma Crystals from around Zaralek Cavern . Progress: Everyone says they want their snails to have strong, healthy shells, but when it comes time to collect the crystals? They're too busy, they're too scared. Crokin' cowards..", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204067, 204069, 204070 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5995 } },
[74520] = { ["id"] = 74520, ["name"] = "Less Cargo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74520 }, ["description"] = "Those djaradin think they own these caverns, coming around here and looting our supplies. How am I supposed to train champions under these conditions? Can you do me a favor and get those supplies back? I can't help you train Slick without them. Besides, the big fellow could use a rest day.", ["objectivesText"] = "Collect 10 Stolen Supplies from djaradin in Igira's Watch. Progress: Shell polish, mucus paste, racing rocks... Crok it all, we need those supplies back!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204273 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5995 } },
[74568] = { ["id"] = 74568, ["name"] = "They Who Would Burn Us", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74568 }, ["description"] = "The djaradin and their Primalist allies are a stain upon the land, <name>. Wipe them from it.", ["objectivesText"] = "Slay djaradin and Primalists assaulting the Ohn'ahran Plains. Progress: How goes the battle?", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204732, 204733, 204735, 204736, 204741, 204742, 204743, 204744, 204745, 204746, 204747, 204748, 204749, 204750, 204752, 204753, 204754, 204755, 204758, 204759, 204760, 204761, 204762, 204763, 204764, 204766, 204767, 204768, 204769, 204770, 204771, 204772, 204773, 204774, 204775, 204776, 204777, 204778, 204780, 204781, 204782, 204783, 204784, 204785, 204787, 204789, 204901 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201090, ["x"] = 0.75, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201090, ["x"] = 0.75, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74569] = { ["id"] = 74569, ["name"] = "Deny Them Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74569 }, ["description"] = "This entire invasion has been carried out with the sole objective of infusing raw materials with elemental power on an unprecedented scale. While we may not know Fyrakk's ultimate goal, frustrating his efforts seems straightforward enough. If he wants these materials, we will deny them to him.", ["objectivesText"] = "Recover infusion supplies from Fyrakk's forces. Progress: Leave him nothing.", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204699, 204732, 204733, 204735, 204736, 204738, 204740, 204742, 204743, 204744, 204745, 204746, 204750, 204752, 204753, 204754, 204758, 204759, 204760, 204761, 204763, 204764, 204766, 204768, 204769, 204771, 204772, 204774, 204776, 204777, 204778, 204780, 204782, 204784, 204785, 204789, 204896, 204897, 204898 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74570] = { ["id"] = 74570, ["name"] = "Aid Our Wounded", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74570 }, ["description"] = "<name>, our forces were not prepared for such an onslaught. These djaradin fight with more furor than the forces we have faced in the past. We have wounded behind enemy lines. If you possess knowledge of how to heal then I ask you employ it. If you do not, we have bandages to aid the wounded with. Please help bring our people out of the fire.", ["objectivesText"] = "Heal 6 Wounded Guardians using the provided bandages or your own abilities. Progress: Our healers cannot be everywhere at once. Nor will they last long behind enemy lines.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 198048, 200454, 203731, 204075, 204732, 204733, 204745, 204762, 204764, 204765, 204766, 204770, 204772, 204773, 204775, 204778, 204779, 204780, 204785, 204786, 204898, 204901 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74571] = { ["id"] = 74571, ["name"] = "Clear a Path", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74571 }, ["description"] = "The djaradin are fortifying their beachhead. We cannot allow them to dig in any deeper or we risk their advances becoming permanent. Destroy their barricades before that can happen.", ["objectivesText"] = "Destroy djaradin barricades . Progress: Leave them nothing to cower behind.", ["rewardItems"] = { 198048, 200454, 204075, 204733, 204735, 204739, 204745, 204746, 204747, 204748, 204749, 204752, 204754, 204755, 204768, 204769, 204776, 204782, 204789, 211279 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201876, ["x"] = 0.753, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201876, ["x"] = 0.753, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.753, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74572] = { ["id"] = 74572, ["name"] = "Make it Rain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74572 }, ["description"] = "The djaradin are setting the Plains ablaze with the reckless use of fire magic. We must act before these small sparks grow into a raging wildfire. A deep pool of fresh water can be found not far from here. Skim the surface on your drake to collect as much as you can carry, then fly over the djaradin camp to douse any flames beneath you. This won't be enough to put out the larger blazes, but it will buy us time.", ["objectivesText"] = "Extinguish fires across the djaradin camp. Progress: Quickly, before the blaze spreads!", ["rewardItems"] = { 198048, 200454, 204075, 204732, 204758, 204760, 204761, 204762, 204764, 204765, 204766, 204770, 204772, 204773, 204774, 204778, 204779, 204780, 204783, 204786, 204787, 204897 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201861, ["x"] = 0.755, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74573] = { ["id"] = 74573, ["name"] = "Aerial Support", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74573 }, ["description"] = "The Primalist portals must be destroyed if we are to prevent them from infusing these raw materials with elemental energy. Unfortunately, their structures are too heavily warded for any single attack, whether mortal or draconic, to do lasting harm. Together, though, there is a way. Take this seed. Use it to weaken their defenses and we will be able to strike before they have a chance to react.", ["objectivesText"] = "Weaken the portals' defenses. Progress: We are counting on you, <class>.", ["rewardItems"] = { 198048, 198059, 200454, 204075, 204673, 204732, 204733, 204738, 204741, 204742, 204743, 204745, 204746, 204747, 204748, 204749, 204750, 204751, 204752, 204753, 204754, 204755, 204756, 204758, 204759, 204760, 204761, 204762, 204763, 204764, 204765, 204766, 204767, 204769, 204770, 204771, 204773, 204774, 204775, 204777, 204779, 204780, 204781, 204783, 204784, 204785, 204786, 204787, 204788, 204896, 204897, 204898 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard" },
[74775] = { ["id"] = 74775, ["name"] = "Disciple of Fyrakk: Kretchenwrath", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 74775 }, ["description"] = "<Fyrakk's disciple has fallen. Perhaps the remains of this beast will bring some comfort to those whose land has been ravaged.>", ["objectivesText"] = "Collect the Head of Kretchenwrath . Progress: I heard you faced a disciple of Fyrakk.", ["rewardGold"] = 4213500, ["rewardXP"] = 12250, ["rewardItems"] = { 201923, 204071, 204195 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 181198, ["x"] = 0.6, ["y"] = 0.375 }, { ["mapID"] = 2023, ["npcID"] = 201860, ["x"] = 0.756, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 204071 } },
[74786] = { ["id"] = 74786, ["name"] = "Snailspiration: Shimmershell Snail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 74786 }, ["description"] = "I smell a snail on you, but it's strange. You holding out on me? Not many people know this, but snails are incredibly susceptible to peer pressure. Show off that wonder-snail you got there, and let's get Slick inspired.", ["objectivesText"] = "Summon a max-level Shimmershell Snail battle pet and show it to Briggul . Progress: Show me that snail! Let's inspire Slick to be his best slimy self.", ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
