[74942] = { ["id"] = 74942, ["name"] = "Grime Lies Where You're Killing Slimes", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 74942 }, ["description"] = "Did you see that? Some of the slimes are leaving little piles of grime behind. Hmm... Melly makes stuff out of all kinds of things. You think she could use the grime to help out Tempo? I bet she could.", ["objectivesText"] = "Collect Time Grime . Progress: Time grime ! I'm on a roll here.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 204263 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
