[75148] = { ["id"] = 75148, ["name"] = "Ancient Techniques", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75148 }, ["description"] = "I've heard tales that the djaradin forge their blades with magic so hot that they can actually quench the metal with lava. Lava! It's like ice water compared to the heat their magic creates! But I've never been able to verify it for myself. They aren't exactly peddling their wares at the market. You smell like battle, though. Go and fetch some of their weapons for the blacksmiths back in Loamm and we'll see if the legends are true, eh?", ["objectivesText"] = "Collect 8 Lava-Quenched Blades . Progress: I find the tales hard to believe, but then again... they do live in magma pits!", ["rewardItems"] = { 198606, 204434 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203170, ["x"] = 0.57, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[75149] = { ["id"] = 75149, ["name"] = "Obsidian Essays", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75149 }, ["description"] = "It's not common these days, but we do have a few of our histories in writing--well, carvings really. We can trace the etchings with our fingers! We used to use clay tablets for this, but they were brittle, and prone to breaking. Not good if you want to preserve history! I hear the djaradin carve their important texts into volcanic glass. If they can manage that without shattering the tablets, we could probably learn a thing or two from their techniques! Take some samples back to Loamm for study.", ["objectivesText"] = "Collect 10 Obsidian Tablets . Progress: New knowledge can come from the strangest sources!", ["rewardItems"] = { 198607, 204435 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203171, ["x"] = 0.558, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75150] = { ["id"] = 75150, ["name"] = "Incandescence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75150 }, ["description"] = "Some of our incense needs to be burned very slowly to release the right aromas. You can check the heat yourself, of course--but it gets to be a bother. Fortunately, I've found a solution! If you grind up shards of fire elementals and sprinkle the dust over the incense, you can keep the heat consistent using enchantments. Completely hands-free! Those shards are a bit hard to come by, though. Could you find some and bring them to my friends back in Loamm?", ["objectivesText"] = "Collect 8 Everburning Fireshards . Progress: Elder Honeypelt usually brings us back a stock of shards when she returns from a hunt, but I'd hate to bother her again so soon.", ["rewardItems"] = { 198610, 204433 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203172, ["x"] = 0.56, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
