[75203] = { ["id"] = 75203, ["name"] = "Absent Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 75203 }, ["description"] = "I am concerned about our queen. Alexstrasza left to gather her thoughts some time ago and has not yet returned. I have no real cause for concern, but with all that has happened, I cannot help but fear for her well-being. Please ease an old dragon's mind and ensure she is alright.", ["objectivesText"] = "Check on Alexstrasza.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[75221] = { ["id"] = 75221, ["name"] = "Find a Rumble Coin", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 75221 }, ["series"] = { 73183 }, ["description"] = "To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin here in the Roasted Ram. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!", ["objectivesText"] = "Find a Rumble Coin in the Roasted Ram and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.", ["rewardItems"] = { 202162, 202163, 202183, 202261, 202395 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
