[75286] = { ["id"] = 75286, ["name"] = "Blacksmith's Back", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75286 }, ["description"] = "The kith of Loamm request the skills of a seasoned blacksmith! We've heard of the wonders you uplanders make with smelted ore! Our Kilnmaster, Mister Crubus, has heard you have devised a way to dig without claws or earth magic! What a wonderful invention! Please deliver some of these \"shovels\" as soon as you can, won't you?", ["objectivesText"] = "Deliver Sturdy Expedition Shovels to Kilnmaster Crubus in Loamm. Progress: Who are you? Oh, Kayann sent you? Well, do you have what I asked for or what?", ["rewardItems"] = { 191294, 191304, 204985, 205188 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203170, ["x"] = 0.57, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[75288] = { ["id"] = 75288, ["name"] = "Enchanted Tales with Topuiz", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75288 }, ["description"] = "The kith of Loamm request the skills of an excellent enchanter! Magic is so prevalent in this wondrous city, it practically floats about on the breeze! Our chief Dustmonger and Sparklefinger, Mister Topuiz, has heard of the many different ways you enchant your clothes on the surface, and wishes to see some examples for himself! Please deliver those scrolls as soon as you can, won't you?", ["objectivesText"] = "Deliver scrolls of Enchant Cloak - Writ of Leech , Enchant Cloak - Writ of Speed , and Enchant Cloak - Writ of Avoidance to Dustmonger Topuiz in Loamm. Progress: Greetings, friend! You smell new! What brings you to the Dustmonger?", ["rewardItems"] = { 200034, 200035, 200036, 204985, 205188 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203172, ["x"] = 0.56, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
[75289] = { ["id"] = 75289, ["name"] = "Ink Master", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 75289 }, ["description"] = "The kith of Loamm request the skills of a scribe! We niffen have heard of the powerful magical writings you produce on the surface, and wish to smell your handiwork with our own noses! Our Chief Chiseler, Miss Scridorsa, has requested a sample of both pigment and runestone be brought below. Make a delivery to Loamm as soon as you can, won't you?", ["objectivesText"] = "Deliver Shimmering Pigments and Chilled Runes to Scridorsa the Chiseler in Loamm. Progress: Hmm? Can I help you? I'm very busy, you know!", ["rewardItems"] = { 194767, 198423, 204985, 205188 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203171, ["x"] = 0.558, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[75290] = { ["id"] = 75290, ["name"] = "Renowned with the Loamm Niffen", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75290 }, ["description"] = "Well hey there! We want to thank you for all your help. How about you meet me in Loamm, so we get you something nice? Keep up the good work!", ["objectivesText"] = "Speak with Mimuup in Loamm.", ["rewardItems"] = { 204712 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2565, ["threshold"] = 7500 } } } },
