[75368] = { ["id"] = 75368, ["name"] = "Stones and Scales", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75368 }, ["description"] = "I'm sure you've run into some of the mean beasties we have down in Zaralek while you were on your adventures! Have you seen any rock vipers yet? They're covered in both scales and stones! And have massive fangs! Mister Garram has offered a reward for anyone brave enough to bring him some of their hides! I'm sure he will make it worth your while!", ["objectivesText"] = "Collect 10 Scaly Stone Hides from rock vipers in Zaralek Cavern . Progress: Have you collected those hides yet? Those snakes are a little scary, but I think a <class> like you can handle them!", ["rewardXP"] = 1415, ["rewardItems"] = { 198613, 204800 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203644, ["x"] = 0.572, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.6245 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
