[75382] = { ["id"] = 75382, ["name"] = "Portal Combat", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75382 }, ["description"] = "The Primalists are channeling elemental forces through those portals, energizing their entire effort and speeding the production of these suffused ingots. Soon they will be stabilized enough to allow their elemental allies to pass through to reinforce their position. We have to seal them before that happens or the battle may turn against us. Take this focus and disrupt the portals' protective runes, then we can strike from above. Only together do we stand a chance.", ["objectivesText"] = "Weaken the portals' defenses. Progress: Together, <class>.", ["rewardItems"] = { 198048, 200453, 204075, 204746, 204758, 204759, 204761, 204768, 204769, 204773, 204776, 204781, 204782, 204786, 204789, 204896, 204897 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75383] = { ["id"] = 75383, ["name"] = "Hideaway No More", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75383 }, ["description"] = "This was supposed to be a peaceful retirement, not a warzone! Grab one of those totems the shamans left lying around and put out these fires before my dreams of a nice fishing retreat go up in smoke! Literally!", ["objectivesText"] = "Use a water totem to extinguish fires in Grimtusk's Hideaway. Progress: Who burns down an ice fishing hut?", ["rewardItems"] = { 198048, 198059, 200453, 204075, 204732, 204736, 204743, 204744, 204745, 204747, 204748, 204749, 204751, 204752, 204754, 204755, 204756, 204757, 204760, 204762, 204763, 204764, 204765, 204768, 204770, 204771, 204773, 204774, 204776, 204777, 204778, 204779, 204780, 204782, 204783, 204784, 204785, 204786, 204787, 204789, 204896, 204897, 204898, 204901 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203604, ["x"] = 0.584, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203604, ["x"] = 0.584, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75384] = { ["id"] = 75384, ["name"] = "Payback's a Mammoth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 75384 }, ["description"] = "Trying to kill me I can forgive, but attacking my Hideaway? Now it's personal. The djaradin are loading their mammoths with all the ingots they can bear to get them back to their precious Fyrakk. Hijack one and bring it back here, cargo and all.", ["objectivesText"] = "Mount an Overladen Mammoth and return it to your lines. Progress: What are you waiting for? A thaw?", ["rewardItems"] = { 198048, 198059, 200453, 204075, 204673, 204732, 204737, 204738, 204739, 204740, 204741, 204742, 204743, 204744, 204750, 204752, 204753, 204758, 204759, 204760, 204761, 204763, 204764, 204766, 204767, 204769, 204771, 204772, 204773, 204774, 204775, 204776, 204777, 204778, 204780, 204781, 204783, 204784, 204785, 204787, 204788, 204896, 204897 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 203604, ["x"] = 0.584, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 203604, ["x"] = 0.584, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
