[75625] = { ["id"] = 75625, ["name"] = "Wanna Play a Game?", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75625 }, ["series"] = { 75709 }, ["description"] = "<You open a scribbled note.> Heya pal! The name's Mizzen , and I hear you're pretty good at findin' stuff. See, I've been playin' this new game called Warcraft Rumble but I'm fresh outta coins. How about we meet up and I'll tell you where to find some?", ["objectivesText"] = "Speak with Mizzen at the Stormwind Harbor.", ["rewardItems"] = { 205189 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 205189 } },
