[75639] = { ["id"] = 75639, ["name"] = "Fel Suspicions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "At the risk of stating the obvious, something very wrong is going on. I know you feel it too. Madam Shadow is sending myself and the other initiates to the Altar of Storms, to try our hand at summoning demons. Please, $p, poke your head around here and see if you can't piece together what she's up to. I saw her and her servant heading towards the back of the faire... I'm sure she has her guard up. Maybe there's some way you can get close without drawing attention to yourself?", ["objectivesText"] = "Spy on Madam Shadow and Assistant Phineas in the Darkmoon Faire.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 5, ["flags"] = 0 } } },
[75657] = { ["id"] = 75657, ["name"] = "Time-Lost Trio", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2025, ["storyline"] = { 75657 }, ["description"] = "We have a teensy problem I could use your help with. But it's... complicated. Some time ago, King Varian Wrynn was in a gladiator trio with Broll Bearmantle and Valeera Sanguinar . Those three just showed up in this 'Field of Ferocity' place and they're not only taking on all challengers, they're beating them too! They won't return through our portals until they lose. Do you think you could find some friends and defeat them? We'll be able to convince them to go back if you can, I'm sure of it!", ["objectivesText"] = "Defeat Valeera, Broll, and Lo'Gosh. Progress: You need to speak with Gurgthock to start the round, then defeat the time-lost gladiators.", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 188871, ["x"] = 0.532, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2023, 2025 }, ["zone"] = { 13645 } }, ["questType"] = "group", ["db2LabelIDs"] = { 2705 } },
