[75706] = { ["id"] = 75706, ["name"] = "A Race to the Finish", ["level"] = 36, ["requiredLevel"] = 36, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75706 }, ["description"] = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win. You can help a snail win by giving it treats. Watch how fast it makes them go! Grab a bag of treats and toss them in the path of the snails. See if you can get Tricky to win!", ["objectivesText"] = "Help Tricky win a race. Progress: Has your snail won the race?", ["rewardGold"] = 309800, ["rewardXP"] = 4925, ["rewardItems"] = { 205119, 205121, 205123 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201099, ["x"] = 0.444, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75709] = { ["id"] = 75709, ["name"] = "Find a Rumble Coin", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 75709 }, ["series"] = { 75625 }, ["description"] = "To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin here at the docks. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!", ["objectivesText"] = "Find a Rumble Coin in Stormwind Harbor and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.", ["rewardItems"] = { 202162, 202163 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[75711] = { ["id"] = 75711, ["name"] = "Find a Rumble Coin", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 84, ["storyline"] = { 75711 }, ["series"] = { 75626 }, ["description"] = "To use this game machine, you need a Rumble Coin . There are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later. I stashed one coin over in the inn. If you find it, it's all yours, pal. Insert that Rumble Coin into the Rumble machine and watch the fun begin!", ["objectivesText"] = "Find a Rumble Coin in the Broken Tusk and insert it into the Warcraft Rumble machine . Progress: <The Warcraft Rumble machine stands before you. A small sign reads:> Insert Rumble Coin to play.", ["rewardItems"] = { 202162, 202163, 202395 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 201230, ["x"] = 0.423333, ["y"] = 0.468333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.423333, ["y"] = 0.468333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[75712] = { ["id"] = 75712, ["name"] = "Warcraft Rumble Minis: New Look!", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["storyline"] = { 75712 }, ["description"] = "<You find a message etched into the foil.> This Rumble Foil can be used at a Warcraft Rumble machine . Go and get a new look for one of your minis!", ["objectivesText"] = "Go to the Warcraft Rumble machine in Stormwind Harbor.", ["rewardGold"] = 28090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
