[75720] = { ["id"] = 75720, ["name"] = "Care to Barter?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75720 }, ["description"] = "Hey, Uplander! I hear you like helping. Maybe you could help me out? I need some packages sent to Valdrakken. If you don't peek and don't ask, I can make it worthwhile. Stop by when you're in Loamm. We can work out a deal! Your new friend, Ponzo .", ["objectivesText"] = "Talk to Ponzo in Loamm.", ["rewardGold"] = 16980, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75721] = { ["id"] = 75721, ["name"] = "Bartering 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75721 }, ["description"] = "So here's what I need you to do. A friend of mine, Kayann , went all the way up to Valdrakken . He's expecting a delivery from me. Can you get it to him? No questions, though. Don't look, don't smell, don't taste. This is for Kayann 's nose only! If that's all right with you, I'll send you on your way--with my thanks, of course!", ["objectivesText"] = "Deliver Ponzo 's box to Kayann in Valdrakken .", ["rewardItems"] = { 204985 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 204693, ["x"] = 0.58, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 203516, ["x"] = 0.365, ["y"] = 0.6245 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75722] = { ["id"] = 75722, ["name"] = "Bag of Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75722 }, ["description"] = "Hello, $p! I heard you've been helping us out! Good deeds should be rewarded--and I've got something special for you! Why don't you meet me in Loamm? Keep up the good work, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 204195 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75723] = { ["id"] = 75723, ["name"] = "Cavern Drakewatching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75723 }, ["description"] = "Well hey there, Uplander! Word is, you've been helping us out a lot! We got a little something for you in return. See me in Loamm and I'll hand it over! Best, Harlowe Marl", ["objectivesText"] = "Talk to Harlowe Marl in Loamm.", ["rewardItems"] = { 203310, 203316, 203327 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 202468, ["x"] = 0.564, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75724] = { ["id"] = 75724, ["name"] = "Like the Niffen Do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75724 }, ["description"] = "Hello there, $p! We want to thank you for all the help you've given us. It's only right! Meet me in Loamm and I'll teach you to dig like we niffen do! Sincerely, Mimuup", ["objectivesText"] = "Talk to Mimuup in Loamm.", ["rewardItems"] = { 205255 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204254, ["x"] = 0.565, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
[75725] = { ["id"] = 75725, ["name"] = "Off to the Track", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75725 }, ["description"] = "Hey Champ! We got a fresh golden opportunity for you. Snail racing! One of the most dynamic sports in the games! Ponzo said you'd be interested. Called you a real go-getter! So go! Get to the track in Glimmerogg! See ya there, Briggul", ["objectivesText"] = "Talk to Briggul in Glimmerogg.", ["rewardGold"] = 303800, ["rewardXP"] = 9920, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 205127, ["x"] = 0.564, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 201752, ["x"] = 0.442, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard" },
