[75877] = { ["id"] = 75877, ["name"] = "Time to Fly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 8568, ["storyline"] = { 75877 }, ["description"] = "Kul Tiras is home to many gryphons. One will accompany you into the skies. Visit Leila Stafford at the Tradewinds Market in Boralus.", ["objectivesText"] = "Find Leila Stafford .", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 206566, 206567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[75887] = { ["id"] = 75887, ["name"] = "Fyrakk's Forces", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2112, ["storyline"] = { 75887 }, ["description"] = "Champion, Fyrakk and his Primalist allies have struck a dark bargain with the djaradin. We have received word that their forces are assaulting the Dragon Isles in search of resources for some nefarious project. Please, champion, find one of these Suffusion Camps and assist any of our allies you can find there.", ["objectivesText"] = "Journey to a Suffusion Camp.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 205647, ["x"] = 0.492667, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 }, { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.492667, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024, 2112 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5478, ["name"] = "Suffusion Camp", ["orderIndex"] = 0, ["flags"] = 0 } } },
[75888] = { ["id"] = 75888, ["name"] = "Suffusion Camp", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2023, ["storyline"] = { 75888 }, ["description"] = "Fyrakk has made a deal with the dragon hunting djaradin! Their blacksmith, Igira, has sent her finest crafters under the aegis of Fyrakk's Primalists. They are gathering materials for the construction of... something. Find a way to access their Suffusion Crucibles and Molds. Keep what you find but we must learn more about what they are doing. The forces appear to require special wards to access the Crucibles and Molds. Start there.", ["objectivesText"] = "Loot a Suffusion Crucible and a Suffusion Mold. Progress: What have you found in the Crucibles and Molds? All of this shadowflame about makes my scales crawl.", ["rewardGold"] = 842700, ["rewardXP"] = 12250, ["rewardItems"] = { 203430, 203683 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 }, { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 201648, ["x"] = 0.752, ["y"] = 0.692 }, { ["mapID"] = 2024, ["npcID"] = 203520, ["x"] = 0.58, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 2023, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[75932] = { ["id"] = 75932, ["name"] = "Loamm Niffen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "emissary", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 75932 }, ["rewardGold"] = 280900, ["rewardXP"] = 4925, ["rewardItems"] = { 204712, 205983, 205985 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["worldSystems"] = { ["bounties"] = { { ["id"] = 465, ["factionID"] = 2564, ["bountySetID"] = 119 } } } },
[75935] = { ["id"] = 75935, ["name"] = "Time, Signature", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75935 }, ["description"] = "Oh good, an adventurer. You've heard of Pedgi, I presume? The composer? No? Well, don't tell him that. We were traveling to research his next song, when we stumbled upon a dragon named Tempo. Pedgi is now convinced they're the only one who can help us. Yes, because of the name. That's really all it takes for him. But Tempo here is, understandably, too busy to help us. Could you talk to them? See if we can help clear their schedule?", ["objectivesText"] = "See if Tempo would be willing to help Pedgi with his music. Progress: Yes, he's always like this. But he pays well and I get to travel.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[75936] = { ["id"] = 75936, ["name"] = "Slimy Yet Satisfying", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75936 }, ["description"] = "<A worm. You know someone who might love this.>", ["objectivesText"] = "Bring 1 Wriggling Worm to Marie Shellie in Loamm. Progress: < Marie Shellie drips slime.>", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205795 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 204356, ["x"] = 0.568, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205795 } },
[75949] = { ["id"] = 75949, ["name"] = "Downbeat Data", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75949 }, ["description"] = "You say that Tempo mentioned objects from other timelines? I have a device used for syncing melodies. Strangely enough, it seems to have the same effect on timelines in this town. Perhaps a side effect of the chaotic temporal energies here? I've upgraded Pedgi's glasses to allow him to observe the rhythms of the world. They may make it easier to find mis-timed entities. Ask if you can borrow them.", ["objectivesText"] = "Use Melly's device near objects from other timelines. Pedgi's sunglasses will make them easier to find. Progress: Have you found any mis-timed entities?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208235, 208236 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[75966] = { ["id"] = 75966, ["name"] = "Compose Yourself", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75966 }, ["description"] = "I promise he's not always like this. But he is, often, like this. Usually it takes him a few days to come out of his funk, but we don't have that sort of time. The commission he got to write this song won't last forever. Maybe we can speed up the process. Could you help raise Pedgi 's confidence?", ["objectivesText"] = "Raise Pedgi 's confidence. Progress: Hmm...", ["rewardGold"] = 280900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204987, ["x"] = 0.538, ["y"] = 0.8416 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[75970] = { ["id"] = 75970, ["name"] = "Tracked Through Time", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75970 }, ["description"] = "A Timewalker spotted a bear cub who stumbled into our present time. She was so frightened she ran off before he could catch her! Can you find the poor thing? You'll need to calm her down before she'll follow you. Bring her back here and I'll open a temporal portal to take her home.", ["objectivesText"] = "Rescue a Time-Lost Cub and return her to her proper time. Progress: That cub must be so scared, all alone and in a strange place. We need to get her back home!", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75971] = { ["id"] = 75971, ["name"] = "Squeaky Toy of Time and Space", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75971 }, ["description"] = "We have detected another time anomaly. A strange object that even we cannot understand the significance of. This artifact must be returned before it does irreparable damage to the true timeline and the world as we know it. Return here once you have recovered the artifact. I will open a portal so you may return it to its proper place.", ["objectivesText"] = "Find the Time-Displaced Toy and return it to its proper time. Progress: All of our fates depend on returning that artifact to its proper time.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206161, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75986] = { ["id"] = 75986, ["name"] = "Feats Per Minute", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75986 }, ["description"] = "Alright, one last problem to help solve. Succeed at this and we'll surely have earned an audience with Tempo! The investigators discovered another Time Slime. A much larger, powerful Time Slime. We've come to call it Time Slime Prime . Its temporal energies are greatly accelerated, making it especially deadly. I recommend using the metronographer several times to slow it back down before engaging in combat.", ["objectivesText"] = "Re-synchronize and defeat the Time Slime Prime .", ["rewardGold"] = 280900, ["rewardXP"] = 11895, ["rewardItems"] = { 206997, 208401 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204990, ["x"] = 0.538, ["y"] = 0.8416 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 195773, ["x"] = 0.548, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.8416 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[75987] = { ["id"] = 75987, ["name"] = "Woolomancer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75987 }, ["description"] = "Somehow, Jaina Proudmoore has found a magic wand. Not our Jaina, of course, but her childhood self. She is far too young to have access to such power. We need you to help clean up the mess she's made and confiscate that wand.", ["objectivesText"] = "Dispel 8 Polymorphed Creatures and confiscate Jaina's Wand of Mass Polymorph . Progress: Jaina must not practice magic until she is old enough to handle it responsibly. I trust you to put a stop to this before the situation becomes dire.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206368, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75988] = { ["id"] = 75988, ["name"] = "Lucky Hearthstone Card", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75988 }, ["description"] = "I was playing Hearthstone with my father when I somehow ended up here. Then some dragon whelps flew off with my lucky card to add it to their... card tornado? Then all the adults started saying I need to go home. But I can't leave without my lucky card! Can you please help me? I promise I'll go home if you bring it back for me!", ["objectivesText"] = "Kill the Enchanted Card Swarm and retrieve Anduin's Lucky Hearthstone Card . Progress: I feel a little better. Bob gave me some juice. But I still don't know what's going on. Where is this place? How did I get here?", ["rewardGold"] = 561800, ["rewardXP"] = 11895, ["rewardItems"] = { 206022, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205604, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205604, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75989] = { ["id"] = 75989, ["name"] = "The Black Prince Parade", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75989 }, ["description"] = "Five separate portals opened up here at the same time, and the same person stepped out of each one. Now we have an inn full of Wrathions. All different ages, dealing with different things in their own lives, and very eager to blame each other for their problems. Let's get them all back to their proper times before they cause too much trouble.", ["objectivesText"] = "Send each Wrathion back to his time through his temporal portal. Progress: All this commotion is bad for business.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206683, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75990] = { ["id"] = 75990, ["name"] = "Star-Crossed Lovers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75990 }, ["description"] = "We found a time disruption long, long ago. Someone helped Illidan charm Tyrande, dooming us all to the Burning Legion! Malfurion is so distraught he can't even sleep. He has no idea how to win her back. We need you to help him out before the timeline is ruined.", ["objectivesText"] = "Help Malfurion gain Tyrande's affection in Val'sharah. Progress: As painful as it can be, heartbreak can be essential for making us who we are. Even if who are isn't always... nice.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206695, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75991] = { ["id"] = 75991, ["name"] = "What Could Have Been", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 75991 }, ["description"] = "A mysterious stranger showed up here a bit ago through one of those time portals. Said there's a threat nearby they need your help with. Some kind of cloaking device. Though you might not like what you see once it's disabled. In fact, you may not particularly like this stranger, for that matter.", ["objectivesText"] = "Help an alternate version of yourself defeat a mutual foe. Progress: I know it must be hard to see yourself like this. At least you're on the same side for this one.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 203769, ["x"] = 0.522, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[75998] = { ["id"] = 75998, ["name"] = "Crispety Crunchety", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 75998 }, ["description"] = "<You've seen this kind of beetle near the stables in Loamm. Maybe the stable master will know more about them?>", ["objectivesText"] = "Bring the Crunchy Beetle to Vanndual in Loamm. Progress: A cherry beetle!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205901 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203294, ["x"] = 0.576, ["y"] = 0.578 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.578 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205901 } },
[76004] = { ["id"] = 76004, ["name"] = "Deep Cuts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14022, ["mapID"] = 2133, ["storyline"] = { 76004 }, ["description"] = "<You find a discarded deepflayer claw . You've seen some niffen wield these as weapons.>", ["objectivesText"] = "Bring 1 Deepflayer Claw to Kilnmaster Crubus in Loamm. Progress: Be careful, those are sharp.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 204985, 205188, 205902 }, ["ends"] = { { ["mapID"] = 2133, ["npcID"] = 203170, ["x"] = 0.57, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 2133 }, ["zone"] = { 14022 } }, ["questType"] = "standard", ["startItems"] = { 205902 } },
