[76072] = { ["id"] = 76072, ["name"] = "Shades of Scarlet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 76072 }, ["description"] = "I need your help, <name>. I thought I had achieved some semblance of peace--although my sins might not be forgiven, I could at least reunite with the spirits of my beloved family. Yet... my wife's spirit is missing. It is as though she never existed. Hallow's End draws the shades that haunt the Monastery out from the shadows. Trapped in the past, they walk the grounds repeating their nightmares. With any luck, one of them might give us answers as to what happened to her.", ["objectivesText"] = "Search for leads amongst the shades at the Scarlet Monastery.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 206158, ["x"] = 0.812, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 205473, ["x"] = 0.824, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.812, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[76073] = { ["id"] = 76073, ["name"] = "No Laughing Matter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 76073 }, ["description"] = "There is a fountain terrace at the end of this path. Before the Scourge wrought havoc across Lordaeron, I used to bring Suzannah there. I remember how certain I felt then--in myself, in the Light... in her, and my children. I wonder when it was that my path started to dim. If there is a shade that can enlighten us, they would be at the fountain.", ["objectivesText"] = "Investigate the Monastery's Fountain.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 205473, ["x"] = 0.824, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 205448, ["x"] = 0.835, ["y"] = 0.307 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[76074] = { ["id"] = 76074, ["name"] = "The Headless Horseman, Returned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 76074 }, ["description"] = "Thomas retreated into the Scarlet Monastery. His ties to this place are strong, even when he is in his corrupted form. Your name is <name>, yes? My husband trusted you to help him, and so I must ask the same. I intend to give chase, but I cannot save him alone. Will you join me?", ["objectivesText"] = "Use the Group Finder to enter the dungeon, \"The Headless Horseman,\" and defeat the Headless Horseman.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 205448, ["x"] = 0.835, ["y"] = 0.307 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.835, ["y"] = 0.307 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[76075] = { ["id"] = 76075, ["name"] = "A Ghostly Message", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 9, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 76075 }, ["description"] = "Excuse me, <name> is it? You've made quite a name for yourself lately, for both the living and the dead. I have in my possession the Tome of Thomas Thomson . For years it has been in my library, a reminder of times we must not forget. Imagine my surprise when the tome flings itself to the floor, falling open to a page with a single name on it. Yours, <name>. If Thomas' spirit is trying to reach you, then I think you should take this tome. Perhaps he awaits at the Scarlet Monastery?", ["objectivesText"] = "Look for Thomas Thomson near the Scarlet Monastery in Tirisfal Glades. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 206596 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 53865, ["x"] = 0.624, ["y"] = 0.665 }, { ["mapID"] = 37, ["npcID"] = 53869, ["x"] = 0.32, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 206158, ["x"] = 0.812, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 18, 37 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[76076] = { ["id"] = 76076, ["name"] = "Small Things", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76076 }, ["description"] = "We had some well-meaning whelps take a few teeny objects from history. Small things can sometimes have a big impact. While the whelps are doing double chores, I need someone to return these rocks to their proper place. I know, right? Rocks? But they have to go back.", ["objectivesText"] = "Return the Icy Rocks to Lordaeron.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
