[76146] = { ["id"] = 76146, ["name"] = "Dawn of the Infinite: Chrono-Lord Deios", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "Chrono-Lord Deios must be behind this all. As the leader of the infinites, he's sure to have led this invasion. I bet Morchie is working for him too. Let's head into the Bronze Temple! We need to stop Deios before he ruins the true timeline.", ["objectivesText"] = "Defeat Chrono-Lord Deios.", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 208415, 208417 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205710, ["x"] = 0.612, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206084, ["x"] = 0.592, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 6, ["flags"] = 0 } } },
[76147] = { ["id"] = 76147, ["name"] = "Rewind and Reconcile", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76140, 76141, 76142, 76143, 76144, 76145, 76146, 76147 }, ["description"] = "<You sense powerful time energy emanating from the relic you retrieved after your fight with Chrono-Lord Deios. It appears to have an engraving of two arrows pointing to the left. You should show it to Nozdormu .>", ["objectivesText"] = "Give the Time Relic to Nozdormu at Temporal Conflux in Thaldraszus. Progress: I sense you have a powerful relic in your possession. Would you allow me to examine it?", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 204196, 206145, 208390 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206084, ["x"] = 0.592, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2025, ["questLines"] = { { ["id"] = 5408, ["name"] = "Dawn of the Infinites", ["orderIndex"] = 7, ["flags"] = 0 } }, ["startItems"] = { 206145 } },
[76155] = { ["id"] = 76155, ["name"] = "A Wolf Among Sheep", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5861, ["mapID"] = 407, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "Thank you for indulging me. But I do not want to appear unappreciative of our new... mentor. Do me a favor--go and fill Madam Shadow 's soulstone by some other means. Far be it for us to test our teacher, but she has yet to earn my trust.", ["objectivesText"] = "Help Oman fill Madam Shadow 's soulstone on Darkmoon Island . Progress: Yes?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 206160 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["db2PoiMapID"] = 974, ["db2PoiUiMapID"] = 407, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 12, ["flags"] = 0 } } },
[76158] = { ["id"] = 76158, ["name"] = "Temporal Gossamer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2112, ["storyline"] = { 76158 }, ["description"] = "The Temporal Gossamer takes shape in the form of delicate, silken strands that appear to strengthen when near an Evoker's Ancient Memories. Assisting the Evoker in finding Temporal Vestigials seems to empower the resolve of these webs, allowing them to bond closely with the Ancient Memories.", ["objectivesText"] = "Strengthen the Temporal Gossemer from group content throughout the Dragon Isles. The Gossamer will only strengthen when in a party and near a holder of Ancient Memories.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 203430, 203683, 204274, 204808, 206163, 206164, 206165, 206166 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 187669, ["x"] = 0.610286, ["y"] = 0.389143 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.610286, ["y"] = 0.389143 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["startItems"] = { 206163 } },
[76159] = { ["id"] = 76159, ["name"] = "Report to the Trading Post", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 76159 }, ["description"] = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", ["objectivesText"] = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 185468, ["x"] = 0.51, ["y"] = 0.718 }, { ["mapID"] = 85, ["npcID"] = 185472, ["x"] = 0.488, ["y"] = 0.764 }, { ["mapID"] = 2339, ["npcID"] = 219244, ["x"] = 0.445, ["y"] = 0.559 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 84, 85, 2339 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 52 },
[76162] = { ["id"] = 76162, ["name"] = "Missing Mojo", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76162 }, ["description"] = "I was practicing me magic and suddenly I found m'self here. Next thing I know, me mojo had run off! It can't have gone far. Would you look for it? I think I need a drink.", ["objectivesText"] = "Recover Vol'jin 's missing Mojo. Progress: Did ya find me mojo?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206171, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205793, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205793, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[76163] = { ["id"] = 76163, ["name"] = "A Lighter Shade of Fel", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 210, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410, 76427, 76430 }, ["description"] = "Dear $p, Greetings. I have taken some time and collected my thoughts after our encounter with Lord Banehollow. I have also sought those who have similarly survived his dark plan, and have gathered them to me in Booty Bay so that we can decide on a way forward. We would ask that you meet us there. Darkest regards, Ph'el Oman", ["objectivesText"] = "Meet with Oman in Booty Bay.", ["rewardGold"] = 127350, ["rewardXP"] = 3085, ["rewardItems"] = { 206681, 207101 }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 205833, ["x"] = 0.42, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 10, ["flags"] = 0 } }, ["startItems"] = { 206681 } },
[76164] = { ["id"] = 76164, ["name"] = "Bovan's Last Hope", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 76164 }, ["description"] = "If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot. We still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work. Go to the Ohn'iri Springs and look for Boku. I'm sure he will help us. Baine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.", ["objectivesText"] = "Find Boku at the Ohn'iri Springs.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[76167] = { ["id"] = 76167, ["name"] = "A Place of Refuge", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 76167 }, ["description"] = "Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. <name>, I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.", ["objectivesText"] = "Meet Baine and Tomul at Toghusuq Village.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[76244] = { ["id"] = 76244, ["name"] = "Prince in Peril", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2025, ["storyline"] = { 76244 }, ["description"] = "I was fighting off a pack of vicious gnolls who were threatening my prince when there was a flash of light. Suddenly, I was in this strange place and the prince was gone! It must have been that dastardly Matriarch Bluepelt . Please, find Prince Wrynn and give those gnolls what for!", ["objectivesText"] = "Defeat time-lost gnolls and recover the missing Llane Wrynn. Progress: Did you find him?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206018, ["x"] = 0.522, ["y"] = 0.815 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206018, ["x"] = 0.522, ["y"] = 0.815 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.815 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[76246] = { ["id"] = 76246, ["name"] = "Manastorm Mystique", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76246 }, ["description"] = "The Manastorms are... unique. While their romance can be explosive, the spark that fanned that flame was quite small. Oddly, Millhouse is having an uncharacteristic crisis of confidence. We need you to help bring them together. May the titans have mercy on us all...", ["objectivesText"] = "Talk to Millhouse Manastorm in Dalaran. Progress: The chaos these two will cause concerns me greatly. However, the timeline must be maintained.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205769, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[76251] = { ["id"] = 76251, ["name"] = "Fowl Beasts", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76251 }, ["description"] = "I believe my time displacement was caused by the horrific creatures to the south. I can hear them even now, with their monstrous noises. No doubt they ripped me from my original time just to taunt me. Slay them for me and for the safety of all good people in this world.", ["objectivesText"] = "Slay 10 Fowl Beasts in Winterpelt Hollow in Azure Span. Progress: Well? What are you waiting for? Think of all the children you could be saving from those monstrous creatures. Not that I saw any, but you never know.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206072, ["x"] = 0.522, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206072, ["x"] = 0.522, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[76257] = { ["id"] = 76257, ["name"] = "Darkmaster's Scourgestone", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 2057, ["mapID"] = 23, ["storyline"] = { 76257 }, ["description"] = "<The scourgestone in your hand feels as real as everything else in this memory. It chills your very bones as it rests in the palm of your hand. While it may be a relic of a past time, the Argent Dawn should nonetheless be made aware of its existence. The ritual conducted upon Eva's journal may have had greater consequences than either of you anticipated.>", ["objectivesText"] = "Find somebody interested in the Darkmaster's Scourgestone .", ["rewardItems"] = { 12844, 206373 }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.536667 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 2057 } }, ["questType"] = "standard", ["startItems"] = { 206373 } },
[76258] = { ["id"] = 76258, ["name"] = "By Time Fire be Purged!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76258 }, ["description"] = "That big ol' slag elemental has taken the heart of me forge! Without it, a timeforge is just, well, a forge. And that's no use to a chronosmith! Even if we had Seashellamayne, I wouldn't be able to repair it. Such power cannot be allowed to remain in the possession of that... that molten moron! The other elementals took off for the towers. I bet half me beard the big one's close by too.", ["objectivesText"] = "Retrieve the Heart of the Timeforge . Progress: Those confounded elementals must have come from the heart of me forge. Was it destabilized, somehow? Either way, it's bad news. Every chronosmith worth their minute knows you don't mix elemental and temporal energies.", ["rewardGold"] = 280900, ["rewardXP"] = 11895, ["rewardItems"] = { 206763, 208482 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208825, ["x"] = 0.522, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206138, ["x"] = 0.522, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76263] = { ["id"] = 76263, ["name"] = "The Dread Citadel - Naxxramas", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 76263 }, ["description"] = "Long ago, magical wards placed upon Naxxramas stymied our attempts to assault Kel'Thuzad's forces. Though I was able to conceal our army past them, I have since learned to dispel them should the need ever arise. I will confess my disbelief of your story. However, if you are so devoted to this investigation, I will enchant your insignia so you may breach these barriers yourself. For a price.", ["objectivesText"] = "Archmage Angela Dosantos in the Eastern Plaguelands wants 5 Arcane Crystals , 6 Large Brilliant Shards , 1 Righteous Orb and 60 gold pieces. You must also be Honored with the Argent Dawn . Progress: Have you brought the necessary reagents?", ["rewardItems"] = { 12363, 12811, 14344 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 16116, ["x"] = 0.741, ["y"] = 0.6945 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 16116, ["x"] = 0.741, ["y"] = 0.6945 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.6945 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[76264] = { ["id"] = 76264, ["name"] = "The Dread Citadel - Naxxramas", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 76264 }, ["description"] = "Long ago, magical wards placed upon Naxxramas stymied our attempts to assault Kel'Thuzad's forces. Though I was able to conceal our army past them, I have since learned to dispel them should the need ever arise. I will confess my disbelief of your story. However, if you are so devoted to this investigation, I will enchant your insignia so you may breach these barriers yourself. For a small fee.", ["objectivesText"] = "Archmage Angela Dosantos in the Eastern Plaguelands wants 2 Arcane Crystals , 3 Large Brilliant Shards , and 30 gold pieces. You must also be Revered with the Argent Dawn . Progress: Have you brought the necessary reagents?", ["rewardItems"] = { 12363, 14344 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 16116, ["x"] = 0.741, ["y"] = 0.6945 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 16116, ["x"] = 0.741, ["y"] = 0.6945 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.6945 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[76265] = { ["id"] = 76265, ["name"] = "The Dread Citadel - Naxxramas", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 76265 }, ["description"] = "Long ago, magical wards placed upon Naxxramas stymied our attempts to assault Kel'Thuzad's forces. Though I was able to conceal our army past them, I have since learned to dispel them should the need ever arise. I will confess my disbelief of your story. However, if you are so devoted to this investigation, I will enchant your insignia so you may breach these barriers yourself.", ["objectivesText"] = "Archmage Angela Dosantos in the Eastern Plaguelands will empower your Argent Dawn Commission at no cost. You must be Exalted with the Argent Dawn .", ["starts"] = { { ["mapID"] = 23, ["npcID"] = 16116, ["x"] = 0.741, ["y"] = 0.6945 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 16116, ["x"] = 0.741, ["y"] = 0.6945 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.6945 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[76266] = { ["id"] = 76266, ["name"] = "A Multitude of Tasks", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76266 }, ["description"] = "Hi <name>! I have a super exciting assignment for today. I need you to place seven loaves of bread around Stormwind, and five jugs of milk in Orgrimmar. You'll finish that up with... < Chromie looks at a note in her hand.> Seven hundred and forty two grains of rice scattered across Pandaria!", ["objectivesText"] = "Perform a series of tasks in the Everywhere Inn in Eon's Fringe. Progress: You're so lucky, always getting to do these fun quests! Meanwhile I'm stuck here, just telling people what to do.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 206447, 206474, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[76268] = { ["id"] = 76268, ["name"] = "Corruptor's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 76268 }, ["objectivesText"] = "Progress: A Corruptor's Scourgestone was the insignia of the Scourge's overlords. Powerful beings that once held a position of authority over the Scourge always possessed one. I formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", ["rewardItems"] = { 12844, 206375, 206576 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.536667 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[76269] = { ["id"] = 76269, ["name"] = "A Mislaid Egg", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76269 }, ["description"] = "Oh dear, this is a tricky one. We need you to relocate an egg to somewhere that Rhonin will be certain to notice it. It may sound odd, but his discovery of that egg sets into motion the events that will free Alexstrasza from the Old Horde--and save the egg, too! We're sending you to Dun Algaz. It's not where any of this should be taking place, but time is like cheese right now. Tasty and full of holes. Oh, and here's some sand. It'll help you be a bit more stealthy.", ["objectivesText"] = "Find the Red Dragon Egg and place it someplace conspicuous. Progress: Did you find a good spot for the egg?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 8499, 206394, 207002 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205424, ["x"] = 0.522, ["y"] = 0.816 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2705 } },
[76270] = { ["id"] = 76270, ["name"] = "Invader's Scourgestones", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 76270 }, ["objectivesText"] = "Progress: An Invader's Scourgestone was the insignia of the Scourge's elite troops. These were sometimes found on the stronger of the troops positioned in Stratholme and Scholomance. I formerly exchanged valor tokens for these. While I doubt you will ever find more, please bring any others back to me immediately so I can see to their destruction.", ["rewardItems"] = { 12844, 206374, 206576 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 11039, ["x"] = 0.756, ["y"] = 0.536667 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.536667 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
