[76350] = { ["id"] = 76350, ["name"] = "The Chronosmith", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76350 }, ["description"] = "Are you here to aid us? As you can see, the time anomaly around Eon's Fringe has dissipated and there is no shortage of work to be done. We've called in for help from one our best chronosmiths, a bronze dragon by the name of Ironormu. The problem, amongst all this chaos, is that he's nowhere to be found. He should have been back from setting up his workshop by now. <Tempo sighs in agitation.> Can you go find him?", ["objectivesText"] = "Seek out Ironormu at the forge in Eon's Fringe.", ["rewardGold"] = 280900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 195773, ["x"] = 0.548, ["y"] = 0.816 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.816 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76351] = { ["id"] = 76351, ["name"] = "Titanic Beasts", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76351 }, ["description"] = "<This small device rolled out of the mouth of a beast you defeated. It appears to be a titan information device, but it's more compact than devices you've seen on Azeroth. Soridormi will want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206564, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206564 } },
[76352] = { ["id"] = 76352, ["name"] = "Chronohammer Time!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76352 }, ["description"] = "If I'm to repair young Finduin's blade here, then we need to crack open this timelock on me forge. And if a hammer can break a lock, then I'm betting a chronohammer can break a timelock. Unfortunately, my hammer's a wee bit out of sync. But we're in the prime sort of mishap to fix that. Nearby rifts are tearing into our timeline just outside the Temporal Conflux and out-of-time uglies are pouring through. Head out of Eon's Fringe, clear the area, and recharge my hammer.", ["objectivesText"] = "Kill time-displaced creatures and destroy rifts in the Passage of Time to resync Ironus's Chronohammer.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76354] = { ["id"] = 76354, ["name"] = "For the Hoard!", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76354 }, ["description"] = "I have a storage vault in the Passage of Time chock-full of chronomatic crates. They contain timelost artifacts from various timelines. Unfortunately, me safeguard protocols on the vault itself were damaged by those blasted time rifts. I did a quick fly-about and saw those infernal looters scattering my crates everywhere! Since you're heading that way, can you grab some of my possessions as you go? Not all of them, of course! Just the important stuff.", ["objectivesText"] = "Find and collect Ironus's artifacts. Progress: I swear by the heat of me forge, if any of those retched looters broke into me crates and took anything, I'm going to... Well, we bronze dragons have all sorts of techniques, don't we?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 198612, 208053 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76355] = { ["id"] = 76355, ["name"] = "If a Hammer Can Break a Lock...", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76355 }, ["description"] = "Now that the hammer is all charged up, all we need is to take one big swing at the time-lock and BOOM! Nothing breaks a temporally-crafted anomaly like a temporally-charged hammer. We'd just need to account for a possible sundering of time and... <Ironus hesitates for a moment as he makes a few calculations under his breath before he looks at you with a not-so-confident smile.> Tell you what? You earned this! You do the honors.", ["objectivesText"] = "Shatter the time-lock with the Chronoforged Hammer.", ["rewardGold"] = 280900, ["rewardXP"] = 7135, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 205679, ["x"] = 0.525, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 208825, ["x"] = 0.522, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
[76356] = { ["id"] = 76356, ["name"] = "Sword Stealing Searers", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76356 }, ["description"] = "Those grubby forgespawns knocked Finduin right over and took Seashellamayne! They must've sensed the temporal energies lingering on the sword. Can't imagine what they'd want with it, but there's no time to wait and see. Everything you've done won't mean much if I don't have Finduin's blade to fix. Could you fetch it for me? After all, the fate of Azmerloth depends on it!", ["objectivesText"] = "Retrieve Finduin Wryngrrlgulgll's blade Seashellamayne. Progress: Like time-moths to the chrono-flame, those wee elementals were drawn to Seashellamayne! I can only hope the damage done to it is minimal.", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 208100 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 208825, ["x"] = 0.522, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206138, ["x"] = 0.522, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
