[76404] = { ["id"] = 76404, ["name"] = "Cogs in a Machine", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76404 }, ["description"] = "<This cog spiraled out of a mechanized creature as you sent it back to its timeway. While its design is similar to Mechagnome technology, it's sleeker and more refined. It bears a small inscription. Soridormi will want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206602, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206602 } },
[76406] = { ["id"] = 76406, ["name"] = "The Sins of the Ashbringer", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76406 }, ["description"] = "<As you near this blade, you can feel necromantic power thrumming from it. Perhaps you should wrap the sword in cloth and avoid touching it directly. Soridormi will want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir.", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206638, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206638 } },
[76410] = { ["id"] = 76410, ["name"] = "A Dark Summons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 75538, 75539, 75540, 75541, 75542, 75543, 75544, 75639, 76155, 76163, 76410 }, ["description"] = "Denizens of Azeroth, Do you thirst for power? Do you wish to change your circumstances, to become... more? More free. More respected. More feared. Do you wish to become a Warlock? If your response to any of the above is \"yes\", then meet with my humble servant Phineas. In temptation, Madam Shadow", ["objectivesText"] = "Talk to Assistant Phineas in the Mage Quarter in Stormwind.", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 207101, 208226 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 204198, ["x"] = 0.490667, ["y"] = 0.769333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.490667, ["y"] = 0.769333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5383, ["name"] = "Some Wicked Things", ["orderIndex"] = 11, ["flags"] = 0 } }, ["startItems"] = { 208226 } },
[76425] = { ["id"] = 76425, ["name"] = "Renowned with the Dream Wardens", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 76425 }, ["description"] = "Champion! A moment of your time. We wanted to recognize all your efforts. Meet me back at Central Encampment. We have a token of our appreciation that we'd like to give you.", ["objectivesText"] = "Speak with Keeper Amrymn at the Central Encampment.", ["rewardItems"] = { 210992 }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208143, ["x"] = 0.502, ["y"] = 0.616 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.616 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2575, ["threshold"] = 7500 } } } },
