[76449] = { ["id"] = 76449, ["name"] = "The Endless Conflict", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14845, ["mapID"] = 2025, ["storyline"] = { 76449 }, ["description"] = "<You notice a book beside the body of a Great Glorious Alliance soldier. Quickly flicking through the pages, you see that it's some type of journal. Parts of it were ruined by a puddle of oil. Soridormi will want to see this.>", ["objectivesText"] = "Bring the Oil-Soaked Log Book to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206749, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14845 } }, ["questType"] = "standard", ["startItems"] = { 206749 } },
