[76456] = { ["id"] = 76456, ["name"] = "Using the Idol", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2025, ["storyline"] = { 76456 }, ["description"] = "Ah, the Idol of Ohn'ahra! Let's use it to find gems. I've hidden three gems nearby in Valdrakken , all outside. The idol will reveal the gems when you're near. Come back when you've tracked them down.", ["objectivesText"] = "Use the Idol of Ohn'ahra to find 3 hidden gems , then speak with Preservationist Kathos . Progress: Have you found the gems?", ["rewardItems"] = { 207730, 208092 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 206864, ["x"] = 0.604, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
