[76533] = { ["id"] = 76533, ["name"] = "Dangerous Documentation", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14846, ["mapID"] = 2025, ["storyline"] = { 76533 }, ["description"] = "<The flickering of a hologram stands out among the surrounding greenery.> A quick investigation of the item reveals this is some sort of catalog left by a Watcher in its timeway. It details observations of the yaungol, ancestors of the tauren. < Soridormi will want to see this.>", ["objectivesText"] = "Return to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206962, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14846 } }, ["questType"] = "standard", ["startItems"] = { 206962 } },
