[76544] = { ["id"] = 76544, ["name"] = "Wasteland Warriors", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76544 }, ["description"] = "<This book has what appears to be a modified Horde symbol on it. You recognize it as the Blood Horde symbol you have seen from timeway incursions. It is odd it is still here, after the incursion has ended. The book has been soaked in blood, though it has long since dried off. Soridormi might be interested in this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206984, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206984 } },
[76545] = { ["id"] = 76545, ["name"] = "Brewfest in Valdrakken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 76545 }, ["description"] = "Have you heard? Brewfest has made its way here! You should speak to Bragdur Battlebrew in the Artisan's Market--he can tell you all about it.", ["objectivesText"] = "Speak to Bragdur Battlebrew .", ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.390667, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[76546] = { ["id"] = 76546, ["name"] = "Mantid Methodology", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76546 }, ["description"] = "<This amber sword was left behind as you knocked one of the Mantid back through a time rift. You take a moment to ensure it's safe, then place it in your pack. Perhaps Soridormi would be interested in it.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 206998, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 206998 } },
[76547] = { ["id"] = 76547, ["name"] = "All That Glitters...", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14844, ["mapID"] = 2025, ["storyline"] = { 76547 }, ["description"] = "<Having recently defeated the Time Anomaly in this timeway, you notice this golden vase glittering. It is extremely worn, be it by time or something else. You can't make out the details of its carvings along the edges. Battered as it is, it still manages to give off a warm light, contrasting the chill here. It looks very out of place. Soridormi may be interested in it.>", ["objectivesText"] = "Return to Soridormi in the Tyrhold Reservoir. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 207003, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 14844 } }, ["questType"] = "standard", ["startItems"] = { 207003 } },
[76548] = { ["id"] = 76548, ["name"] = "A Fishy Gift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 76548 }, ["description"] = "Murglgalgul! Glulmual, rluu glua ffrl wawawamual. Lalala! Mowua ha mwaaay. < Murloc You raises a fish up in both of <his/her:their> hands towards you. It seems very officious. Soridormi may want to see this.>", ["objectivesText"] = "After completing a Time Rift, return to Soridormi in the Tyrhold Reservoir. Progress: Hello again, <name>. What do you have there?", ["rewardGold"] = 28090, ["rewardXP"] = 1190, ["rewardItems"] = { 207008, 208186 }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard", ["startItems"] = { 207008 } },
