[77208] = { ["id"] = 77208, ["name"] = "Barreling Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77208 }, ["description"] = "If it's ale ye be looking for, we've plenty to sample! Or at least we would if the Valdrakken folk would hurry up and bring the rest of the barrels down here. We've shipped our Brewfest brews here so they can celebrate--and wouldn't ye know it, they've already started their own traditions! Rolling barrels through the city? That's no way to treat a good brew! Mind lending a hand to bring those barrels down here? And try not to break 'em!", ["objectivesText"] = "Deliver barrels to the Artisan's Market in Valdrakken. Progress: Careful with the barrels! Ye shouldn't jostle a good ale.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207496, ["x"] = 0.298, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[77236] = { ["id"] = 77236, ["name"] = "When Time Needs Mending", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13647, ["mapID"] = 2025, ["storyline"] = { 77236 }, ["description"] = "We need to close rifts. We need to fix timeways. Honestly, we need all the help we can get. There's always more work to do. Are you ready for the next challenge?", ["objectivesText"] = "Close a Time Rift by defeating a Fractured Causality. Progress: Come now, these rifts aren't going to close themselves.", ["rewardItems"] = { 204076, 207002, 207030, 207582, 207583, 207584, 208090, 208945, 208951, 208952, 215363, 224298 }, ["starts"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 204450, ["x"] = 0.51, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 2025, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 2025 }, ["zone"] = { 13647 } }, ["questType"] = "standard" },
