[77697] = { ["id"] = 77697, ["name"] = "The Right Food...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77677, 77697, 77711, 77762, 78398 }, ["description"] = "<The plant is now a promising sapling and has thrived with the attention you've given. Peering closely at the plant's leaves, you see its exterior brimming with dew. Perhaps the right food will help the plant even further.>", ["objectivesText"] = "Bring some fertilizer for the plant. Progress: <The plant is hydrated, but remains severely underfed.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 4537, 208644, 208646, 208647, 208757, 209416, 210774 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 209458, ["x"] = 0.486, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209458, ["x"] = 0.486, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5477, ["name"] = "A Mix of Hope, Care, and Patience", ["orderIndex"] = 2, ["flags"] = 0 } } },
[77711] = { ["id"] = 77711, ["name"] = "And a Pinch of Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77677, 77697, 77711, 77762, 78398 }, ["description"] = "The diligence you've shown here is astounding, <name>. I never suspected that someone who couldn't even find their own bucket, could do something like this. I think the sapling is almost there, and with my help we can bring it the rest of the way. Take this totem and place it near some of the weakened, flame-corrupted Roottenders found in the Singing Fen. This should siphon the unstable magical energies out of their bodies and transform it into something we can use.", ["objectivesText"] = "Defeat Roottenders while they are under the effects of the Druidic Totem . Progress: Is the totem charged?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137663, 208705 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208337, ["x"] = 0.496, ["y"] = 0.628 }, { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5477, ["name"] = "A Mix of Hope, Care, and Patience", ["orderIndex"] = 3, ["flags"] = 0 } } },
