[77779] = { ["id"] = 77779, ["name"] = "The Tale of Sir Thomas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 9, ["zoneID"] = 6109, ["mapID"] = 18, ["storyline"] = { 77779 }, ["description"] = "Suzannah... I never thought I would find her. Now we can return to our children, and rest at last. All thanks to you, <name>. Do you still have my tome? My story has reached its end, and I would see it penned by my own hand. <Thomas glides his finger across a blank page, spectral ink marking his words.> Please return this to the Orphan Matron. And... please apologize on my behalf for frightening her, would you?", ["objectivesText"] = "Return to the Orphan Matron. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 208769 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 53865, ["x"] = 0.624, ["y"] = 0.665 }, { ["mapID"] = 37, ["npcID"] = 53869, ["x"] = 0.32, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 18, 37 }, ["zone"] = { 6109 } }, ["questType"] = "standard" },
