[77813] = { ["id"] = 77813, ["name"] = "Lightning Strikes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77813, 77815 }, ["description"] = "<Flaps does a spin and deposits a drool-soaked note into your hand.> Ah, <name>. I am told you have acquired a fine new mount. A gryphon that soars upon the very storm itself! I would very much like to see how this wondrous creature flies. I will await you at Skytop Observatory.", ["objectivesText"] = "Meet Lord Andestrasz at the Skytop Observatory.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 39347, 39400, 39437, 39457, 209417 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 197478, ["x"] = 0.455, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 193359, ["x"] = 0.752, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 2022, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2022, ["questLines"] = { { ["id"] = 5480, ["name"] = "11.0 Preorder", ["orderIndex"] = 0, ["flags"] = 0 } } },
[77822] = { ["id"] = 77822, ["name"] = "A Titanic Mold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77822 }, ["description"] = "<The Titan Key Mold was at the location referenced in the story. Weaponsmith Koref will be so excited to see the mold!>", ["objectivesText"] = "Return the Titan Key Mold to Weaponsmith Koref in Valdrakken . Progress: By the forge, did you actually do it? Did you find the Titan Key mold ?", ["rewardItems"] = { 208092, 208486, 208827 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 195769, ["x"] = 0.365, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77829] = { ["id"] = 77829, ["name"] = "Reforging a Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77829 }, ["description"] = "There you are! Weaponsmith Koref was just looking for you. Left me with a note asking you to meet him in the Obsidian Conclave. Sounds like you're helping him reforge an ancient titan key? Let me know how it goes! That's headline news if I ever heard it.", ["objectivesText"] = "Seek out Weaponsmith Koref in the Obsidian Enclave.", ["rewardItems"] = { 207730, 208829, 208831, 208835, 208836 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 195769, ["x"] = 0.365, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77831] = { ["id"] = 77831, ["name"] = "A Key To Reforg(ing)", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13644, ["mapID"] = 2022, ["storyline"] = { 77831 }, ["description"] = "You have the final materials! Perfect. I prepared the forge and the mold. I just need you to add the ingredients when I say. Oh, and be ready to use that Torch of Pyrreth. Seems the relic is crucial to the forging process. I'll tell you when!", ["objectivesText"] = "Assist Weaponsmith Koref in reforging the Titan Key. Progress: The Titan Key. By the forge... Let me have a look.", ["rewardItems"] = { 191251, 191264, 193201, 207730, 208092, 208829, 208830, 208831, 208835, 208836 }, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 210837, ["x"] = 0.245, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 210837, ["x"] = 0.245, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 2022 }, ["zone"] = { 13644 } }, ["questType"] = "standard" },
[77832] = { ["id"] = 77832, ["name"] = "Shadows upon shadows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 77832 }, ["description"] = "I need to save him.", ["objectivesText"] = "Slay the Shadows.", ["rewardGold"] = 8725, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[77833] = { ["id"] = 77833, ["name"] = "Handling It: Concentrated Sophic Vellum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "I know of a sage who can help temper Fyr'alath. Shalasar Glimmerdusk is an expert in intellectual matters, often pondering theories for controlling volatile magics. Few understand sophic matters as well as she does. Seek her guidance in managing shadowflame. I suspect her solution may include a sprinkle of Chromatic Dust!", ["objectivesText"] = "Seek out Shalasar Glimmerdusk in the Ohn'ahran Plains.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 208840 } },
[77835] = { ["id"] = 77835, ["name"] = "Handling It: Rune of Shadowbinding", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "Lydiara Whisperfeather is an academic who recognizes the rigidity of the rules that govern our world. She also likes bending them. If there is anyone who can assist in binding Fyr'alath's power, it's her.", ["objectivesText"] = "Seek out Lydiara Whisperfeather in the Azure Span.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208781 }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 208839 } },
[77838] = { ["id"] = 77838, ["name"] = "Tattered Dreamleaf", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2023, ["storyline"] = { 77838 }, ["description"] = "The properties of Dreamleaf are foreign to you. Completing events during the Superbloom will give you the knowledge necessary to help your ally.", ["objectivesText"] = "Complete events during the Superbloom.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 206448, 207729, 208576, 208587, 208588, 208593, 208781, 208846, 210199 }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["startItems"] = { 211927 } },
