[77886] = { ["id"] = 77886, ["name"] = "Handling It: Shadowed Dreamleaf", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "When Fyr'alath's power is at its limit, you will need a grip that can cool itself. It is like standing your ground when a beast charges you: as the battle heats up, you need a way to stay focused. Various leathers throughout the Dragon Isles have that cooling property, but I know of something better. Foliage that is routinely exposed to shadowflame would be the best choice for binding the components together. Let us gather what you need.", ["objectivesText"] = "Collect Shadowed Dreamleaf from completing objectives in the Superbloom. Progress: Did you find what we need?", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208593, 210009 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 208887 } },
[77889] = { ["id"] = 77889, ["name"] = "A Fiery Proposal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77889 }, ["description"] = "Ah hello! I have been working with some inscribers recently. We've been making a new type of ink. It's like fire ink, but even fierier! We need fiery essence from fire elementals, and fire elementals are currently attacking the dream. I believe this is what is called a \"win win\" scenario. Please drop their essence off at my associate in Amirdrassil.", ["objectivesText"] = "Collect 10 Fiery Essence from fire elementals in the Emerald Dream . Progress: New knowledge can come from the strangest sources!", ["rewardItems"] = { 198607, 208886 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208337, ["x"] = 0.496, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[77891] = { ["id"] = 77891, ["name"] = "Fixing The Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77891 }, ["description"] = "Engineering is an exact science! When something explodes, engineers plan it that way. Dreams are not exact, especially emerald ones! Someday, someone will want engineers to fix the Dream, and we won't know how to do it. We need a lot more information to understand what we're dealing with! Go to the Dream and place research beacons at my designated points. They will gather the information needed for any future repairs. Use this handy teleport device if you want to find the locations quickly.", ["objectivesText"] = "Activate 8 Research Beacons Progress: I wonder if we'll ever truly understand the dream.", ["rewardItems"] = { 198611, 209017 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[77892] = { ["id"] = 77892, ["name"] = "Pearls Of Great Value", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77892 }, ["description"] = "When Amirdrassil's roots spread to the water, many rare creatures arose from the ocean's depths and now flourish around the dreams. One such rare creature is the Sandsparkle Clam, which can contain magical pearls! See if you can locate these clams and find some pearls within.", ["objectivesText"] = "Collect 10 Sandsparkle Pearls Progress: Have you found any pearls?", ["rewardItems"] = { 198612, 208927 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[77897] = { ["id"] = 77897, ["name"] = "A Special Book", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77897 }, ["rewardItems"] = { 206696, 207730, 208092, 208888, 208889 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77908] = { ["id"] = 77908, ["name"] = "A Legacy of Secrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77908 }, ["description"] = "<Return the book to Bobby Carlisle in Valdrakken to assist with deciphering the tablet text!>", ["objectivesText"] = "Return the book, Tyr's Legacy , to Bobby Carlisle in Valdrakken . Progress: Was my source any good? Were you able to find the book?", ["rewardGold"] = 280900, ["rewardXP"] = 9515, ["rewardItems"] = { 201302, 201303, 201304, 201305, 201306, 201307, 201308, 201309, 208889 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77910] = { ["id"] = 77910, ["name"] = "Enchanted Shrubbery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2133, ["storyline"] = { 77910 }, ["description"] = "Certain plants from the Emerald Dream could contain ingredients that would be helpful in our work here, but we need a lot of them, and I'm not hiring some herbalist to collect them. I've enchanted a water pot to help solve the problem. Travel to the Emerald Dream and use it on the plants I require. The plants should then deliver themselves.", ["objectivesText"] = "Use the Watering Pot on 12 Enchanted Shrubs . Progress: Have you found the plants?", ["rewardItems"] = { 198610, 208947 }, ["starts"] = { { ["mapID"] = 2133, ["npcID"] = 203172, ["x"] = 0.56, ["y"] = 0.568 }, { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["coords"] = { ["mapID"] = 2133, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 2112, 2133 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 40 },
[77912] = { ["id"] = 77912, ["name"] = "Unmodern Jewelry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77912 }, ["description"] = "Some of the local Jewelcrafters are looking to study examples of the Zaqali tribes adornments. Given they are currently attacking my home, we may take advantage of the situation. I thought you might take them violently, yes? Argonax waits once you have collected them.", ["objectivesText"] = "Collect 10 Zaqali Adornments . Progress: New knowledge can come from the strangest sources.", ["rewardItems"] = { 198612, 208928 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208340, ["x"] = 0.572, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 43 },
[77914] = { ["id"] = 77914, ["name"] = "Burning Runes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77914 }, ["description"] = "I am told that the Druids of the Flame help to stabilize their portals into the dream through the use of a unique sort of inscription! While their ends are abhorrent, I cannot help but be curious as to their means. If we can better understand their methods, then perhaps we can better equip our allies to stem the tide of their arrival. If you get your hands on any burning runes , could you bring them to my colleague for further study?", ["objectivesText"] = "Collect 10 Burning Runes from druids of the flame in the Emerald Dream . Progress: Take care, friend. I doubt the Druids of the Flame will part with their runework willingly.", ["rewardItems"] = { 198607, 208946 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208409, ["x"] = 0.36, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 42 },
[77928] = { ["id"] = 77928, ["name"] = "They Are Always Listening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77928 }, ["description"] = "Remember my contact, Fangli Hoot ? Seems she has another theory about the one behind these artifact thefts. I'm a bit weary after the last tip went nowhere, but we can't turn down a lead. Journalistic integrity demands we at least hear her out. You'll find her by the barber shop.", ["objectivesText"] = "Speak with Fangli Hoot near the Valdrakken barber shop.", ["rewardItems"] = { 206696, 207730, 208929 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207696, ["x"] = 0.476, ["y"] = 0.470667 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.470667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77932] = { ["id"] = 77932, ["name"] = "Warmth of Life", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77932 }, ["description"] = "The Druids of the Flame practice virulent magics that warp and burn all they touch. They do, however, have excellent taste in alchemical reagents. If you should happen across any of their metamorphic ash, could you gather it up for me? One of my contacts within the Dream has been asking after the stuff.", ["objectivesText"] = "Collect eight samples of Metamorphic Ash from Druids of the Flame in the Smoldering Copse. Progress: Ah, there you are! Have you managed to get your hands on any of that ash, yet? Its alchemical properties are truly wondrous.", ["rewardItems"] = { 198608, 208938 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208406, ["x"] = 0.692, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[77933] = { ["id"] = 77933, ["name"] = "Bubbling Discoveries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77933 }, ["description"] = "The rise of Amirdrassil has unlocked various geological wonders in the dream. Among these are a variety of magical springs, bubbling water from deep within Azeroth. Travel the dream and gather samples from these springs.", ["objectivesText"] = "Collect 8 samples from Bubbling Springs . Progress: Have you gathered the samples?", ["rewardItems"] = { 198608 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 38 },
[77934] = { ["id"] = 77934, ["name"] = "A Complete Inventory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77934 }, ["description"] = "<Compile your notes on the caches for Fangli Hoot in Valdrakken .>", ["objectivesText"] = "Report your findings to Fangli Hoot near the barber shop in Valdrakken . Provided item:", ["rewardItems"] = { 208936 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 207697, ["x"] = 0.2656, ["y"] = 0.5432 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.2656, ["y"] = 0.5432 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[77935] = { ["id"] = 77935, ["name"] = "A-Sword-ed Needs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77935 }, ["description"] = "Swords! Sorry, I saw you and I did not want to forget. Yes. We need swords. In the Dream. You can provide, yes? Please deliver them to Cylania .", ["objectivesText"] = "Deliver 3 Draconium Swords to Cylania in the Emerald Dream Progress: Can I help you?", ["rewardItems"] = { 190484, 198606 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207755, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[77936] = { ["id"] = 77936, ["name"] = "A Warm Harvest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2112, ["storyline"] = { 77936 }, ["description"] = "Everyone knows heat plays a critical role in blacksmithing. I hear the Emerald Dream is still heavily under attack by allies of the flame. There must be a way to harvest fuel from those eternally fiery creatures. If you do secure anything, I'm sure one of the local blacksmiths in the Dream will be very interested.", ["objectivesText"] = "Collect 10 Essence of Endless Flame in the Emerald Dream . Progress: Hmm. Yes?", ["rewardItems"] = { 198606, 209049 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208340, ["x"] = 0.572, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 14529 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 33 },
[77938] = { ["id"] = 77938, ["name"] = "An Unlikely Engineer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2112, ["storyline"] = { 77938 }, ["description"] = "I hear there is a legendary engineer in the Dream who crafts the most beautiful dream catchers. This engineer, Nyla Bushtail , enjoys acorn-flavored morels and relies on them to fuel her work. Acorn-flavored mushrooms... certainly strange, but perhaps not unheard of. There's a coastal area close to the Eye of Ysera where these morels grow abundantly. Do tread carefully around any wildlife in the area. If these morels are as tasty as I hear, they will be guarded greedily.", ["objectivesText"] = "Collect 8 Whiteburr Morels for Nyla Bushtail in the Emerald Dream .", ["rewardItems"] = { 198611 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 210636, ["x"] = 0.525, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 14529 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 35 },
[77945] = { ["id"] = 77945, ["name"] = "Boots on the Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77945 }, ["description"] = "Just who I wanted to see. I have a requisition script for items of leather from some of the denizens of the Dream. Shoes, of course. Bipeds tend to go through them like a bird through the forest, yes? Once you have acquired them, please take them to Cylania .", ["objectivesText"] = "Deliver 3 Pioneer's Leather Boots to Cylania in the Emerald Dream . Progress: Can I help you?", ["rewardItems"] = { 193386, 198613 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207755, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[77946] = { ["id"] = 77946, ["name"] = "Fibrous Thread", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77946 }, ["description"] = "Fine thread may conjure images of tailory, but it can serve a vital role in leatherwork as well. Some of the Dream's hardier flora can be processed into a thread strong enough to secure even the thickest of hides and scales. If you happen upon any dense fiber during your travels, you would be well-served by bringing it to my colleague in the Dream.", ["objectivesText"] = "Bring 1 Emerald Fiber from Enchanted Thickets in the Emerald Dream . Progress: You needn't worry about the plants themselves. They are nigh impossible to harm, and so long as they are treated respectfully, they will be more than happy to share their bounty with you.", ["rewardItems"] = { 198613, 208950 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 208404, ["x"] = 0.544, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 44 },
[77947] = { ["id"] = 77947, ["name"] = "Primalist Fashion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77947 }, ["description"] = "Ah, <name>, there you are! The robes of the primalists make for interesting study for the local tailors. If you could retrieve some from the primalists assaulting the dream, I would be pleased, yes? No rips or tears please. Blood stains optional. They can be washed out.", ["objectivesText"] = "Collect 10 Intact Primalist Garb from the Emerald Dream . Progress: Can I help you?", ["rewardItems"] = { 198609, 208956 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 207755, ["x"] = 0.498, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112, 2200 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
[77949] = { ["id"] = 77949, ["name"] = "Fashion Feathers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 77949 }, ["description"] = "Much of the Dream's wildlife is feathered or furred. Their shed, whether it be down fur or feathers, is reputed to be extremely durable, soft, and fashionable. The great somnowls' feathers are particularly desirable. They don't shed often, and feathers are quickly retrieved by local wildlife for nest building. I've heard that your best chance is scouring the Meandering Rootlands in the Dream.", ["objectivesText"] = "Collect 10 Shed Great Feathers in the Emerald Dream . Progress: Have you found any feathers? They're easy to identify. As large as two hands lengthwise, often snowy in color, and buttery soft.", ["rewardItems"] = { 198609, 209021 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 210162, ["x"] = 0.367, ["y"] = 0.629 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.367, ["y"] = 0.629 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "profession", ["db2DetailThemeID"] = 37 },
