[78153] = { ["id"] = 78153, ["name"] = "Handling It: Prototype Rune", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "Ah, I see! We're in uncharted territory here, but I've got a plan. You'll need some Cosmic Ink, Runed Writhebark, and Shadowflame Essence. Sharing this recipe with a friendly scribe should allow them to complete a Crafting Order for you. Let me update my notes with a recipe for the Rune of Shadowbinding.", ["objectivesText"] = "Craft or obtain Lydiara's Binding Rune . Progress: Is it ready? Shall we proceed?", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 194754, 194862, 204464, 209349, 209998 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78154] = { ["id"] = 78154, ["name"] = "To the Test: Rune of Shadowbinding", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 77835, 78003, 78153, 78154 }, ["description"] = "We need to finalize the binding. We can attune the components properly by testing them in combat against Fyrakk's most powerful lieutenants. Then we can bind the attuned materials to Fyr'alath. If you can defeat Gnarlroot, Igira the Cruel, and Volcoross while this rune is bound to them, you'll be ready to fully attune the Rune of Shadowbinding.", ["objectivesText"] = "Defeat Gnarlroot, Igira the Cruel, and Volocross in Amirdrassil, the Dream's Hope. Progress: A hero never backs down from a challenge. You've got this.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 209999, 211397 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["ends"] = { { ["mapID"] = 2024, ["npcID"] = 194840, ["x"] = 0.402, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.644 }, ["mapCandidates"] = { ["npc"] = { 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2024, ["questLines"] = { { ["id"] = 5485, ["name"] = "Rune of Shadowbinding", ["orderIndex"] = 3, ["flags"] = 0 } } },
[78155] = { ["id"] = 78155, ["name"] = "Handling It: Radiant Fleck of Ash", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "I've heard that in the Emerald Dream, a coarse ash with strong properties of shadowflame tends to cling to powerful pieces of equipment. The only way to harvest that powerful dust is by disassembling the equipment. Here, use this rod I've enchanted. It should allow you to siphon off the dust you need.", ["objectivesText"] = "Collect Radiant Flecks of Ash from powerful pieces of gear throughout the Emerald Dream. Progress: Don't give up! This process doesn't just help with crafting. It builds character! Remember that!", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 208581, 210001, 210002 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78156] = { ["id"] = 78156, ["name"] = "Handling It: Radiant Vellum", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77833, 78002, 78155, 78156 }, ["description"] = "We can refine my creation by embedding the enchantment with Order magic. Here are my notes on Concentrated Sophic Vellum. Sharing this with another friendly enchanter should give them enough info to complete a Crafting Order for you.", ["objectivesText"] = "Craft or obtain Shalasar's Sophic Vellum . Progress: I've seen students become... disenchanted... with this type of task, but I know you're made of sterner stuff. Sorry. I've been in isolation for a long time, and I don't get to use that \"joke\" very often.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 109599, 158380, 208846, 210003, 210011 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194837, ["x"] = 0.624, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5484, ["name"] = "Concentrated Sophic Vellum", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78159] = { ["id"] = 78159, ["name"] = "Handling It: Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "To craft something workable, we'll need a substantial amount of Zaralek Glowspores and some leather. Here are my notes on the Symbiotic Glowspore Grip. Sharing this with a friendly leatherworker should give them enough info to complete a Crafting Order for you.", ["objectivesText"] = "Craft or obtain Erden 's Glowspore Grip. Progress: Tracking this down is a lot of work, but the quarry is worth the hunt.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 209351, 210010 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 2, ["flags"] = 0 } } },
[78160] = { ["id"] = 78160, ["name"] = "To the Test: Symbiotic Glowspore Grip", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13645, ["mapID"] = 2023, ["storyline"] = { 77791, 77886, 78159, 78160, 78655 }, ["description"] = "You will have to trust me. We need to activate the reagents embedded in the grip. Wrapping the grip around Fyr'alath's haft should work, as long as you can survive the onslaught that follows. You're going to need to make adjustments as you go, and you won't get it the first time. The spores need to adapt to the axe.", ["objectivesText"] = "Empower the grip while surviving its union with Fyr'alath. Progress: Keep at it. All this hard work is going to pay off.", ["rewardGold"] = 140450, ["rewardXP"] = 4760, ["rewardItems"] = { 205025, 207174, 207528, 210012, 210207, 211396 }, ["starts"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 2023, ["npcID"] = 194842, ["x"] = 0.824, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 2023, ["source"] = "quest_giver", ["x"] = 0.824, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 2023 }, ["zone"] = { 13645 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5483, ["name"] = "Symbiotic Glowspore Grip", ["orderIndex"] = 3, ["flags"] = 0 } } },
