[78328] = { ["id"] = 78328, ["name"] = "Take a Look Around", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 78328 }, ["series"] = { 78329, 78981 }, ["description"] = "The Gala of Gifts is here to showcase the many wonderful artisans carefully crafting gifts just for you and your loved ones. You should see what they have to offer, and talk to the other attendees. Who knows, you might just find the perfect gift for someone you care about!", ["objectivesText"] = "Meet the vendors and visitors at the Gala of Gifts. Progress: Have you seen all of the wares available?", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211802, ["x"] = 0.322, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211802, ["x"] = 0.322, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78329] = { ["id"] = 78329, ["name"] = "Love is in the Air", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 78329 }, ["series"] = { 78328, 78981 }, ["description"] = "Smell these roses! My partner got them for me at the Gala of Gifts. Interested in seeing things yourself? Head to the gates of Stormwind. There are gifts, and food, and you should taste the chocolate, it's delicious!", ["objectivesText"] = "Visit the Gala of Gifts at the gates of Stormwind.", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 18927, ["x"] = 0.628143, ["y"] = 0.557571 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 87, ["npcID"] = 215197, ["x"] = 0.326571, ["y"] = 0.666 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211802, ["x"] = 0.322, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.628143, ["y"] = 0.557571 }, ["mapCandidates"] = { ["npc"] = { 10, 37, 84, 87, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78332] = { ["id"] = 78332, ["name"] = "I Smell Trouble", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 37, ["storyline"] = { 78332 }, ["description"] = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it? Well, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away! Are you in? I could use a good partner to solve this.", ["objectivesText"] = "Use O.D.I.E.'s Remote Control to find clues around Stormwind. Progress: Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.", ["rewardGold"] = 312800, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 210332, 210413, 210416, 210417, 210658 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 38066, ["x"] = 0.322, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
