[78337] = { ["id"] = 78337, ["name"] = "An Unwelcome Gift", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1519, ["storyline"] = { 78337 }, ["description"] = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent! But let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", ["objectivesText"] = "Kill 8 Crown Chemical Co. members around Stormwind. Progress: Follow your nose, pal! Anyone who stinks could be a suspect.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 211208 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
