[78369] = { ["id"] = 78369, ["name"] = "Crushing the Crown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 130, ["mapID"] = 21, ["storyline"] = { 78369 }, ["series"] = { 78379, 78729 }, ["description"] = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver. <Snagglebolt points to the unmarked box.> Bombs. I got bombs. Playtime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", ["objectivesText"] = "Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members. Progress: We need to put a stop to this before the Crown pulls off their smelly sabotage.", ["rewardGold"] = 1024800, ["rewardXP"] = 300, ["rewardItems"] = { 49927, 210431 }, ["starts"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 21, ["npcID"] = 38066, ["x"] = 0.458, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 21, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 21 }, ["zone"] = { 130 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
