[78398] = { ["id"] = 78398, ["name"] = "A Dash of Minerals...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 14529, ["mapID"] = 2200, ["storyline"] = { 77677, 77697, 77711, 77762, 78398 }, ["description"] = "I think we have a chance with this one, <name>. But we'll need to begin revitalizing the soil if we want to see this plant flourish. Head to the Eye of Ysera and harvest fish bones from the Fathomless Lurkers in the depths of the water. They're rich in minerals and degrade easily. It won't replenish the soil on its own, but it's a great start.", ["objectivesText"] = "Collect Fish Bones from Fathomless Lurkers. Progress: Did you have a chance to pick up what I asked for? This plant won't thrive without it.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210457, 210774 }, ["starts"] = { { ["mapID"] = 2200, ["npcID"] = 208337, ["x"] = 0.496, ["y"] = 0.628 }, { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 2200, ["npcID"] = 209571, ["x"] = 0.486, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 2200, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 2200 }, ["zone"] = { 14529 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2548, ["db2PoiUiMapID"] = 2200, ["questLines"] = { { ["id"] = 5477, ["name"] = "A Mix of Hope, Care, and Patience", ["orderIndex"] = 1, ["flags"] = 0 } } },
[78421] = { ["id"] = 78421, ["name"] = "The Power of Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14643, ["storyline"] = { 78421 }, ["description"] = "It seems that the fabric of the Emerald Dream itself is rejecting the invaders, leaving behind shadows of their dreams in the form of these Essences. So close to Amirdrassil, even your own actions are leaving behind ephemeral echoes of power. With enough time, perhaps we can use these echoes to awaken their strength and turn it against Fyrakk himself. Defeat the invaders wherever you find them and return to me when you have gathered enough of the Dream's power.", ["objectivesText"] = "Gather Echoed Ephemera and the Dreams of the Invaders of Amirdrassil. Progress: The Dream has many layers, some quite fragile. I worry that even the defenders' presence will change the unchanging land.", ["rewardGold"] = 929400, ["rewardItems"] = { 210470, 210472, 210473, 210474, 210475, 210494 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14643 } }, ["questType"] = "raid" },
[78429] = { ["id"] = 78429, ["name"] = "The Power of Dreams, Awoken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14643, ["storyline"] = { 78429 }, ["description"] = "Are you ready, <name>? I will fuse the essences of their fiery dreams together for you. Focus the Echoed Ephemera you have collected to awaken the latent power within. Show Fyrakk that even he should fear the power of the Dream!", ["objectivesText"] = "Awaken the power within the Fused Essence .", ["rewardGold"] = 4647000, ["rewardItems"] = { 210494, 210498 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14643 } }, ["questType"] = "raid" },
