[78980] = { ["id"] = 78980, ["name"] = "Take a Look Around", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78980 }, ["description"] = "Here at the Gala of Gifts, we have many wonderful artisans crafting gifts just for you and your loved ones. But don't take my word for it--there are plenty of attendees enjoying the festivities as well! Go, speak to the visitors, and see what the artisans have to offer. Maybe you will find the perfect gift!", ["objectivesText"] = "Meet the vendors and visitors at the Gala of Gifts. Progress: Are you having a good time?", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214477, ["x"] = 0.418, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214477, ["x"] = 0.418, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78981] = { ["id"] = 78981, ["name"] = "Love is in the Air", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78981 }, ["series"] = { 78328, 78329 }, ["description"] = "Smell these roses! My partner got them for me at the Gala of Gifts. Interested in seeing things yourself? Head to Durotar. There are gifts, and food, and you should taste the chocolate, it's delicious!", ["objectivesText"] = "Visit the Gala of Gifts in Durotar, near Rocktusk Farm.", ["rewardGold"] = 16980, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 18, ["npcID"] = 215196, ["x"] = 0.614, ["y"] = 0.668 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214477, ["x"] = 0.418, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.545667, ["y"] = 0.709667 }, ["mapCandidates"] = { ["npc"] = { 1, 18, 85, 2339 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78982] = { ["id"] = 78982, ["name"] = "I Smell Trouble", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78982 }, ["description"] = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it? Well, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away! Are you in? I could use a good partner to solve this.", ["objectivesText"] = "Use O.D.I.E.'s Remote Control to find clues around Orgrimmar. Progress: Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 210413, 210416, 210417, 211778 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78983] = { ["id"] = 78983, ["name"] = "An Unwelcome Gift", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1519, ["storyline"] = { 78983 }, ["description"] = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent! But let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", ["objectivesText"] = "Kill 8 Crown Chemical Co. members around Orgrimmar. Progress: Follow your nose, pal! Anyone who stinks could be a suspect.", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 211781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78984] = { ["id"] = 78984, ["name"] = "Crushing the Crown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78984 }, ["series"] = { 78978, 78985 }, ["description"] = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver. <Snagglebolt points to the unmarked box.> Bombs. I got bombs. Playtime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", ["objectivesText"] = "Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members. Progress: We need to put a stop to this before the Crown pulls off their smelly sabotage.", ["rewardGold"] = 1024800, ["rewardXP"] = 300, ["rewardItems"] = { 49927, 210431 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78985] = { ["id"] = 78985, ["name"] = "The Stench of Revenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 78985 }, ["series"] = { 78978, 78984 }, ["description"] = "We're never gonna see an end to this unless we take on the boss himself. Look, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Orgrimmar if we let him finish his research. You go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", ["objectivesText"] = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel . Progress: You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", ["rewardGold"] = 1123600, ["rewardXP"] = 400, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 3027 } },
[78986] = { ["id"] = 78986, ["name"] = "Getaway to Scenic Grizzly Hills!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78986 }, ["description"] = "Good morrow! Today's special portal is a magical getaway to the majestic forests of Northrend! Although perhaps I could beg you for a favor. You seem the adventurous type. I could use your help in delivering some flowers from Grizzly hills to a beautiful woman named Laverne. I would do it myself but... Well, you see, she is rather intimidating in her beauty.", ["objectivesText"] = "Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Laverne. Progress: The mage conjuring portals? <Laverne giggles.> Let me see.", ["rewardGold"] = 335000, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210719 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214496, ["x"] = 0.406, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78987] = { ["id"] = 78987, ["name"] = "Getaway to Scenic Nagrand!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78987 }, ["description"] = "Good morrow! Today's special portal is a magical getaway to the great plains of Nagrand! Would you, perchance, be interested in a proposition? I will lend you my camera if you could deliver any photographs you take to my dear friend Karn. He has been adrift in Nagrand as of late, lost in his own thoughts. As stubborn as he is, I'm sure he will appreciate the company. I would do it myself, but I must maintain the portals here.", ["objectivesText"] = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Karn. Progress: How is Karn? When last I saw him, he seemed drowned in regrets and loneliness.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210743 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78988] = { ["id"] = 78988, ["name"] = "Getaway to Scenic Feralas!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78988 }, ["description"] = "Good morrow! Today's special portal is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited! Unfortunately, some of our festival attendees who took this portal earlier left their gifts here at the gala. Could you perchance help me return them? I will meet you at the beach and together we shall be able to determine which gifts belong to whom.", ["objectivesText"] = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients. Progress: There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", ["rewardGold"] = 312800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 211922, 211923 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214497, ["x"] = 0.414, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78989] = { ["id"] = 78989, ["name"] = "The Gift of Self-Care", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78989 }, ["description"] = "The eyes of a tired adventurer. A <class> that does many great deeds for many people. When was the last time you did a kind gesture for yourself? Perhaps now is the time. Look into your heart. What do YOU desire?", ["objectivesText"] = "Speak with Ning to discover your heart's desire. Progress: Love is a blessing, especially if it comes from within.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78990] = { ["id"] = 78990, ["name"] = "The Gift of Relief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78990 }, ["description"] = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. I saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress. Perhaps he has insight to teach you.", ["objectivesText"] = "Speak to Tokag Bonebreaker at the Gala of Gifts, then relieve your stress in Orgrimmar. Progress: I've seen men die of stress, you don't want to bottle it up every day.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214602, ["x"] = 0.412, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78991] = { ["id"] = 78991, ["name"] = "The Gift of Relaxation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78991 }, ["description"] = "Love is a gift, yes. But it is also a gift that you can give yourself. Sometimes, the best way to love yourself is simply to relax. I met a troll across the Southfury River who seems particularly wise in this regard. Perhaps you could ask her for insights in the art of relaxation.", ["objectivesText"] = "Speak with Jaz the Reborn about relaxation, then relax by Southfury River in the Northern Barrens. Progress: True love is letting ya guard down. Let yourself relax, you'll see what I mean.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927, 210929 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 214592, ["x"] = 0.71, ["y"] = 0.14 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1, 10 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78992] = { ["id"] = 78992, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78992 }, ["description"] = "If it's a challenge you're after, I think I have an idea. I saw a boastful champion heading toward Razor Hill. You could challenge him to a duel. This would satisfy your desire and perhaps teach him a valuable lesson in humility.", ["objectivesText"] = "Defeat Poggchug Ragethrower in a duel near the road to Razor Hill. Progress: How fares your challenge?", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[78993] = { ["id"] = 78993, ["name"] = "Loving Yourself, Your Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 78993 }, ["description"] = "A full belly is a happy belly! There is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", ["objectivesText"] = "Consume Packages of treats from vendors at the Gala of Gifts. Progress: Have you had your fill of treats? I love the fruits, myself.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 49927 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 214591, ["x"] = 0.418, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3027 } },
[79074] = { ["id"] = 79074, ["name"] = "Summoning All Soldiers!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79074 }, ["description"] = "The Artisan's Consortium has struck one final deal with the quartermasters of the Gladiator's Refuge! In addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas! Present this brochure to Calderax to receive two complimentary Trophies of Conquest, on us! - Rabul", ["objectivesText"] = "Deliver the brochure to Calderax in the Gladiator's Refuge of Valdrakken .", ["rewardItems"] = { 211685, 211686, 211690 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 199599, ["x"] = 0.444667, ["y"] = 0.366667 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.444667, ["y"] = 0.366667 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["startItems"] = { 211690 } },
[79127] = { ["id"] = 79127, ["name"] = "The Outland Cup Begins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 1519, ["mapID"] = 87, ["storyline"] = { 79127 }, ["series"] = { 78040, 78047, 79125, 79126, 79128 }, ["description"] = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", ["objectivesText"] = "Visit Lord Andestrasz in Stormwind.", ["rewardGold"] = 34100, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 214022, ["x"] = 0.285, ["y"] = 0.67925 }, { ["mapID"] = 84, ["npcID"] = 214031, ["x"] = 0.618, ["y"] = 0.7505 }, { ["mapID"] = 1161, ["npcID"] = 214095, ["x"] = 0.678, ["y"] = 0.182 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 214111, ["x"] = 0.6, ["y"] = 0.663 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.67925 }, ["mapCandidates"] = { ["npc"] = { 84, 87, 1161, 2339 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
