[79178] = { ["id"] = 79178, ["name"] = "Play Hearthstone!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79178 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 211965, 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79184] = { ["id"] = 79184, ["name"] = "It's Hearthstone's Anniversary!", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79184 }, ["description"] = "\"Hearthstone's been played for ten years, can you believe it? I'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us! -Farala, Master of Ceremonies\"", ["objectivesText"] = "Speak with M.C. Farala in Valdrakken, in the Seat of the Aspects.", ["rewardGold"] = 33500, ["rewardItems"] = { 212154 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
