[79199] = { ["id"] = 79199, ["name"] = "Renowned with Keg Leg's Crew", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = { "emissary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 79199 }, ["description"] = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer! Return to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", ["objectivesText"] = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", ["rewardItems"] = { 204378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
