[79321] = { ["id"] = 79321, ["name"] = "The Catalyst's Gift", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2022, ["storyline"] = { 79321 }, ["description"] = "I have an urgent message for you, adventurer. The Revival Catalyst seems to be responding to the land's rumblings--perhaps even your feats! Miraculously, it now shares its power for nothing in return except one's mere presence. Antuka will know more. Go with haste, $p. This is wondrous news.", ["objectivesText"] = "Speak to Antuka in Tyrhold.", ["rewardGold"] = 30900, ["starts"] = { { ["mapID"] = 2022, ["npcID"] = 199336, ["x"] = 0.765, ["y"] = 0.342 }, { ["mapID"] = 2112, ["npcID"] = 213930, ["x"] = 0.48, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 2025, ["npcID"] = 198695, ["x"] = 0.606, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 2022, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 2022, 2025, 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112 },
[79322] = { ["id"] = 79322, ["name"] = "What the Duck?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79322 }, ["description"] = "What the--why are all these ducks here? Something has them agitated. They almost knocked over my beautiful golden egg heirloom! We need to clear out these chaotic quackers so we can continue our festivities. I'll keep them from entering the inn, but can you help clear out the rest?", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Show those ducks who's boss!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45072, 210558, 210594, 212599, 212608, 212643, 213428, 216874, 216881 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[79323] = { ["id"] = 79323, ["name"] = "A Fowl Concoction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79323 }, ["description"] = "We need to put an end to this duck invasion. While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My precious heirloom was among the items stolen! Please, <name>. I won't stand for these pilfering poultry. I know a mage in Stormwind who might have some ideas on how to handle this.", ["objectivesText"] = "Speak with Emmery Fiske at the Wizard's Sanctum in Stormwind. Progress: Have you spoken with Emmery yet?", ["rewardItems"] = { 45072 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[79330] = { ["id"] = 79330, ["name"] = "Duck Tales", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79330 }, ["description"] = "Take this potion, <name>. You should be able to communicate with your feathery friends with it. But don't blame me for any unintended side effects you may experience.", ["objectivesText"] = "Use the potion to get information from 5 ducks. Progress: Go on now, have a chat with those ducks!", ["rewardItems"] = { 45072, 212608 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 216129, ["x"] = 0.42, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[79331] = { ["id"] = 79331, ["name"] = "Just a Waddle Away", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 79331 }, ["description"] = "We need to find out where those ducks are hiding our stolen goods! And who this mysterious Daetan is, while we're at it. I convinced Emmery to give me more of that potion. Take it and find my heirloom!", ["objectivesText"] = "Discover the duck's hiding spot. Progress: Where would those ducks be hiding...", ["rewardGold"] = 309800, ["rewardItems"] = { 45072, 210594, 212599, 212608, 212643, 213428, 216874, 216881, 216890, 216897, 216898, 216900, 216901, 216902 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 211646, ["x"] = 0.42, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[79350] = { ["id"] = 79350, ["name"] = "Intro Dummy Quest Week 1 (Text Only)", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["storyline"] = { 79350 }, ["description"] = "I am chuffed you are helping us with this venture that is so close to my heart. As a lad, I loved dragons--as young children do--and was smitten with Sindragosa. I read all I could about her. When the Dragon Isles opened, I begged the Algeth'ar Academy to let me study the many volumes of Sindragosa's memoirs. In them found a brief mention of a battle at Traitor's Rest. The Blue Dragons are staying mum, but clues to an epic story are all about here! I must know what happened here. For Sindragosa", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[79432] = { ["id"] = 79432, ["name"] = "It's About Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 371, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["series"] = { 79433, 79434, 79435, 79438, 79440, 80380 }, ["description"] = "Your timing is serendipitous. I require your assistance. Not all infinites have seen what Nozdormu has shown me. Not all would agree even if they had. Archaios is one such detractor. He must be eliminated.", ["objectivesText"] = "Slay Archaios the Artificer . Progress: The other infinites jeopardize our mission. We cannot let them wreak havoc on the timeways.", ["rewardGold"] = 48350, ["rewardXP"] = 1415, ["rewardItems"] = { 213631 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 216591, ["x"] = 0.364, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 216591, ["x"] = 0.364, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 0, ["flags"] = 0 } } },
[79433] = { ["id"] = 79433, ["name"] = "Seeking Expert Advice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 371, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["series"] = { 79432, 79434, 79435, 79438, 79440, 80380 }, ["description"] = "Take this spool to Moratari . Perhaps she can make sense of this relic.", ["objectivesText"] = "Speak with Moratari . Provided item:", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 213631 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 216591, ["x"] = 0.364, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 371, 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 1, ["flags"] = 0 } } },
[79434] = { ["id"] = 79434, ["name"] = "Weave It To Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["series"] = { 79432, 79433, 79435, 79438, 79440, 80380 }, ["description"] = "The other infinites are not as judicious in their treatment of the timeline. They have rather torn through time in their reckless opposition to our efforts. Though we cannot simply mend the timeways, we may yet repurpose its loose threads. Reclaim the threads of time from our enemies and we shall weave you a cloak worthy of the Infinite Dragonflight.", ["objectivesText"] = "Collect 3 Threads of Time from Infinite Ravagers. Progress: It is our duty as responsible scholars to clean up after ourselves... and others. < Moratari glances toward the distant ravagers with an annoyed expression.> We cannot let stray threads continue to create temporal anomalies.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 198609, 213571, 225571, 226103, 239125, 250769 }, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.255333, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 2, ["flags"] = 0 } } },
[79435] = { ["id"] = 79435, ["name"] = "What's Hours Is Yours", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["series"] = { 79432, 79433, 79434, 79438, 79440, 80380 }, ["description"] = "Horos , our antiquities collector, should have a chronobadge you can use to fasten together the temporal threads you collected. With the chronobadge, Momentus can craft the threads into a powerful cloak for you to wear!", ["objectivesText"] = "Purchase a Chronobadge from Horos , then speak with Momentus. Progress: That cloak will be able to absorb loose threads of time, adding them to its own magic. The prospect of infinite power is enticing, is it not? Just don't let it go to your head. Let it go to your cloak instead! < Moratari giggles.>", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 210333, 215442 }, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.255333, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 4, ["flags"] = 0 } } },
[79437] = { ["id"] = 79437, ["name"] = "Knot My Problem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["description"] = "These temporal anomalies are getting out of control. Normally, our research does not unravel the timeline this much--I suspect the other infinites are to blame. Use this chronostabilizer to zip up the frayed rifts. Be aware--this may briefly create even more anomalies. I trust you know how to handle them.", ["objectivesText"] = "Use the Chronostabilizer to close 3 Time Rifts . Progress: Every moment moves us toward a new possibility. With every fight, we learn and change.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 215110 }, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.255333, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 3, ["flags"] = 0 } } },
[79438] = { ["id"] = 79438, ["name"] = "Goodbyes Are Hard When You Live Forever", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["series"] = { 79432, 79433, 79434, 79435, 79440, 80380 }, ["description"] = "We have one last anomaly to deal with here before we can study the history of Pandaria. Help us stabilize the timeway and secure our mission.", ["objectivesText"] = "Defeat Eratus, the Unwoven Paradox . Progress: Dealing with paradoxes can be difficult, but these are the risks we accept.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 218129, ["x"] = 0.257667, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.255333, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 6, ["flags"] = 0 } } },
[79440] = { ["id"] = 79440, ["name"] = "Recalling the War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79440 }, ["series"] = { 79432, 79433, 79434, 79435, 79438, 80380 }, ["description"] = "Our operations here are secure. For now, anyway! It is time for you to begin your journey to the past so that we may observe how history unfolded. Speak with Eternus if you have any final questions about our mission. She can show you how these events began.", ["objectivesText"] = "Ask Eternus to show you the events of the past.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 218129, ["x"] = 0.257667, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 216591, ["x"] = 0.364, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.257667, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 371, 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[79448] = { ["id"] = 79448, ["name"] = "Leave No Flightstone Unturned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79448, 79453 }, ["description"] = "It's so exciting to be in Valdrakken! Cuzolth and I have never been here before. And it's everything we hoped it would be. Some of the others have even introduced themselves. They actually thanked us for our work studying Flightstones and Crests. That's every researcher's dream! So I need your help again. Could you find some Flightstones and a new piece of adventuring gear? Then come back to Cuzolth for an upgrade? It would really help us solidify our new position here.", ["objectivesText"] = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 4 equipment using Flightstones . Progress: There's no need to hurry. But if you wouldn't mind hurrying anyway...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5537, ["name"] = "10.2.6 Upgrade System Tutorial", ["orderIndex"] = 0, ["flags"] = 0 } } },
[79453] = { ["id"] = 79453, ["name"] = "Awakened Crests, Unlimited Possibilities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79448, 79453 }, ["description"] = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here. Of course, I'm sure you know that Flightstones can only go so far. You need Awakened Crests to upgrade powerful adventuring gear. Much like Flightstones, these Crests are rewarded through many different activities. Awakened Crests have four tiers, and more dangerous tasks reward you with higher-tier crests. Bring me fifteen Whelpling's Awakened Crests, and we can help you upgrade some gear further.", ["objectivesText"] = "Acquire 15 Whelpling's Awakened Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then return to Vaskarn in Valdrakken. Progress: If you're having a hard time finding Whelpling's Awakened Crests, you can search for hidden treasures around the Dragon Isles. There's no shortage of those!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 211951, 212458 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216449, ["x"] = 0.455, ["y"] = 0.5565 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.5565 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2112, ["questLines"] = { { ["id"] = 5537, ["name"] = "10.2.6 Upgrade System Tutorial", ["orderIndex"] = 1, ["flags"] = 0 } } },
[79511] = { ["id"] = 79511, ["name"] = "Identity Crisis", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79511 }, ["description"] = "Hey $p, over here! I just finished speaking with Emberthal. I'm not sure what, but something is bothering her! She had lots of odd questions about visage forms. Could she be ready to choose one? How exciting! I think I saw her head over to the Victorious Visage. You should check on her, I bet you could get her to spill the secret!", ["objectivesText"] = "Speak with Emberthal in the Victorious Visage.", ["rewardGold"] = 29500, ["rewardXP"] = 1190, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216946, ["x"] = 0.403714, ["y"] = 0.557429 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216945, ["x"] = 0.295, ["y"] = 0.4965 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.403714, ["y"] = 0.557429 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79512] = { ["id"] = 79512, ["name"] = "Who Are You?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79512 }, ["description"] = "Perhaps Cindrethresh is right. Still, if I'm to pick a visage, I should at least give it some thought. I just do not fully understand the concept of visage forms. I have heard that visage is supposed to be ones own expression of self. How does one discover what that is? Maybe some of the individuals here in Valdrakken hold the answers. $p, I need you to gather intel. I will remain here. Report back your findings when you are finished.", ["objectivesText"] = "Speak with 9 Valdrakken Visitors in Valdrakken. Progress: Have you completed your reconnaissance yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216945, ["x"] = 0.295, ["y"] = 0.4965 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216945, ["x"] = 0.295, ["y"] = 0.4965 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.4965 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79513] = { ["id"] = 79513, ["name"] = "Dragon Isles Adventuring: Being Yourself", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79513 }, ["description"] = "I worry about Emberthal. Her mood has grown increasingly dark. By sticking to citizens of the city, she is looking for ways she is similar to them, instead of what makes her unique. Perhaps a broader sample size is in order? She needs stories to guide her. There are many such individuals with stories to tell in the Dragon Isles . Go, and speak with them. Would that I could go myself, but the duties of a Scalecommander never rest.", ["objectivesText"] = "Speak with 8 residents of the Dragon Isles and listen to their stories. Progress: Have you spoken with everyone?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 210469 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216950, ["x"] = 0.295, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216950, ["x"] = 0.295, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79514] = { ["id"] = 79514, ["name"] = "Don't Threaten Me With a Good Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79514 }, ["description"] = "Emberthal seems worried, but I'm sure she'll come back. And when she does, she'll pick a visage form! Chromie told us all about the celebrations dragons used to have for Visage Day. So, Kalecgos and I are going to blow stuff up! Fireworks, mostly. We'll need some arcane residue to make them, though. Conveniently, there are some arcane elementals just outside the Gardens of Unity that are ripe for the harvest. The three of us have some other preparations to make here in Valdrakken.", ["objectivesText"] = "Collect 100 Arcane Residue from Volatile Arcana in The Cascades. Progress: These volatile elementals make the perfect base for fireworks!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 217348 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216967, ["x"] = 0.295, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216967, ["x"] = 0.295, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79515] = { ["id"] = 79515, ["name"] = "Gather Your Rosebuds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 79515 }, ["description"] = "Emberthal is quite troubled. It reminds me of a certain bronze dragon when she chose her visage form. Not to worry! Once Emberthal has returned, we shall throw a proper Visage Day celebration. The fireworks are to match the colors of the dragonflights. Each enclave of the city grows special flowers in accordance with that enclave's flight. Three of each color should be enough for the first batch of fireworks.", ["objectivesText"] = "Collect 3 of each color of Flight Flower in Valdrakken. Progress: We still require more flowers if we are to provide a celebration worthy of dragons.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 224296 }, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216951, ["x"] = 0.3032, ["y"] = 0.4644 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 216951, ["x"] = 0.3032, ["y"] = 0.4644 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.3032, ["y"] = 0.4644 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79558] = { ["id"] = 79558, ["name"] = "Feathered Fiend", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79558 }, ["description"] = "The trinket appears to be a Noblegarden decoration of sorts. You should return this to the festivities at Razor Hill.", ["objectivesText"] = "Bring the Noblegarden Trinket to Sylnaria Fareflame at Razor Hill.", ["rewardItems"] = { 210594, 212599, 212698, 212699, 212701, 212711, 212715, 212985, 213428, 216874, 216932 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 }, ["startItems"] = { 216932 } },
[79575] = { ["id"] = 79575, ["name"] = "What the Duck?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79575 }, ["description"] = "I cannot work under these conditions! Something has all these silly ducks in an uproar--they nearly upended my precious golden egg! These chaotic quackers simply must be dealt with! I can keep them from entering the inn, but will you please help clear out the rest?", ["objectivesText"] = "Scare off 10 ducks using the Horn of Honking . Progress: Shoo! Shoo! ...have you shooed them all yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 45072, 216487 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79576] = { ["id"] = 79576, ["name"] = "A Fowl Concoction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79576 }, ["description"] = "My egg! My precious egg! While I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My beautiful golden heirloom was among the items stolen! Enough is enough. We simply must put an end to this duck invasion. Please, <name>. These pilfering poultry must be stopped! Fortunately, I know a mage in Orgrimmar who might just have a solution for us.", ["objectivesText"] = "Speak with Tethris Dewgazer at the Pathfinder's Den in Orgrimmar. Progress: Have you spoken with Tethris yet?", ["rewardItems"] = { 45072, 216881 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79577] = { ["id"] = 79577, ["name"] = "Duck Tales", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79577 }, ["description"] = "Take this potion, <name>. Drink it, and you should be able to chit chat with those feathery fiends. Oh, but if you happen to experience any... unintended side effects, don't blame me.", ["objectivesText"] = "Use the potion to get information from 5 ducks. Progress: Have they said anything interesting?", ["rewardItems"] = { 45072, 216488, 216881 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217147, ["x"] = 0.525, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79578] = { ["id"] = 79578, ["name"] = "Just a Waddle Away", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 9, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 79578 }, ["description"] = "We simply must find out where those ducks are hiding our stolen goods--and my precious egg! Oh, and who this mysterious Daetan is, of course. I convinced Tethris to give me more of that potion. Take it and bring back my golden heirloom!", ["objectivesText"] = "Discover the duck's hiding spot. Progress: Where would those ducks be hiding...", ["rewardGold"] = 309800, ["rewardItems"] = { 45072, 212599, 212608, 212643, 213428, 216488, 216489, 216874, 216881, 216890, 216897, 216898, 216900, 216901, 216902, 216932 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 217125, ["x"] = 0.525, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[79693] = { ["id"] = 79693, ["name"] = "Play Hearthstone!", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79693 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79694] = { ["id"] = 79694, ["name"] = "Play Hearthstone!", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 1, ["storyline"] = { 79694 }, ["description"] = "It's time to play Hearthstone! Here's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play! Or if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", ["objectivesText"] = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table. Progress: Like the game so far? Give it a chance and play those cards!", ["rewardGold"] = 31500, ["rewardItems"] = { 212979 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 215409, ["x"] = 0.53, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
[79989] = { ["id"] = 79989, ["name"] = "An Ancient Awakening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13646, ["mapID"] = 2024, ["storyline"] = { 79989 }, ["description"] = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks. That amount of unstable energy being released could be catastrophic. Shall we continue?", ["objectivesText"] = "Empower the Waygate.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 198858 }, ["starts"] = { { ["mapID"] = 2024, ["npcID"] = 189764, ["x"] = 0.4968, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 2022, ["npcID"] = 189066, ["x"] = 0.472, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 2024, ["source"] = "quest_giver", ["x"] = 0.4968, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 2022, 2024 }, ["zone"] = { 13646 } }, ["questType"] = "standard" },
[80012] = { ["id"] = 80012, ["name"] = "Skyriding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "This land is more vast than I remember. However, a good scholar always prepares for contingencies. Two of the most airborne dragons have agreed to aid our cause. They will provide a winged mount so you may cover more ground. I will send you to Lord Andestrasz . He shall instruct you further.", ["objectivesText"] = "Take Moratari 's portal to Lord Andestrasz . Progress: All things come with practice.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 194034 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218468, ["x"] = 0.342667, ["y"] = 0.375333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.342667, ["y"] = 0.375333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 0, ["flags"] = 0 } } },
[80013] = { ["id"] = 80013, ["name"] = "How to Glide with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "Let us start with the basics. If you fly straight you will wear yourself out right now. Use gravity as an aid and aim slightly down to fly a long distance. The rings will give you the general angle that you should use for basic gliding. First, call upon your drake, or our Red Drake friend here can give you a lift. Then, fly through the rings and land at the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Summon your dragonriding mount, or mount the Red Drake . Then glide through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 2, ["flags"] = 0 } } },
[80015] = { ["id"] = 80015, ["name"] = "How to Dive with Your Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "Gliding will get you to where you want to go. But what if you want to get there faster? Diving after jumping from somewhere high will give you a speed boost. As long as you fly well, you can conserve your momentum and gain some height after a dive. Fly through the rings to the target location. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Dive then glide through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 3, ["flags"] = 0 } } },
[80016] = { ["id"] = 80016, ["name"] = "The Need For Higher Velocities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "Sometimes you'll need to travel longer distances. If you don't need to travel up and over any obstacles, using Surge Forward is the easiest way to maintain a good forward speed to prevent yourself from plummeting out of the sky. Follow the rings again to your destination and use Surge Forward when prompted to maintain your speed. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Fly through the rings and land in the target area. Progress: Well done, <name>.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 4, ["flags"] = 0 } } },
[80017] = { ["id"] = 80017, ["name"] = "The Need For Higher Altitudes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["description"] = "To gain height, use Skyward Ascent. Follow the rings again to your destination, using Skyward Ascent when you need upward momentum. If you find yourself stuck, use the Bronze Timepiece and Celormu will reset you.", ["objectivesText"] = "Fly through the rings and land in the target area. Progress: Well done, <name>.", ["rewardItems"] = { 216712 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218470, ["x"] = 0.6508, ["y"] = 0.3456 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 5, ["flags"] = 0 } } },
[80018] = { ["id"] = 80018, ["name"] = "Fashionable Flying", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80012, 80013, 80015, 80016, 80017, 80018, 90754 }, ["series"] = { 80349 }, ["description"] = "You have learned all I can teach you. But flying isn't just about getting to your destination--it's about getting there in style! Use the Rostrum of Transformation behind you to customize your drake's appearance.", ["objectivesText"] = "Use the Rostrum of Transformation. Progress: How do you like your look?", ["rewardItems"] = { 2778 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5546, ["name"] = "Introduction to Skyriding", ["orderIndex"] = 6, ["flags"] = 0 } } },
[80069] = { ["id"] = 80069, ["name"] = "Tears of Teldrassil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "I have carried this weight long enough. It has finally come time to put my family to rest. Even if I never found my sister... < Kelestra wipes away tears and takes a deep breath.> I must gather barrowstones to place at their final resting place. But I simply cannot carry that many stones. Maybe I ask too much of a stranger, but would you assist me? I know having someone beside me will make this more endurable.", ["objectivesText"] = "Follow Kelestra and collect barrowstones to help her memorialize her family. Progress: < Kelestra looks distraught, and her hands are shaking.> I can not parse my feelings. My sister is alive, but a traitor. And what did he mean she deserved her fate? Please Koroleth, let this finally be our time to reunite.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218623, ["x"] = 0.7255, ["y"] = 0.7305 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218697, ["x"] = 0.728, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.7255, ["y"] = 0.7305 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 1, ["flags"] = 0 } } },
[80071] = { ["id"] = 80071, ["name"] = "Fact Finding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "I must speak with the Primalists. I don't understand why she would turn her back on us. Koroleth saved my life at Teldrassil. I owe it to her to find out the truth. <name>, I realize this might be awkward, but will you help me? I can no longer bear this alone.", ["objectivesText"] = "Meet Kelestra at the Twilight Watchtower.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218697, ["x"] = 0.728, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 2, ["flags"] = 0 } } },
[80072] = { ["id"] = 80072, ["name"] = "A Primalist Point of View", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "Warden Malathra has granted us permission to speak with the Primalists. They might have switched sides, but the wardens are keeping a close eye on them. < Kelestra begins to look distressed.> I'm going to talk to the Warden more. Could you handle the Primalists? All of this about Koroleth is just happening so suddenly. I feel we should gather as much information as we can.", ["objectivesText"] = "Speak to the reformed Primalists about Koroleth. Progress: I want to talk to them, but I don't even know where to begin.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 3, ["flags"] = 0 } } },
[80073] = { ["id"] = 80073, ["name"] = "Bones of a Bygone Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "After speaking with the warden, I learned the Battle of the Barrier where my sister fell took place east of here, on the shores of the Ohn'ahran Plains. I understand her body was washed out to sea and never recovered. It's possible the tide brought her remains back to shore at some point. Will you help me look for her? Each member of my family has a necklace with this distinct design. It will identify Koroleth's body. I would like to lay her to rest with the family she loved.", ["objectivesText"] = "Search the shoreline of the Ancient Bough for Koroleth's remains. Progress: Is this the necklace you found?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 217003 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218698, ["x"] = 0.336, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218701, ["x"] = 0.888, ["y"] = 0.208 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2023, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 4, ["flags"] = 0 } } },
[80075] = { ["id"] = 80075, ["name"] = "A Barrow Den Burial", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "All that is left to do is to gather my sister's remains and bring them to the barrow den. Please meet me there, <name>. I could use a friend.", ["objectivesText"] = "Meet Kelestra outside the barrow den at the Fields of Reverie.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218701, ["x"] = 0.888, ["y"] = 0.208 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218785, ["x"] = 0.722, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.888, ["y"] = 0.208 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 5, ["flags"] = 0 } } },
[80077] = { ["id"] = 80077, ["name"] = "Sins of the Sister", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "This druid is trying to convince Malfurion not to let me bury my sister here with the rest of my family. He won't even let me get a word in. < Kelestra tightly clutches the straps of her backpack holding her sister's remains.> I know I have asked a lot of you already. Could you talk to them? Perhaps they might listen to you?", ["objectivesText"] = "Speak with Malfurion Stormrage about Koroleth's remains. Progress: <Malfurion is deep in thought.>", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 223146 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 218785, ["x"] = 0.722, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218629, ["x"] = 0.722, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 6, ["flags"] = 0 } } },
[80196] = { ["id"] = 80196, ["name"] = "Extract a Gem", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["storyline"] = { 80196 }, ["series"] = { 79489, 80197 }, ["description"] = "Any gem can be removed from your equipment using the Extract Gem ability. The gem will not be destroyed. Extract a gem now.", ["objectivesText"] = "Extract the Chipped Deadly Sapphire from your equipment.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 210714 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
