[80310] = { ["id"] = 80310, ["name"] = "Setting Sun Garrison", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 80310 }, ["description"] = "Might you be willing to find Anji at the Setting Sun Garrison to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", ["objectivesText"] = "Speak to Anji Autumnlight at the Setting Sun Garrison.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 390, ["npcID"] = 64007, ["x"] = 0.63, ["y"] = 0.222 }, { ["mapID"] = 390, ["npcID"] = 64031, ["x"] = 0.847333, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 390, ["npcID"] = 58919, ["x"] = 0.214667, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 390, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 390 }, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[80311] = { ["id"] = 80311, ["name"] = "Order of the Cloud Serpent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30134, 30135, 30136, 30137, 30138, 30139, 30140, 30141, 30142, 30143, 30144, 30145, 30187, 30188, 31810, 31811, 80311 }, ["series"] = { 30134, 30135 }, ["description"] = "Widing toortles is da best! But widing cloud serpents is even better! There's some peepos at da Arboweetum who wide cloud serpents and can teach you how!", ["objectivesText"] = "Speak to Elder Anli at The Arboretum.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 211279, 223907 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 63900, ["x"] = 0.49, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 58564, ["x"] = 0.576, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 0, ["flags"] = 0 } } },
