[80349] = { ["id"] = 80349, ["name"] = "Time to Return", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 80349 }, ["series"] = { 80018 }, ["description"] = "You'd best be on your way now. That portal should take you back to the village.", ["objectivesText"] = "Return to Moratari .", ["starts"] = { { ["mapID"] = 371, ["npcID"] = 218469, ["x"] = 0.652, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 218468, ["x"] = 0.342667, ["y"] = 0.375333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[80380] = { ["id"] = 80380, ["name"] = "Cloak and Needle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 79432, 79433, 79434, 79435, 79437, 79438, 80380 }, ["series"] = { 79432, 79433, 79434, 79435, 79438, 79440 }, ["description"] = "Once you don your cloak, you will be able to find threads on any enemy. The cloak will naturally absorb those threads, permanently increasing your power. Try collecting a thread from the nearby Infinite Ravagers.", ["objectivesText"] = "Equip your Cloak of Infinite Potential and collect a Thread of Power from an Infinite Ravager. Progress: You need not be a tailor. The cloak will weave threads for you.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 216594, ["x"] = 0.255333, ["y"] = 0.515333 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.255333, ["y"] = 0.515333 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 554, ["questLines"] = { { ["id"] = 5536, ["name"] = "Timerunning: Mists of Pandaria", ["orderIndex"] = 5, ["flags"] = 0 } } },
[80384] = { ["id"] = 80384, ["name"] = "A Keg-Stamped Package", ["level"] = 70, ["requiredLevel"] = 70, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 80384 }, ["description"] = "<A note, attached to a small and crumpled package, is shoved into your hands by a nondescript figure. Just as quickly, they disappear into the crowd. The letters on the note are scrawled crudely, as if by a dagger dipped in ink.> Here's yer share of the plunder. Sent the mates to the inn. <You look around to see if there is anything else on the note. There is a picture of a keg at the bottom. You shake the package gently and hear the telltale sound of coins.>", ["objectivesText"] = "Bring the Keg-Stamped Note to Da'kash Grimledger at the Roasted Ram Inn in Valdrakken .", ["rewardGold"] = 289300, ["rewardXP"] = 9515, ["rewardItems"] = { 217397 }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 219760, ["x"] = 0.466, ["y"] = 0.455333 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.455333 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
