[82080] = { ["id"] = 82080, ["name"] = "More Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 82080 }, ["description"] = "Hello, fire juggler! Are you having fun and making fiery mayhem? That's what I like to hear! Now, do you think you're an expert at torch tossing? Then I have a test for you... You know the rules: toss torches at the marked braziers. This time, however, you are timed and have a LOT more braziers to hit. Ready?", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 252720, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3459 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97 },
[82087] = { ["id"] = 82087, ["name"] = "Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 9, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 82087 }, ["series"] = { 11657, 11731 }, ["description"] = "So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! Stand near the bonfire and you'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers, then come back here... for your next lesson.", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3459 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97 },
[82105] = { ["id"] = 82105, ["name"] = "Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 9, ["zoneID"] = 3487, ["mapID"] = 18, ["storyline"] = { 82105 }, ["series"] = { 11922, 11923 }, ["description"] = "So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! As you approach the bonfire you'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers then come back here... for your next lesson.", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Flame Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3459 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[82109] = { ["id"] = 82109, ["name"] = "More Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 9, ["zoneID"] = 3487, ["mapID"] = 18, ["storyline"] = { 82109 }, ["description"] = "Hello, fire juggler! Are you having fun and making fiery mayhem? That's what I like to hear! Now, do you think you're an expert at torch tossing? Then I have a test for you... You know the rules: toss torches at the marked braziers. This time, however, you have a little more time and a LOT more braziers to hit. Ready?", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Flame Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3459 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110 },
[82229] = { ["id"] = 82229, ["name"] = "An Uncommon Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 15105, ["mapID"] = 2239, ["storyline"] = { 80069, 80071, 80072, 80073, 80075, 80077, 82229 }, ["description"] = "<name>, welcome to Bel'ameth. I wonder -- do you have time for a small favor? Earlier today, a young kaldorei named Kelestra came to see me. She sought permission to bury her family in a barrow den. An uncommon request, but I gave her my blessing and directed her to the Barrows of Reverie. She looked... melancholy. After she left, it struck me that she might be the last of her family still alive. If you have the time, could you check on her?", ["objectivesText"] = "Meet Kelestra in the Barrows of Reverie.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 223146 }, ["starts"] = { { ["mapID"] = 2239, ["npcID"] = 216069, ["x"] = 0.4925, ["y"] = 0.6815 } }, ["ends"] = { { ["mapID"] = 2239, ["npcID"] = 218623, ["x"] = 0.7255, ["y"] = 0.7305 } }, ["coords"] = { ["mapID"] = 2239, ["source"] = "quest_giver", ["x"] = 0.4925, ["y"] = 0.6815 }, ["mapCandidates"] = { ["npc"] = { 2239 }, ["zone"] = { 15105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2444, ["db2PoiUiMapID"] = 2239, ["questLines"] = { { ["id"] = 5547, ["name"] = "Sins of the Sister", ["orderIndex"] = 0, ["flags"] = 0 } } },
[82762] = { ["id"] = 82762, ["name"] = "Keeping a Close Tabard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 9, ["zoneID"] = 13862, ["mapID"] = 2112, ["storyline"] = { 82762 }, ["description"] = "Wow! That's a super nifty tabard! And it's all yours to customize however you want. Kessa should be able to help you bring your designs to life. Go ahead and pay her a visit to get started!", ["objectivesText"] = "Speak with Kessa in the Victorious Visage. Progress: Kessa is a very skilled tabard designer!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 2112, ["npcID"] = 216946, ["x"] = 0.403714, ["y"] = 0.557429 } }, ["ends"] = { { ["mapID"] = 2112, ["npcID"] = 224600, ["x"] = 0.295, ["y"] = 0.473 } }, ["coords"] = { ["mapID"] = 2112, ["source"] = "quest_giver", ["x"] = 0.403714, ["y"] = 0.557429 }, ["mapCandidates"] = { ["npc"] = { 2112 }, ["zone"] = { 13862 } }, ["questType"] = "standard" },
